schemas.schema-09-inquiries.prisma:
/// Support Ticket Entity - This implements the service support and inquiry feature requirements from the backend requirements analysis, particularly relating to customer service workflows and support escalation (see EARS statements about ticketing, AI escalation, and compliance logging). 
/// This table models customer-initiated service requests—used for tracking issues, questions, and operational problems faced by customers, sellers, or administrators. It enables robust, auditable support workflows and links to related users by foreign keys (referencing pre-existing user tables). Maintains full 3NF normalization: All attribute data is atomic, and references are by foreign keys only. No pre-calculated or summary fields are present. Key relationships: links (via foreign keys) to users (customers, sellers, admins) in already-existing tables; referenced by audit/logging modules in other schemas. Special behaviors: status transitions (open, assigned, resolved, closed); fully audit-trailed via timestamp fields; supports escalation, categorization, and assignment. Sensitive information must be subject to compliance logging.
///
/// @namespace Inquiries
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_support_tickets {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each support ticket.
  id String @id @db.Uuid

  /// User's {@link aimall_backend_customers.id}, {@link aimall_backend_sellers.id}, or {@link aimall_backend_administrators.id} who created the support ticket. Enables reference to the actor initiating the ticket for compliance and support workflow.
  requester_id String @db.Uuid

  /// Assigned admin's {@link aimall_backend_administrators.id}, if a ticket has been assigned to a staff member for handling. Tracks responsibility delegation in support workflow.
  assignee_admin_id String? @db.Uuid

  /// Support ticket subject line - Implements the summary/short title requirement. Business meaning: customer-provided or system-generated one-line description for ticket triage (e.g., 'Order not received', 'Billing error'). Atomic, required for efficient ticket queue management.
  subject String

  /// Support ticket full request detail - Implements the main description field. This is the message or inquiry provided by the user, containing all specifics of the case. Must be stored as a string (may contain markup/HTML). Strictly atomic and normalized.
  body String

  /// Ticket status - Implements the workflow state for tracking open, pending, resolved, or closed support requests. Suggested enum values: 'open', 'pending', 'resolved', 'closed', but allows string for forward-compatibility with workflow engines. Always atomic and only represents the current state, not calculated. Used for ticket queue filtering.
  status String

  /// Priority flag (e.g., 'low','normal','high','urgent') - Implements support triage requirement. Indicates urgency for staff response and routing. Not calculated; strictly atomic and can be updated per ticket system business rules.
  priority String

  /// Ticket category - Implements requirement for classification/tagging (e.g., 'payment', 'delivery', 'product', 'technical', 'account') for reporting, agent assignment, and workflow. Always atomic and reflects user/system selection upon ticket submission.
  category String

  /// Ticket creation timestamp - Implements requirement for audit trails, SLAs, and tracking. Indicates when the ticket was submitted. Not nullable per compliance requirements.
  created_at DateTime @db.Timestamptz

  /// Ticket last update timestamp - Ensures audit log compliance and enables support workflow monitoring (e.g., for SLA violation, escalation checks). Updated on every atomic change to the ticket.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_support_ticket_requester_id      aimall_backend_customers       @relation(fields: [requester_id], references: [id], onDelete: Cascade)
  fk_support_ticket_assignee_admin_id aimall_backend_administrators? @relation(fields: [assignee_admin_id], references: [id], onDelete: Cascade)

  @@unique([requester_id, created_at])
  @@index([status])
  @@index([priority])
  @@index([created_at])
  @@index([assignee_admin_id])
  @@index([subject(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// FAQ Entity - This implements the knowledge base/self-service feature from the requirements, enabling listing and maintaining frequently asked questions to improve user self-resolution and reduce support load (see EARS requirements for knowledge management and ticket deflection). Models a single FAQ record (question-answer pair), fully atomic and referenceable in a normalized fashion. Allows categorization and keyword search. There is no denormalization or calculated data. Example usage: customer accesses FAQ for 'Payment not processed', gets guided advice, reducing incoming support tickets. Key relationships: can be referenced from support tickets (for self-service deflection statistics), links only via reference IDs as required by normalized modeling guidelines. Special behaviors: supports category-tag filtering, allows soft update of content/visibility for compliance (e.g. hiding outdated answers).
///
/// @namespace Inquiries
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_faqs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each FAQ entry.
  id String @id @db.Uuid

  /// FAQ question - Implements requirement for FAQ knowledge base questions. Short, atomic, and searchable (used as main text for user lookup).
  question String

  /// FAQ answer - Implements knowledge base content for most common inquiries. May contain rich/HTML content for effective guidance. Atomic, not calculated, and strictly normalized.
  answer String

  /// FAQ category - Implements requirement for classification/tagging, enabling search and filtering over large FAQ databases. Examples: 'order', 'payment', 'product', 'account'. Strictly atomic and normalized.
  category String

  /// Manual sort order for display - Implements the need for prioritized/ordered FAQ listing (e.g., order by popularity, admin-set priority). Atomic integer, not calculated.
  sort_order Int @db.Integer

  /// Visibility flag - Implements soft hide/archive policy for outdated or admin hidden FAQs. If false, FAQ is hidden from customer view but still exists for audit/compliance records. Fully atomic, normalized.
  visible Boolean

  /// FAQ creation timestamp - For audit log compliance and historical analysis. Indicates when FAQ entry was created/published. Always required; never nullable per compliance tracing.
  created_at DateTime @db.Timestamptz

  /// FAQ last updated timestamp - Maintains revision history compliance; updated on any change to the question or answer. Atomic, not calculated, strictly normalized.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([category])
  @@index([sort_order])
  @@index([visible])
  @@index([question(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([answer(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-10-analytics.prisma:
/// [Analytics Dashboard] - This implements the requirement for centralized analytics dashboards as referenced in the technical architecture and analytics/monitoring requirements documents. This normalized entity represents configuration records for admin-customizable analytics dashboards (e.g., KPIs, fraud monitors). It ensures 3NF by only storing dashboard config data—not pre-aggregated or denormalized metric results. Example use: an admin creates a 'fraud monitoring' dashboard; access rights are managed externally. Supports audit linkage for change tracking via other tables.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_analytics_dashboards {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the analytics dashboard.
  id String @id @db.Uuid

  /// [Dashboard Code] - Unique symbolic identifier for this dashboard (e.g., 'sales-kpi-main'). Used in lookup and linking; ensures no aggregate types are mixed here. Example: Used by admin UI to load dashboard definition by code.
  code String

  /// [Dashboard Title] - Human-readable dashboard name for UI display (e.g., 'Sales Overview'). Atomic string for normalized structure. Example: Appears in dashboard selectors.
  title String

  /// [Dashboard Description] - Optional detailed explanation of dashboard purpose. Example: Used for admin UI tooltips/documentation; null allowed.
  description String?

  /// [Dashboard Config JSON] - Serialized JSON (as string) storing dashboard widget/layout/metrics config. Only configuration is stored here, never calculated results. Example: '{"widgets":[{"type":"chart","metric":"orders_daily"}]}'
  config_json String?

  /// [Created At] - Creation timestamp. Used for sorting/audit; enforced at insert.
  created_at DateTime @db.Timestamptz

  /// [Updated At] - Last modification timestamp for change tracking/audit trail.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([code])
  @@index([created_at])
  @@index([updated_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Audit Log Entity] - Implements the technical/compliance requirement for all key admin/user/system actions and system events. Normalized append-only entity supporting traceable, regulatory-compliant audit trails for the platform (e.g., admin actions, config changes). Each row represents a single event, consistent with 3NF—no aggregates or summaries. Example usage: storing admin logins, permission changes, dashboard edits; deletion/updates forbidden. Relations to actors in otherComponents via actor_id foreign key. Supports full-text search on core event fields.
///
/// @namespace Analytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the audit log event.
  id String @id @db.Uuid

  /// [Actor Reference] - Foreign key referencing the administrator/user (from aimall_backend_administrators) responsible for the event. Key for audit traceability. Allows null for system/automated events. Maintains normalization by reference only, not denormalized actor info.
  actor_id String? @db.Uuid

  /// [Event Type] - Categorical string for the class of event ('LOGIN','PERMISSION_CHANGE','DASHBOARD_UPDATE', etc). Maintains 3NF by only storing atomic type.
  event_type String

  /// [Event Target] - Resource/entity impacted (e.g., dashboard code, configuration key, resource ID). 3NF by only storing atomic identifier, not summary/result.
  event_target String?

  /// [IP Address] - IP the event originated from; atomic string for auditing/admin compliance.
  ip_address String?

  /// [Event Outcome] - Result state of action (e.g., 'SUCCESS', 'FAILED', 'DENIED'). Only stores normalized atomic event outcome.
  outcome String

  /// [Event Detail (JSON)] - Optional raw JSON string (text) giving extended context for the event; not pre-aggregated. E.g., '{"previous_role":"user","new_role":"admin"}'. Null allowed for minimal records.
  detail_json String?

  /// [Event Timestamp] - When this log row was created; used for filtering/reporting. 3NF as atomic event record.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  administrator aimall_backend_administrators? @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([event_type, created_at])
  @@index([actor_id, created_at])
  @@index([event_type(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([event_target(ops: raw("gin_trgm_ops"))], type: Gin)
}

