import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";

/**
 * Validate retrieval of all comments for a post visible to a customer.
 *
 * This test verifies that when a customer requests all comments for a given
 * post:
 *
 * - They see all public comments,
 * - They see their own private comments,
 * - They do NOT see private comments authored by other users.
 *
 * Steps:
 *
 * 1. Create a post as CustomerA (assume authenticated connection is CustomerA)
 * 2. CustomerA leaves a public comment and a private comment
 * 3. Simulate a second user CustomerB by swapping in a new customer connection,
 *    and have CustomerB leave both a public and a private comment
 * 4. Fetch all comments for the post as CustomerA
 * 5. Assert the result contains:
 *
 *    - All public comments
 *    - CustomerA's private comment
 *    - No private comments from CustomerB
 * 6. Verify pagination metadata is present
 */
export async function test_api_aimall_backend_customer_posts_comments_get_all_visible_to_customer(
  connection: api.IConnection,
  connectionB: api.IConnection,
) {
  // 1. CustomerA creates a post.
  const post = await api.functional.aimall_backend.customer.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(3),
        body: RandomGenerator.paragraph()(),
        is_private: false,
      } satisfies IAimallBackendPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. CustomerA leaves public and private comments
  const commentA_pub =
    await api.functional.aimall_backend.customer.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          body: "Visible to everyone!",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(commentA_pub);
  const commentA_priv =
    await api.functional.aimall_backend.customer.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: {
          body: "My private thoughts",
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(commentA_priv);

  // 3. CustomerB (using connectionB) leaves public and private comments
  const commentB_pub =
    await api.functional.aimall_backend.customer.posts.comments.create(
      connectionB,
      {
        postId: post.id,
        body: {
          body: "Greetings from B (public)",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(commentB_pub);
  const commentB_priv =
    await api.functional.aimall_backend.customer.posts.comments.create(
      connectionB,
      {
        postId: post.id,
        body: {
          body: "B's private secret",
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(commentB_priv);

  // 4. Fetch all comments for the post as CustomerA
  const output =
    await api.functional.aimall_backend.customer.posts.comments.index(
      connection,
      { postId: post.id },
    );
  typia.assert(output);

  // 5. Assert visible comments: all public + CustomerA's private, NOT CustomerB's private
  const expectedVisible = [commentA_pub, commentB_pub, commentA_priv];
  for (const expected of expectedVisible) {
    TestValidator.predicate("expected comment is visible")(
      output.data.some((c) => c.id === expected.id),
    );
  }
  TestValidator.predicate("other user's private comment not visible")(
    !output.data.some((c) => c.id === commentB_priv.id),
  );

  // 6. Pagination metadata is present
  TestValidator.predicate("pagination present")(
    typeof output.pagination === "object",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";

/**
 * Validate error handling when retrieving comments for a non-existent post.
 *
 * Business requirement: The comments API should return a 404 or meaningful
 * error if the requested postId does not exist in the system. This test
 * attempts to retrieve comments for a random (presumed not to exist) UUID as
 * postId and asserts the error handling behavior.
 *
 * Steps:
 *
 * 1. Generate a random UUID to use as postId, which is not associated with any
 *    post in the system.
 * 2. Attempt to fetch comments for this postId via the customer comments endpoint.
 * 3. Validate that an error is thrown (404 Not Found or equivalent business error
 *    indicating missing post).
 * 4. (Edge) Ensure no successful response is returned with data.
 */
export async function test_api_aimall_backend_test_get_all_comments_for_post_post_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID not present in the system (assume typia.random() is enough for non-existence).
  const fakePostId = typia.random<string & tags.Format<"uuid">>();

  // 2 & 3. Try to fetch comments and expect an error to be thrown.
  await TestValidator.error(
    "Should return 404 or not found error for missing post",
  )(async () => {
    await api.functional.aimall_backend.customer.posts.comments.index(
      connection,
      { postId: fakePostId },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";

/**
 * Validate endpoint rejection when retrieving post comments as an unauthorized
 * user.
 *
 * This test confirms that the GET
 * /aimall-backend/customer/posts/{postId}/comments endpoint enforces
 * authentication and does not allow anonymous or invalid users to list post
 * comments.
 *
 * Test Workflow:
 *
 * 1. Prepare a random UUID to use as postId (any value is acceptable, as
 *    authorization fails first).
 * 2. Use a connection object with no authentication headers, simulating an
 *    anonymous/unauthorized user.
 * 3. Attempt to call the API to retrieve comments for the given post.
 * 4. Use TestValidator.error to assert that an authentication or permission error
 *    is thrown (401/403).
 */
export async function test_api_aimall_backend_customer_posts_comments_test_get_all_comments_for_post_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Prepare a random UUID as postId (since actual post access is not reached)
  const postId = typia.random<string & tags.Format<"uuid">>();

  // 2-4. Execute and confirm error on unauthenticated access
  await TestValidator.error("Anonymous users cannot retrieve comments")(
    async () => {
      await api.functional.aimall_backend.customer.posts.comments.index(
        connection,
        { postId },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";

/**
 * Validate retrieval of all customer details for a given customerId by
 * administrator.
 *
 * This test ensures that a newly registered customer can be fully retrieved by
 * their unique ID using the administrator endpoint. It verifies all
 * business-critical fields are present and match the registration input,
 * meeting compliance and data integrity requirements.
 *
 * Step-by-step process:
 *
 * 1. Register a new customer (using /aimall-backend/customers endpoint)
 * 2. Capture the generated customerId from creation response
 * 3. As an administrator, retrieve the customer's details by customerId
 * 4. Check that all key fields (id, email, phone, status, audit fields) are
 *    present and match registration data
 * 5. Validate that audit fields (created_at, updated_at) are correctly formatted
 *    date-times
 */
export async function test_api_aimall_backend_administrator_customers_test_get_customer_details_with_valid_customer_id(
  connection: api.IConnection,
) {
  // 1. Register a new customer and capture the resulting entity
  const newCustomerInput: IAimallBackendCustomer.ICreate = {
    email: typia.random<string>(),
    phone: typia.random<string>(),
    password_hash: typia.random<string>(),
    status: "active",
  };
  const createdCustomer: IAimallBackendCustomer =
    await api.functional.aimall_backend.customers.create(connection, {
      body: newCustomerInput,
    });
  typia.assert(createdCustomer);

  // 2. Retrieve the customer's details as administrator
  const fetchedCustomer: IAimallBackendCustomer =
    await api.functional.aimall_backend.administrator.customers.at(connection, {
      customerId: createdCustomer.id,
    });
  typia.assert(fetchedCustomer);

  // 3. Verify field-by-field equivalence for identity and registration fields
  TestValidator.equals("customer id matches")(fetchedCustomer.id)(
    createdCustomer.id,
  );
  TestValidator.equals("customer email matches")(fetchedCustomer.email)(
    createdCustomer.email,
  );
  TestValidator.equals("customer phone matches")(fetchedCustomer.phone)(
    createdCustomer.phone,
  );
  TestValidator.equals("customer status matches")(fetchedCustomer.status)(
    createdCustomer.status,
  );

  // 4. Confirm audit fields exist and have proper ISO 8601 date format
  TestValidator.predicate("created_at is valid ISO date-time")(
    !!fetchedCustomer.created_at &&
      !isNaN(Date.parse(fetchedCustomer.created_at)),
  );
  TestValidator.predicate("updated_at is valid ISO date-time")(
    !!fetchedCustomer.updated_at &&
      !isNaN(Date.parse(fetchedCustomer.updated_at)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";

/**
 * Test handling of invalid customerId when retrieving customer details as an
 * administrator.
 *
 * This test validates that the API correctly returns a 404 Not Found error when
 * attempting to retrieve a customer entity by a UUID that does not correspond
 * to any real record. The goal is to ensure that:
 *
 * 1. The endpoint does not expose any sensitive data or allow enumeration of
 *    customers.
 * 2. The error returned is a 404 and no customer data is present in the response.
 *
 * Steps:
 *
 * 1. Generate a random UUID for a customerId that is assumed not to exist in the
 *    system.
 * 2. Call the administrator get-customer-details endpoint with this invalid ID.
 * 3. Assert that a 404 error is thrown and no data is returned.
 */
export async function test_api_aimall_backend_administrator_customers_test_get_customer_details_with_invalid_customer_id(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID for a non-existent customerId
  const invalidCustomerId: string = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. Attempt to retrieve customer details with this ID and expect failure
  await TestValidator.error("should return 404 for non-existent customerId")(
    async () => {
      await api.functional.aimall_backend.administrator.customers.at(
        connection,
        {
          customerId: invalidCustomerId,
        },
      );
    },
  );
  // 3. No data is leaked if the endpoint works as intended (the thrown error by SDK abstraction will prevent sensitive leaks)
}

