import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendChannel";
import type { IAimallBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSection";

/**
 * Validate that updating a section's code to a value that already exists for
 * another section in the same channel fails.
 *
 * Business context: Each section 'code' in a channel must be unique. This test
 * ensures the API enforces the (channel_id, code) unique constraint on update.
 *
 * Workflow steps:
 *
 * 1. Create a new channel as parent context (channelA).
 * 2. Create section1 under channelA with a unique code (e.g., "main-banner").
 * 3. Create section2 under channelA with a different code (e.g., "sub-banner").
 * 4. Attempt to update section2's code to the code of section1 ("main-banner").
 * 5. Expect the update to fail with a conflict error (HTTP 409 or a known conflict
 *    error thrown by the API).
 * 6. As there is no section read API, skip re-load & check of section2.
 */
export async function test_api_aimall_backend_administrator_channels_sections_test_update_section_with_duplicate_code_within_channel(
  connection: api.IConnection,
) {
  // 1. Create a new channel
  const channel =
    await api.functional.aimall_backend.administrator.channels.create(
      connection,
      {
        body: {
          code: `CHAN-${RandomGenerator.alphaNumeric(5)}`,
          name: `Test Channel ${RandomGenerator.alphaNumeric(5)}`,
          enabled: true,
        } satisfies IAimallBackendChannel.ICreate,
      },
    );
  typia.assert(channel);

  // 2. Create section1 with code 'main-banner-xxxx'
  const section1Code = `main-banner-${RandomGenerator.alphaNumeric(4)}`;
  const section1 =
    await api.functional.aimall_backend.administrator.channels.sections.create(
      connection,
      {
        channelId: channel.id,
        body: {
          channel_id: channel.id,
          code: section1Code,
          name: "Main Banner Section",
          display_order: 1,
          enabled: true,
        } satisfies IAimallBackendSection.ICreate,
      },
    );
  typia.assert(section1);

  // 3. Create section2 with code 'sub-banner-xxxx'
  const section2Code = `sub-banner-${RandomGenerator.alphaNumeric(4)}`;
  const section2 =
    await api.functional.aimall_backend.administrator.channels.sections.create(
      connection,
      {
        channelId: channel.id,
        body: {
          channel_id: channel.id,
          code: section2Code,
          name: "Sub Banner Section",
          display_order: 2,
          enabled: true,
        } satisfies IAimallBackendSection.ICreate,
      },
    );
  typia.assert(section2);

  // 4. Try to update section2's code to section1's code (should fail: duplicate)
  await TestValidator.error("fail update: code duplicate in channel")(
    async () => {
      await api.functional.aimall_backend.administrator.channels.sections.update(
        connection,
        {
          channelId: channel.id,
          sectionId: section2.id,
          body: {
            code: section1Code,
          } satisfies IAimallBackendSection.IUpdate,
        },
      );
    },
  );
  // 5. No fetch/read-by-id available for section, so cannot re-check section2 data.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSection";

/**
 * Validate error responses for section update with invalid channelId or
 * sectionId
 *
 * This test ensures that the update API for channel sections enforces strict
 * input validation and referential integrity, by rejecting requests that supply
 * invalid (malformed or non-existent) channelId/sectionId values.
 *
 * Workflow:
 *
 * 1. Generate a plausible update payload using IAimallBackendSection.IUpdate (with
 *    at least one field set).
 * 2. Test the following error cases: a. Malformed channelId, valid sectionId b.
 *    Valid channelId, malformed sectionId c. Both IDs malformed d. Both IDs
 *    well-formed but do not correspond to existing records
 * 3. For each invalid parameter set, attempt to call the update endpoint and
 *    assert that an error is thrown.
 */
export async function test_api_aimall_backend_administrator_channels_sections_test_update_section_invalid_channel_or_section_id(
  connection: api.IConnection,
) {
  // Step 1: Prepare a plausible update payload (set a few real fields)
  const updatePayload = {
    name: "Updated Section Name",
    display_order: 999,
    enabled: false,
  } satisfies IAimallBackendSection.IUpdate;

  // Step 2: Prepare test ID combinations for error scenarios
  const randomUUID = () => typia.random<string & tags.Format<"uuid">>();
  const malformedId = "NOT-A-UUID";

  const validChannelId = randomUUID();
  const validSectionId = randomUUID();

  const errorCases = [
    // (a) Malformed channelId
    { channelId: malformedId, sectionId: validSectionId },
    // (b) Malformed sectionId
    { channelId: validChannelId, sectionId: malformedId },
    // (c) Both malformed
    { channelId: malformedId, sectionId: malformedId },
    // (d) Both valid UUIDs, but do not exist in DB
    { channelId: randomUUID(), sectionId: randomUUID() },
  ];

  // Step 3: Attempt updates, expecting errors in each case
  for (const { channelId, sectionId } of errorCases) {
    await TestValidator.error(
      `should fail: update section channelId=${channelId}, sectionId=${sectionId}`,
    )(() =>
      api.functional.aimall_backend.administrator.channels.sections.update(
        connection,
        {
          channelId,
          sectionId,
          body: updatePayload,
        },
      ),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendChannel";
import type { IAimallBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSection";

/**
 * Validate the soft deletion (logical deletion) of a section within a channel
 * by an administrator.
 *
 * The test simulates the business sequence for managing sections under a
 * channel, ensuring:
 *
 * - A channel is provisioned and available for use.
 * - At least one section is created within that channel.
 * - The section is then soft deleted via the DELETE endpoint.
 * - After the operation, the section's `deleted_at` should be a set timestamp,
 *   confirming the soft delete (not an actual removal from the DB).
 * - The section should not appear in live/active queries and listings (not tested
 *   here due to lack of list endpoint in the provided APIs), but it still
 *   exists in the backend for auditing and compliance.
 *
 * Sequence:
 *
 * 1. Create a new channel via administrator API.
 * 2. Under this channel, create a new section.
 * 3. Perform soft delete on the created section.
 * 4. Optionally, attempt to retrieve or validate the state of the deleted section
 *    (via future get/list endpoint, if available).
 * 5. Assert that the DELETE operation succeeds and logical constraints are met.
 */
export async function test_api_aimall_backend_administrator_channels_sections_test_soft_delete_section_success_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new channel as admin
  const channel =
    await api.functional.aimall_backend.administrator.channels.create(
      connection,
      {
        body: {
          code: RandomGenerator.alphaNumeric(6),
          name: RandomGenerator.paragraph()(1),
          enabled: true,
        } satisfies IAimallBackendChannel.ICreate,
      },
    );
  typia.assert(channel);

  // 2. Create a new section under the channel
  const section =
    await api.functional.aimall_backend.administrator.channels.sections.create(
      connection,
      {
        channelId: channel.id,
        body: {
          channel_id: channel.id,
          code: RandomGenerator.alphaNumeric(6),
          name: RandomGenerator.paragraph()(1),
          display_order: 1,
          enabled: true,
        } satisfies IAimallBackendSection.ICreate,
      },
    );
  typia.assert(section);
  TestValidator.equals("section is not deleted at creation")(
    section.deleted_at,
  )(null);

  // 3. Perform soft delete (erase) on the created section
  await api.functional.aimall_backend.administrator.channels.sections.erase(
    connection,
    {
      channelId: channel.id,
      sectionId: section.id,
    },
  );
  // There's no fetch-by-id nor listing endpoint provided in the current APIs to confirm deleted_at directly after delete.
  // To fully confirm in future, fetch section details after delete and check deleted_at is now set (not null),
  // and check it's omitted from active listings.
}

