 * /aimall-backend/administrator/channels/{channelId}/sections/{sectionId}
 * responds with a 404 error when provided with a valid channelId but a
 * sectionId that does not exist or has already been deleted.
 *
 * This test is important to confirm:
 *
 * - The endpoint does not allow deletion of sections that do not exist (integrity
 *   check).
 * - The system provides an appropriate error (404 Not Found) without leaking
 *   internal errors.
 * - Side-effect auditing is invoked (not directly testable here).
 *
 * Steps:
 *
 * 1. Provision a new channel (to have a valid channelId).
 * 2. Generate a random UUID for sectionId that is not present under this channel.
 * 3. Call DELETE
 *    /aimall-backend/administrator/channels/{channelId}/sections/{sectionId}.
 * 4. Assert that the API call throws an error (404 expected).
 */
export async function test_api_aimall_backend_administrator_channels_sections_test_delete_section_nonexistent_section_id(
  connection: api.IConnection,
) {
  // 1. Provision a new channel to get a valid channelId
  const channel =
    await api.functional.aimall_backend.administrator.channels.create(
      connection,
      {
        body: {
          code: RandomGenerator.alphaNumeric(8),
          name: RandomGenerator.alphabets(12),
          enabled: true,
        } satisfies IAimallBackendChannel.ICreate,
      },
    );
  typia.assert(channel);

  // 2. Prepare a random, non-existent sectionId
  const nonExistentSectionId = typia.random<string & tags.Format<"uuid">>();

  // 3. Attempt section deletion with valid channelId but non-existent sectionId
  await TestValidator.error("non-existent sectionId should return 404 error")(
    async () => {
      await api.functional.aimall_backend.administrator.channels.sections.erase(
        connection,
        {
          channelId: channel.id,
          sectionId: nonExistentSectionId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendConfiguration";

/**
 * Validate that an administrator is able to list all system configurations.
 *
 * This test ensures:
 *
 * - The endpoint `/aimall-backend/administrator/configurations` responds with all
 *   configuration entities, including global, channel-scoped, and
 *   section-scoped configurations.
 * - Returned objects conform to the IAimallBackendConfiguration.ISummary schema.
 * - No sensitive or extraneous fields are leaked in the response.
 * - At least one configuration exists and is present in the result, by first
 *   creating one.
 *
 * Test Workflow:
 *
 * 1. Create at least one configuration using the admin `create` endpoint to
 *    guarantee a non-empty list.
 * 2. Retrieve the list of all configurations using the admin `index` endpoint.
 * 3. Confirm the result is an array of objects conforming to the ISummary schema.
 * 4. Verify audit and key fields (id, key, value, channel/section context) are
 *    present, and that sensitive or extra fields are not returned.
 * 5. Check the created configuration can be found in the result.
 */
export async function test_api_aimall_backend_administrator_configurations_index(
  connection: api.IConnection,
) {
  // 1. Create a configuration for predictable listing.
  const newConfig =
    await api.functional.aimall_backend.administrator.configurations.create(
      connection,
      {
        body: {
          // chose a global configuration for predictable matching
          channel_id: null,
          section_id: null,
          key: `e2e_test_key_${typia.random<string>()}`,
          value: "test_value",
          description: "E2E test configuration entry to ensure listing works.",
        } satisfies IAimallBackendConfiguration.ICreate,
      },
    );
  typia.assert(newConfig);

  // 2. Retrieve the full list of configurations as admin.
  const configs =
    await api.functional.aimall_backend.administrator.configurations.index(
      connection,
    );
  typia.assert(configs);

  // 3. Confirm result includes an array of ISummary objects
  if (!Array.isArray(configs))
    throw new Error(
      "Configurations listing did not return an array as expected.",
    );
  for (const item of configs) {
    typia.assert<IAimallBackendConfiguration.ISummary>(item);
  }

  // 4. Check that the configuration just created is present in the results (by key & value)
  const match = configs.find(
    (x) => x.key === newConfig.key && x.value === newConfig.value,
  );
  TestValidator.predicate("created config is present in the list")(!!match);

  // 5. Check for schema compliance and no extra fields in each result
  for (const item of configs) {
    const keys = Object.keys(item);
    const summaryFields = ["id", "channel_id", "section_id", "key", "value"];
    TestValidator.equals("no extra fields in summary")(keys.sort().join(","))(
      summaryFields.sort().join(","),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendConfiguration";
import type { IPageIAimallBackendConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching system configurations with filters and pagination.
 *
 * This test verifies the administrator's ability to search system configuration
 * records using a variety of filter options and pagination/sorting, ensuring
 * that only records matching the criteria are returned and pagination metadata
 * is consistent with expected results.
 *
 * Steps:
 *
 * 1. Create three configuration records, each scoped differently:
 *
 *    - A global configuration (channel_id and section_id null)
 *    - A channel-scoped configuration (channel_id set, section_id null)
 *    - A section-scoped configuration (same channel_id as above, section_id set) All
 *         records use unique keys/values for robust filter testing.
 * 2. Run multiple searches via the PATCH endpoint:
 *
 *    - By exact key
 *    - By partial key
 *    - By value substring
 *    - By channel_id and section_id
 *    - By pagination (limit, page)
 *    - By sorting fields (e.g., sort_by and sort_order)
 * 3. Validate:
 *
 *    - Only matching data is returned for each filter
 *    - Pagination metadata accurately reflects query and results
 *    - Edge case: No-match search returns empty array and paginated metadata
 */
export async function test_api_aimall_backend_administrator_configurations_test_search_configurations_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create distinct test records for all filter types
  const globalKey = `global_feature_${RandomGenerator.alphaNumeric(6)}`;
  const globalConfig =
    await api.functional.aimall_backend.administrator.configurations.create(
      connection,
      {
        body: {
          key: globalKey,
          value: "active",
          channel_id: null,
          section_id: null,
          description: "E2E test - global config",
        },
      },
    );
  typia.assert(globalConfig);

  const channelId = typia.random<string & tags.Format<"uuid">>();
  const channelKey = `channel_flag_${RandomGenerator.alphaNumeric(6)}`;
  const channelConfig =
    await api.functional.aimall_backend.administrator.configurations.create(
      connection,
      {
        body: {
          key: channelKey,
          value: "enabled",
          channel_id: channelId,
          section_id: null,
          description: "E2E test - channel config",
        },
      },
    );
  typia.assert(channelConfig);

  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const sectionKey = `section_setting_${RandomGenerator.alphaNumeric(6)}`;
  const sectionConfig =
    await api.functional.aimall_backend.administrator.configurations.create(
      connection,
      {
        body: {
          key: sectionKey,
          value: "special",
          channel_id: channelId,
          section_id: sectionId,
          description: "E2E test - section config",
        },
      },
    );
  typia.assert(sectionConfig);

  // 2. Search by exact key (globalKey)
  let result =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      {
        body: { key: globalKey },
      },
    );
  typia.assert(result);
  TestValidator.predicate("all returned records have the searched key")(
    result.data.every((cfg) => cfg.key === globalKey),
  );
  TestValidator.equals("pagination reflects single record found")(
    result.pagination.records,
  )(1);

  // 3. Partial key search - should find at least the global record
  result =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      {
        body: { key: "global_feature" },
      },
    );
  typia.assert(result);
  TestValidator.predicate("partial key search includes global config")(
    result.data.some((cfg) => cfg.id === globalConfig.id),
  );

  // 4. Value substring search for "enabled" value (channel scoped record)
  result =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      {
        body: { value_contains: "enabled" },
      },
    );
  typia.assert(result);
  TestValidator.predicate("all records have 'enabled' substring in value")(
    result.data.every((cfg) => cfg.value.includes("enabled")),
  );

  // 5. Filter by channel_id
  result =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      {
        body: { channel_id: channelId },
      },
    );
  typia.assert(result);
  TestValidator.predicate("all records match the channel_id filter")(
    result.data.every((cfg) => cfg.channel_id === channelId),
  );

  // 6. Filter by section_id
  result =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      {
        body: { section_id: sectionId },
      },
    );
  typia.assert(result);
  TestValidator.predicate("all records match section_id filter")(
    result.data.every((cfg) => cfg.section_id === sectionId),
  );

  // 7. Pagination: limit=1, page=2 (test multiple pages)
  result =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      {
        body: { limit: 1, page: 2 },
      },
    );
  typia.assert(result);
  TestValidator.equals("pagination limit is respected")(
    result.pagination.limit,
  )(1);
  TestValidator.equals("pagination current page is 2")(
    result.pagination.current,
  )(2);

  // 8. Sort by key descending
  result =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      {
        body: { sort_by: "key", sort_order: "desc" },
      },
    );
  typia.assert(result);
  const descSorted = [...result.data].sort((a, b) =>
    b.key.localeCompare(a.key),
  );
  TestValidator.equals("sort descending by key")(result.data)(descSorted);

  // 9. Edge - filter with no matches
  result =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      {
        body: { key: "_no_config_with_this_key_" },
      },
    );
  typia.assert(result);
  TestValidator.equals("empty result when key does not exist")(
    result.data.length,
  )(0);
  TestValidator.predicate("pagination object still returned")(
    typeof result.pagination === "object" && result.pagination.current >= 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendConfiguration";
import type { IPageIAimallBackendConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the case where searching for aimall backend administrator configurations
 * yields no results.
 *
 * This test ensures that, when search criteria are set to impossible values
 * (such as a configuration key that could not possibly exist), the API responds
 * correctly by returning an empty data array, while still providing valid
 * pagination metadata.
 *
 * Steps:
 *
 * 1. Construct a search request to the configurations endpoint with a key known to
 *    be impossible (e.g., a random UUID prefix key).
 * 2. Call the search API endpoint as an administrator.
 * 3. Verify the response:
 *
 *    - The `data` array in the response should be empty.
 *    - The `pagination` object must still be present and valid, with `records`,
 *         `pages`, and `current` values indicating zero records.
 */
export async function test_api_aimall_backend_administrator_configurations_test_search_configurations_no_results(
  connection: api.IConnection,
) {
  // 1. Prepare impossible search criteria: impossible key string, all others default (null/omitted)
  const impossibleKey = `NO_SUCH_KEY_${typia.random<string & tags.Format<"uuid">>()}`;
  const input = {
    key: impossibleKey,
    page: null,
    limit: null,
    channel_id: null,
    section_id: null,
    value_contains: null,
    sort_by: null,
    sort_order: null,
  } satisfies IAimallBackendConfiguration.IRequest;

  // 2. Perform search
  const output =
    await api.functional.aimall_backend.administrator.configurations.search(
      connection,
      { body: input },
    );
  typia.assert(output);

  // 3. Validate response: data must be empty, pagination present and has zero records
  TestValidator.equals("empty data array")(output.data.length)(0);
  TestValidator.predicate("pagination present")(
    typeof output.pagination === "object" && output.pagination !== null,
  );
  TestValidator.equals("zero records")(output.pagination.records)(0);
  TestValidator.equals("zero pages")(output.pagination.pages)(0);
}

