import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSeller";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSku";

/**
 * Validates that an administrator can successfully create a SKU for a product.
 *
 * Business context:
 *
 * - SKUs are variants belonging to a product. Each SKU must be associated with an
 *   existing product (by product_id) and have a unique sku_code.
 * - Administrators use this endpoint to add new purchasable variants to the
 *   catalog.
 *
 * Why this test is necessary:
 *
 * - Ensures the API allows admins to create SKUs for valid products, and verifies
 *   the system links the SKU correctly.
 * - Guards against regressions that break core catalog management workflows.
 *
 * Step-by-step process:
 *
 * 1. Create a seller (administrator privilege) so a product can be assigned an
 *    owner.
 * 2. Create a product, assigning it to the created seller.
 * 3. As administrator, create a SKU for the product, providing a unique sku_code
 *    and referencing the existing product ID.
 * 4. Assert that the returned SKU contains the expected product_id and sku_code.
 */
export async function test_api_aimall_backend_administrator_products_skus_test_admin_creates_new_sku_for_product_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a seller (admin privilege)
  const sellerData = {
    business_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    contact_phone: RandomGenerator.mobile(),
    status: "approved",
  } satisfies IAimallBackendSeller.ICreate;
  const seller =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: sellerData,
      },
    );
  typia.assert(seller);

  // 2. Create a product owned by the new seller
  const productData = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    seller_id: seller.id,
    title: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    status: "active",
  } satisfies IAimallBackendProduct.ICreate;
  const product = await api.functional.aimall_backend.seller.products.create(
    connection,
    {
      body: productData,
    },
  );
  typia.assert(product);

  // 3. As admin, create a SKU using a unique sku_code for that product
  const sku_code = "SKU-" + RandomGenerator.alphaNumeric(8);
  const skuBody = {
    product_id: product.id,
    sku_code,
  } satisfies IAimallBackendSku.ICreate;
  const sku =
    await api.functional.aimall_backend.administrator.products.skus.create(
      connection,
      {
        productId: product.id,
        body: skuBody,
      },
    );
  typia.assert(sku);

  // 4. Assertions to confirm the SKU is bound to the correct product and code
  TestValidator.equals("sku product id matches")(sku.product_id)(product.id);
  TestValidator.equals("sku_code matches")(sku.sku_code)(sku_code);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSeller";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSku";

/**
 * Validate that an administrator cannot create a new SKU for a product using a
 * duplicate "sku_code".
 *
 * Business context: SKU codes must be unique per product. Creating a SKU with a
 * code that already exists for the same product must result in a
 * conflict/validation error (typically 409 or equivalent).
 *
 * Workflow:
 *
 * 1. Admin creates a seller (required for product ownership).
 * 2. Seller creates a product under their account.
 * 3. Seller creates an initial SKU for the product with a specific sku_code.
 * 4. Admin attempts to create another SKU for the same product using the exact
 *    same sku_code.
 * 5. Test expects error/validation failure due to duplicate sku_code for the same
 *    product.
 */
export async function test_api_aimall_backend_administrator_products_skus_test_admin_attempts_to_create_sku_with_duplicate_code_fails(
  connection: api.IConnection,
) {
  // 1. Admin creates a seller for test product ownership
  const sellerInput: IAimallBackendSeller.ICreate = {
    business_name: RandomGenerator.name(),
    email: typia.random<string & tags.Format<"email">>(),
    contact_phone: RandomGenerator.mobile(),
    status: "approved",
  };
  const seller =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      { body: sellerInput },
    );
  typia.assert(seller);

  // 2. Seller creates a product
  const productInput: IAimallBackendProduct.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    seller_id: seller.id,
    title: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    main_thumbnail_uri: undefined,
    status: "active",
  };
  const product = await api.functional.aimall_backend.seller.products.create(
    connection,
    { body: productInput },
  );
  typia.assert(product);

  // 3. Seller creates an initial SKU
  const skuCode = RandomGenerator.alphaNumeric(10);
  const skuInput: IAimallBackendSku.ICreate = {
    product_id: product.id,
    sku_code: skuCode,
  };
  const sku = await api.functional.aimall_backend.seller.products.skus.create(
    connection,
    {
      productId: product.id,
      body: skuInput,
    },
  );
  typia.assert(sku);

  // 4. Admin attempts to create another SKU with the same sku_code
  const duplicateSkuInput: IAimallBackendSku.ICreate = {
    product_id: product.id,
    sku_code: skuCode, // duplicate
  };

  await TestValidator.error(
    "duplicate sku_code should result in conflict/validation failure",
  )(async () => {
    await api.functional.aimall_backend.administrator.products.skus.create(
      connection,
      {
        productId: product.id,
        body: duplicateSkuInput,
      },
    );
  });
}

