  // 2d. Zero page (should be at least 1)
  await TestValidator.error("zero page is a validation error")(() =>
    api.functional.aimall_backend.administrator.skus.inventorySnapshots.search(
      connection,
      {
        skuId,
        body: {
          page: 0,
        },
      },
    ),
