  // 2e. Negative limit
  await TestValidator.error("negative limit triggers validation error")(() =>
    api.functional.aimall_backend.administrator.skus.inventorySnapshots.search(
      connection,
      {
        skuId,
        body: {
          limit: -10,
        },
      },
