import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import type { IAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSnapshot";
import type { IPageIAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search and filtering of post snapshots by a customer.
 *
 * This test ensures that after uploading multiple snapshots (with different
 * attributes, such as captions and timestamps) under a single post, the
 * advanced search API for snapshots (PATCH
 * /aimall-backend/customer/posts/{postId}/snapshots) correctly returns matching
 * snapshot records according to given filters (such as media URI substring or
 * created_at date range), and fulfills expected behaviors for no results.
 *
 * Test workflow:
 *
 * 1. Create a customer post (as the parent entity for snapshots)
 * 2. Upload several snapshots with varied properties (media_uri, caption, distinct
 *    created_at values for meaningful filtering)
 * 3. Search/filter snapshots using known criteria:
 *
 *    - By post_id only (should return all snapshots)
 *    - By media_uri substring (should match a subset)
 *    - By created_from/created_to date range
 *    - By caption keyword
 *    - By impossible filter (should return an empty result)
 * 4. In each case, validate that results match expected filtering, including total
 *    count and correct field content.
 */
export async function test_api_aimall_backend_customer_posts_snapshots_test_advanced_search_snapshots_for_post_by_customer(
  connection: api.IConnection,
) {
  // 1. Create a new post
  const post = await api.functional.aimall_backend.customer.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(),
        is_private: false,
      },
    },
  );
  typia.assert(post);

  // 2. Upload several snapshots with distinct properties (media_uri, caption, created_at)
  const snapshots: IAimallBackendSnapshot[] = [];
  const now = new Date();
  for (let i = 0; i < 3; ++i) {
    // Spread out created_at, alternate media_uri patterns, mix captions
    const created_at = new Date(now.getTime() + i * 86400000).toISOString();
    const media_uri =
      i % 2 === 0
        ? `https://media.example.com/photo${i}.jpg`
        : `https://media.example.com/video${i}.mp4`;
    const caption = i === 1 ? "holiday-trip" : `test-caption-${i}`;
    const snap =
      await api.functional.aimall_backend.customer.posts.snapshots.create(
        connection,
        {
          postId: post.id,
          body: {
            post_id: post.id,
            media_uri,
            caption,
            created_at,
          },
        },
      );
    typia.assert(snap);
    snapshots.push(snap);
  }

  // 3. Search by post_id only: should return all 3
  {
    const res =
      await api.functional.aimall_backend.customer.posts.snapshots.search(
        connection,
        {
          postId: post.id,
          body: { post_id: post.id },
        },
      );
    typia.assert(res);
    TestValidator.equals("all snapshots exist")(res.data?.length ?? 0)(
      snapshots.length,
    );
  }

  // 4. Search by media_uri substring: should match 1 or more
  {
    const filterUri = "video";
    const expected = snapshots.filter((s) => s.media_uri.includes(filterUri));
    const res =
      await api.functional.aimall_backend.customer.posts.snapshots.search(
        connection,
        {
          postId: post.id,
          body: { post_id: post.id, media_uri: filterUri },
        },
      );
    typia.assert(res);
    TestValidator.equals("filtered by media_uri")(res.data?.length ?? 0)(
      expected.length,
    );
    TestValidator.predicate("all returned should match media_uri filter")(
      res.data?.every((s) => s.media_uri.includes(filterUri)) ?? false,
    );
  }

  // 5. Search by caption substring (should match at least one)
  {
    const filterCaption = "holiday";
    const expected = snapshots.filter((s) =>
      (s.caption ?? "").includes(filterCaption),
    );
    const res =
      await api.functional.aimall_backend.customer.posts.snapshots.search(
        connection,
        {
          postId: post.id,
          body: { post_id: post.id, caption: filterCaption },
        },
      );
    typia.assert(res);
    TestValidator.equals("filter by caption substring")(res.data?.length ?? 0)(
      expected.length,
    );
    TestValidator.predicate("all returned captions should match filter")(
      res.data?.every((s) => (s.caption ?? "").includes(filterCaption)) ??
        false,
    );
  }

  // 6. Search by created_from: should match only those created after a certain date
  {
    const from = new Date(now.getTime() + 86400000).toISOString();
    const expected = snapshots.filter((s) => s.created_at >= from);
    const res =
      await api.functional.aimall_backend.customer.posts.snapshots.search(
        connection,
        {
          postId: post.id,
          body: { post_id: post.id, created_from: from },
        },
      );
    typia.assert(res);
    TestValidator.equals("filter by created_from")(res.data?.length ?? 0)(
      expected.length,
    );
    TestValidator.predicate("returned created_at >= searchFrom")(
      res.data?.every((s) => s.created_at >= from) ?? false,
    );
  }

  // 7. Search by created_to: should match only those created on/before certain date
  {
    const to = new Date(now.getTime()).toISOString();
    const expected = snapshots.filter((s) => s.created_at <= to);
    const res =
      await api.functional.aimall_backend.customer.posts.snapshots.search(
        connection,
        {
          postId: post.id,
          body: { post_id: post.id, created_to: to },
        },
      );
    typia.assert(res);
    TestValidator.equals("filter by created_to")(res.data?.length ?? 0)(
      expected.length,
    );
    TestValidator.predicate("all returned created_at <= to date")(
      res.data?.every((s) => s.created_at <= to) ?? false,
    );
  }

  // 8. Impossible filter: should return zero results
  {
    const res =
      await api.functional.aimall_backend.customer.posts.snapshots.search(
        connection,
        {
          postId: post.id,
          body: { post_id: post.id, caption: "unmatchable-filter-string-zzz" },
        },
      );
    typia.assert(res);
    TestValidator.equals("empty results for unmatchable filter")(
      res.data?.length ?? 0,
    )(0);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import type { IAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSnapshot";
import type { IPageIAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate seller's advanced filtered search for snapshots using PATCH
 * endpoint.
 *
 * This test validates the ability to upload multiple snapshots to a seller's
 * post, then perform advanced searches (filters, pagination) on that set with
 * PATCH. Snapshots will have varying attributes (caption, media_uri), and
 * search filters will target these differences. Both success and edge/failure
 * scenarios (e.g., no match, pagination limits) are validated.
 *
 * Steps:
 *
 * 1. Create a post as a seller
 * 2. Upload at least three distinct snapshots to this post
 *
 *    - Distinct captions, media URIs
 * 3. Filter by unique caption: only the targeted snapshot is returned
 * 4. Filter by non-existent caption: should return empty result
 * 5. Test pagination (limit=2): verify split between pages, total matches uploaded
 * 6. Filter by shared caption: ensure multiple correct matches are returned
 */
export async function test_api_aimall_backend_seller_posts_snapshots_test_advanced_search_snapshots_for_post_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller creates a post
  const post = await api.functional.aimall_backend.seller.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(2),
        body: RandomGenerator.content()()(),
        is_private: false,
      } satisfies IAimallBackendPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Upload three snapshots with varying captions and media URIs
  const snapshots: IAimallBackendSnapshot[] = [];
  const captions = [
    RandomGenerator.alphaNumeric(8),
    RandomGenerator.alphaNumeric(8),
    RandomGenerator.alphaNumeric(8),
  ];
  const uris = [
    "https://example.com/imageA.png",
    "https://example.com/imageB.jpg",
    "https://example.com/videoC.mp4",
  ];
  for (let i = 0; i < 3; ++i) {
    const snapshot =
      await api.functional.aimall_backend.seller.posts.snapshots.create(
        connection,
        {
          postId: post.id,
          body: {
            post_id: post.id,
            media_uri: uris[i],
            caption: captions[i],
            created_at: new Date(Date.now() - i * 1000 * 60).toISOString(),
          } satisfies IAimallBackendSnapshot.ICreate,
        },
      );
    typia.assert(snapshot);
    snapshots.push(snapshot);
  }

  // 3. Search by caption for the second snapshot, only that one should be returned
  const filterCaption = captions[1];
  const captionSearch =
    await api.functional.aimall_backend.seller.posts.snapshots.search(
      connection,
      {
        postId: post.id,
        body: {
          post_id: post.id,
          caption: filterCaption,
          limit: 10,
          page: 1,
        } satisfies IAimallBackendSnapshot.IRequest,
      },
    );
  typia.assert(captionSearch);
  TestValidator.equals("Only snapshot with filter caption should return")(
    captionSearch.data?.length,
  )(1);
  TestValidator.equals("Returned caption matches filter")(
    captionSearch.data?.[0]?.caption,
  )(filterCaption);

  // 4. Search by a non-existent caption, expect empty results
  const emptyCaption = "not-a-real-caption-zzz";
  const emptySearch =
    await api.functional.aimall_backend.seller.posts.snapshots.search(
      connection,
      {
        postId: post.id,
        body: {
          post_id: post.id,
          caption: emptyCaption,
          limit: 10,
          page: 1,
        } satisfies IAimallBackendSnapshot.IRequest,
      },
    );
  typia.assert(emptySearch);
  TestValidator.equals("No results for absent caption")(
    emptySearch.data?.length ?? 0,
  )(0);

  // 5a. Pagination test, limit=2, page=1
  const page1 =
    await api.functional.aimall_backend.seller.posts.snapshots.search(
      connection,
      {
        postId: post.id,
        body: {
          post_id: post.id,
          limit: 2,
          page: 1,
        } satisfies IAimallBackendSnapshot.IRequest,
      },
    );
  typia.assert(page1);
  TestValidator.equals("First page should return 2 items")(page1.data?.length)(
    2,
  );

  // 5b. Pagination test, limit=2, page=2
  const page2 =
    await api.functional.aimall_backend.seller.posts.snapshots.search(
      connection,
      {
        postId: post.id,
        body: {
          post_id: post.id,
          limit: 2,
          page: 2,
        } satisfies IAimallBackendSnapshot.IRequest,
      },
    );
  typia.assert(page2);
  TestValidator.equals("Second page should return 1 item")(page2.data?.length)(
    1,
  );
  // 5c. Total returned should match uploaded snapshots
  const totalReturned = (page1.data?.length ?? 0) + (page2.data?.length ?? 0);
  TestValidator.equals("Total paginated matches uploaded count")(totalReturned)(
    snapshots.length,
  );

  // 6. Add an extra snapshot with same caption as the first
  const sharedCaption = captions[0];
  const extra =
    await api.functional.aimall_backend.seller.posts.snapshots.create(
      connection,
      {
        postId: post.id,
        body: {
          post_id: post.id,
          media_uri: "https://example.com/extraD.jpg",
          caption: sharedCaption,
        } satisfies IAimallBackendSnapshot.ICreate,
      },
    );
  typia.assert(extra);

  const sharedSearch =
    await api.functional.aimall_backend.seller.posts.snapshots.search(
      connection,
      {
        postId: post.id,
        body: {
          post_id: post.id,
          caption: sharedCaption,
          limit: 10,
          page: 1,
        } satisfies IAimallBackendSnapshot.IRequest,
      },
    );
  typia.assert(sharedSearch);
  TestValidator.predicate("Filtering by shared caption returns >=2 items")(
    (sharedSearch.data?.length ?? 0) >= 2,
  );
}

