        currency,
      } satisfies IAimallBackendOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Seller adds an order item
  const product_id = typia.random<string & tags.Format<"uuid">>();
  const item_name = "Test Item";
  const quantity = 2;
