import type { IAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrderItem";

/**
 * Validates listing order items for a customer's own order, and permission
 * enforcement.
 *
 * This test ensures that a customer can only retrieve order items belonging to
 * their own order, and that another customer is restricted from accessing those
 * items.
 *
 * 1. Create Customer A (simulated by unique UUID context)
 * 2. Customer A creates a new order via POST /aimall-backend/customer/orders
 * 3. Customer A adds two order items to the order (with full schema fields)
 * 4. Customer A retrieves the order items and checks the returned list matches
 *    exactly the created items and fields are correct
 * 5. Create Customer B (distinct UUID). Attempt to list order items on A's order
 *    and verify an error is thrown (permission/ownership protection)
 */
export async function test_api_aimall_backend_customer_orders_orderItems_index(
  connection: api.IConnection,
) {
  // --- Step 1: Prepare customer A (simulated by unique ids) ---
  const customerA_id = typia.random<string & tags.Format<"uuid">>();
  const seller_id = typia.random<string & tags.Format<"uuid">>();
  const address_id = typia.random<string & tags.Format<"uuid">>();

  // --- Step 2: Customer A places an order ---
  const orderCreateReq: IAimallBackendOrder.ICreate = {
    customer_id: customerA_id,
    seller_id,
    address_id,
    order_status: "pending",
    total_amount: 12000,
    currency: "KRW",
    // order_number intentionally omitted for system auto-generation
  };
  const order = await api.functional.aimall_backend.customer.orders.create(
    connection,
    {
      body: orderCreateReq,
    },
  );
  typia.assert(order);
  TestValidator.equals("customer matches")(order.customer_id)(customerA_id);

  // --- Step 3: Customer A adds two order items ---
  // Use distinct products, variations in item details
  const orderItemReqs: IAimallBackendOrderItem.ICreate[] = [
    {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_option_id: typia.random<string & tags.Format<"uuid">>(),
      item_name: "Red Shirt - Large",
      quantity: 2,
      unit_price: 5000,
      total_price: 10000,
    },
    {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      // Omit product_option_id for product without variants
      item_name: "Coffee Mug",
      quantity: 1,
      unit_price: 2000,
      total_price: 2000,
    },
  ];

  const createdItems: IAimallBackendOrderItem[] = [];
  for (const req of orderItemReqs) {
    const item =
      await api.functional.aimall_backend.customer.orders.orderItems.create(
        connection,
        {
          orderId: order.id,
          body: req,
        },
      );
    typia.assert(item);
    TestValidator.equals("order in item")(item.order_id)(order.id);
    createdItems.push(item);
  }

  // --- Step 4: Customer A lists their order items and validates ---
  const listed =
    await api.functional.aimall_backend.customer.orders.orderItems.index(
      connection,
      {
        orderId: order.id,
      },
    );
  typia.assert(listed);
  // Validate all expected items returned (by id, order)
  const listedIds = listed.data.map((x) => x.id).sort();
  const createdIds = createdItems.map((x) => x.id).sort();
  TestValidator.equals("all item ids returned")(listedIds)(createdIds);
  // Additional detail checks
  for (const created of createdItems) {
    const found = listed.data.find((x) => x.id === created.id);
    TestValidator.predicate("listed should contain created item")(!!found);
    TestValidator.equals("item_name")(found!.item_name)(created.item_name);
    TestValidator.equals("quantity")(found!.quantity)(created.quantity);
    TestValidator.equals("unit_price")(found!.unit_price)(created.unit_price);
    TestValidator.equals("total_price")(found!.total_price)(
      created.total_price,
    );
  }

  // --- Step 5: Simulate another customer B, who does not own the order ---
  const customerB_id = typia.random<string & tags.Format<"uuid">>();
  // They might attempt the same API, but referencing A's order.
  // If authorization context is enforced by customer_id, we can simulate by swapping the id in a future context.
  // For this test, simulate permission error (should reject as not-owning customer).
  // (In this test context, we don't actually have authentication APIs, so this is a simulated negative test.)
  //
  // Simulate by using swapped context or indicating in comments.
  TestValidator.error("Other customer cannot access this order's items")(
    async () => {
      // Attempt with different customer id as context
      // In a real system, the underlying API would check the authenticated user's identity.
      await api.functional.aimall_backend.customer.orders.orderItems.index(
        connection,
        {
          orderId: order.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";
import type { IAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrderItem";
import type { IPageIAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendOrderItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced order item search and filtering for an administrator.
 *
 * This test verifies the administrator's ability to search/filter order items
 * within a specific order. It ensures correct operation with diverse item lines
 * and thorough handling of pagination, filtering, sorting, and edge cases.
 *
 * Steps:
 *
 * 1. Create an order via the administrator API with valid and random business
 *    fields (customer_id, seller_id, address_id, etc.).
 * 2. Add multiple (at least 5) diverse order items to the created order, each with
 *    unique combinations of product_id, SKU/product_option_id (some null, some
 *    filled), item_name, quantity, unit_price, and total_price.
 * 3. Search order items solely by order_id (should return all just-added items),
 *    confirm all are present and content matches what was added.
 * 4. For each unique product_id present in those items, search with order_id and
 *    that product_id -- confirm only matching items are returned.
 * 5. For a line with product_option_id, search using order_id and
 *    product_option_id; confirm only correct item(s) are returned.
 * 6. Search by an item_name substring that should match one or more items,
 *    validate filtering.
 * 7. Validate pagination - e.g. set limit 2, get total page count and data
 *    integrity for all pages.
 * 8. Sort by item_name ascending and descending, confirm that order of results is
 *    correct in both cases.
 * 9. Try a non-matching product_id, a non-existent product_option_id, or
 *    impossible combo, confirm that result set is empty but not errored.
 */
export async function test_api_aimall_backend_administrator_orders_orderItems_test_advanced_search_order_items_by_admin(
  connection: api.IConnection,
) {
  // 1. Create an order as administrator
  const order = await api.functional.aimall_backend.administrator.orders.create(
    connection,
    {
      body: {
        customer_id: typia.random<string & tags.Format<"uuid">>(),
        seller_id: typia.random<string & tags.Format<"uuid">>(),
        address_id: typia.random<string & tags.Format<"uuid">>(),
        order_status: "pending",
        total_amount: 100000,
        currency: "KRW",
      },
    },
  );
  typia.assert(order);

  // 2. Add 5 diverse order items with unique (product_id, option, name, qty, price)
  const products = ArrayUtil.repeat(5)(() => ({
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_option_id:
      Math.random() > 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
    item_name: RandomGenerator.alphabets(10),
    quantity: typia.random<number & tags.Type<"int32">>(),
    unit_price: 1000 + Math.floor(Math.random() * 5000),
  }));
  const orderItems: IAimallBackendOrderItem[] = [];
  for (const prod of products) {
    const oi =
      await api.functional.aimall_backend.administrator.orders.orderItems.create(
        connection,
        {
          orderId: order.id,
          body: {
            product_id: prod.product_id,
            product_option_id: prod.product_option_id,
            item_name: prod.item_name,
            quantity: prod.quantity,
            unit_price: prod.unit_price,
            total_price: prod.unit_price * prod.quantity,
          },
        },
      );
    orderItems.push(oi);
    typia.assert(oi);
  }

  // 3. Search for all order items (by order_id)
  let searchRes =
    await api.functional.aimall_backend.administrator.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: { order_id: order.id },
      },
    );
  typia.assert(searchRes);
  TestValidator.equals("return all items")(searchRes.data.length)(
    orderItems.length,
  );
  for (const item of orderItems)
    TestValidator.predicate("item present")(
      searchRes.data.some((d) => d.id === item.id),
    );

  // 4. Filter by each product_id and validate match
  for (const prod of products) {
    searchRes =
      await api.functional.aimall_backend.administrator.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: { order_id: order.id, product_id: prod.product_id },
        },
      );
    typia.assert(searchRes);
    TestValidator.predicate("product filter")(
      searchRes.data.every((i) => i.product_id === prod.product_id),
    );
  }

  // 5. Filter by product_option_id where not null
  for (const prod of products.filter((p) => !!p.product_option_id)) {
    searchRes =
      await api.functional.aimall_backend.administrator.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: {
            order_id: order.id,
            product_option_id: prod.product_option_id,
          },
        },
      );
    typia.assert(searchRes);
    TestValidator.predicate("option filter")(
      searchRes.data.every(
        (i) => i.product_option_id === prod.product_option_id,
      ),
    );
  }

  // 6. Filter by item_name substring (pick first three letters)
  {
    const filterName = products[0].item_name.substring(0, 3);
    searchRes =
      await api.functional.aimall_backend.administrator.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: { order_id: order.id, item_name: filterName },
        },
      );
    typia.assert(searchRes);
    TestValidator.predicate("item_name filter")(
      searchRes.data.some((i) => i.item_name.includes(filterName)),
    );
  }

  // 7. Pagination (limit = 2) and page correctness
  searchRes =
    await api.functional.aimall_backend.administrator.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: { order_id: order.id, limit: 2, page: 1 },
      },
    );
  typia.assert(searchRes);
  TestValidator.equals("pagination limit")(searchRes.data.length)(2);

  // 8. Sorting
  searchRes =
    await api.functional.aimall_backend.administrator.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: { order_id: order.id, sort_by: "item_name", sort_order: "asc" },
      },
    );
  typia.assert(searchRes);
  const ascNames = searchRes.data.map((i) => i.item_name);
  const sortedAsc = [...ascNames].sort((a, b) => a.localeCompare(b));
  TestValidator.equals("sort asc")(ascNames)(sortedAsc);

  searchRes =
    await api.functional.aimall_backend.administrator.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: { order_id: order.id, sort_by: "item_name", sort_order: "desc" },
      },
    );
  typia.assert(searchRes);
  const descNames = searchRes.data.map((i) => i.item_name);
  const sortedDesc = [...descNames].sort((a, b) => b.localeCompare(a));
  TestValidator.equals("sort desc")(descNames)(sortedDesc);

  // 9. Try a bogus product_id (random not assigned above)
  searchRes =
    await api.functional.aimall_backend.administrator.orders.orderItems.search(
      connection,
      {
        orderId: order.id,
        body: {
          order_id: order.id,
          product_id: typia.random<string & tags.Format<"uuid">>(),
        },
      },
    );
  typia.assert(searchRes);
  TestValidator.equals("no match")(searchRes.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";
import type { IAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrderItem";
import type { IPageIAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendOrderItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced search and filter functionalities for seller order items
 * in an owned order.
 *
 * This E2E test covers the following sequence:
 *
 * 1. Create an order as a seller (parent entity for order items to be
 *    filtered/searched)
 * 2. Add multiple (at least two) distinct order items to the order, varying
 *    product_id, product_option_id, and quantity for comprehensive filter
 *    coverage.
 * 3. Search the order items using exact product_id, SKU/option (product_option_id)
 *    filters, and expect output to match those filters and reflect correct
 *    pagination meta.
 * 4. Search with an invalid product_id for this order and assert the result is
 *    empty.
 * 5. Attempt to search order items for an order as a seller that does not own it
 *    (simulate with fake UUID), verify API returns an error.
 */
export async function test_api_aimall_backend_test_seller_advanced_search_filter_order_items(
  connection: api.IConnection,
) {
  // 1. Create an order as seller
  const order_input: IAimallBackendOrder.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    address_id: typia.random<string & tags.Format<"uuid">>(),
    order_number: undefined, // Let backend generate
    order_status: "pending",
    total_amount: 200000,
    currency: "KRW",
  };
  const order = await api.functional.aimall_backend.seller.orders.create(
    connection,
    { body: order_input },
  );
  typia.assert(order);

  // 2. Add multiple distinct order items (different product_id, product_option_id, quantity)
  const item_inputs: IAimallBackendOrderItem.ICreate[] = [
    {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_option_id: typia.random<string & tags.Format<"uuid">>(),
      item_name: "Red T-Shirt Large",
      quantity: 5,
      unit_price: 10000,
      total_price: 50000,
    },
    {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_option_id: typia.random<string & tags.Format<"uuid">>(),
      item_name: "Blue Jeans Medium",
      quantity: 2,
      unit_price: 50000,
      total_price: 100000,
    },
    {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_option_id: null,
      item_name: "Black Belt",
      quantity: 1,
      unit_price: 50000,
      total_price: 50000,
    },
  ];
  const created_items: IAimallBackendOrderItem[] = [];
  for (const input of item_inputs) {
    const item =
      await api.functional.aimall_backend.seller.orders.orderItems.create(
        connection,
        {
          orderId: order.id,
          body: input,
        },
      );
    typia.assert(item);
    created_items.push(item);
  }

  // 3a. Search/filter by product_id (should yield 1)
  {
    const search_body: IAimallBackendOrderItem.IRequest = {
      order_id: order.id,
      product_id: created_items[0].product_id,
    };
    const resp =
      await api.functional.aimall_backend.seller.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: search_body,
        },
      );
    typia.assert(resp);
    TestValidator.predicate("Exactly 1 filtered by product_id")(
      resp.data.length === 1,
    );
    TestValidator.equals("filter product_id matches")(resp.data[0].product_id)(
      created_items[0].product_id,
    );
  }

  // 3b. Filter by product_option_id (should yield 1)
  {
    const search_body: IAimallBackendOrderItem.IRequest = {
      order_id: order.id,
      product_option_id: created_items[1].product_option_id,
    };
    const resp =
      await api.functional.aimall_backend.seller.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: search_body,
        },
      );
    typia.assert(resp);
    TestValidator.predicate("Exactly 1 filtered by product_option_id")(
      resp.data.length === 1,
    );
    TestValidator.equals("filter product_option_id matches")(
      resp.data[0].product_option_id,
    )(created_items[1].product_option_id);
  }

  // 3c. Find by quantity (since quantity is not an allowed search param, get all then filter)
  {
    const quantity_to_find = created_items[2].quantity;
    const search_body: IAimallBackendOrderItem.IRequest = {
      order_id: order.id,
    };
    const resp =
      await api.functional.aimall_backend.seller.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: { ...search_body },
        },
      );
    typia.assert(resp);
    const matches = resp.data.filter((i) => i.quantity === quantity_to_find);
    TestValidator.predicate("Should find at least one with matching quantity")(
      matches.length > 0,
    );
    TestValidator.equals("quantity matches")(matches[0].quantity)(
      quantity_to_find,
    );
  }

  // 3d. Test pagination (limit=1 page=2)
  {
    const search_body: IAimallBackendOrderItem.IRequest = {
      order_id: order.id,
      page: 2,
      limit: 1,
    };
    const resp =
      await api.functional.aimall_backend.seller.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: search_body,
        },
      );
    typia.assert(resp);
    TestValidator.equals("pagination limit")(resp.pagination.limit)(1);
    TestValidator.equals("pagination current page")(resp.pagination.current)(2);
    TestValidator.predicate("at most 1 item on page")(resp.data.length <= 1);
  }

  // 4. Search by invalid product_id (should yield 0 results)
  {
    const search_body: IAimallBackendOrderItem.IRequest = {
      order_id: order.id,
      product_id: typia.random<string & tags.Format<"uuid">>(),
    };
    const resp =
      await api.functional.aimall_backend.seller.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: search_body,
        },
      );
    typia.assert(resp);
    TestValidator.equals("empty array on invalid product_id")(resp.data.length)(
      0,
    );
    TestValidator.equals("0 records on invalid product_id")(
      resp.pagination.records,
    )(0);
  }

  // 5. Search for order not owned (simulate with new UUID as order_id)
  await TestValidator.error("Unauthorized or forbidden for wrong order_id")(
    async () => {
      await api.functional.aimall_backend.seller.orders.orderItems.search(
        connection,
        {
          orderId: typia.random<string & tags.Format<"uuid">>(),
          body: {
            order_id: typia.random<string & tags.Format<"uuid">>(),
          },
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCoupon";

/**
 * Test updating a coupon as an administrator with valid, mutable fields.
 *
 * This test ensures that an administrator can successfully update a coupon's
 * status and expiration using allowed fields. The workflow is as follows:
 *
 * 1. Create a new coupon as a precondition.
 * 2. Update the coupon (identified by id) by changing its status and expiry date.
 * 3. Confirm the updated coupon reflects these changes.
 * 4. Confirm all other properties remain unchanged.
 */
export async function test_api_aimall_backend_administrator_coupons_test_update_coupon_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a new coupon (precondition)
  const couponCreateInput: IAimallBackendCoupon.ICreate = {
    discount_campaign_id: typia.random<string & tags.Format<"uuid">>(),
    customer_id: null,
    code: `TESTCOUPON-${RandomGenerator.alphaNumeric(8).toUpperCase()}`,
    status: "issued",
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7 days from now
  };
  const created: IAimallBackendCoupon =
    await api.functional.aimall_backend.administrator.coupons.create(
      connection,
      { body: couponCreateInput },
    );
  typia.assert(created);

  // 2. Update mutable fields (status & expires_at) for this coupon
  const updatedStatus = "expired";
  const updatedExpiry = new Date(
    Date.now() + 14 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 14 days from now
  const updateInput: IAimallBackendCoupon.IUpdate = {
    status: updatedStatus,
    expires_at: updatedExpiry,
  };
  const updated: IAimallBackendCoupon =
    await api.functional.aimall_backend.administrator.coupons.update(
      connection,
      {
        couponId: created.id,
        body: updateInput,
