import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IPageIAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendReview";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate customer review search access control (PATCH
 * /aimall-backend/customer/reviews).
 *
 * Ensures that a customer cannot access reviews authored by other customers,
 * even if they specify a different customer_id in the search filter. Confirms
 * that API enforces strict ownership: only reviews authored by the currently
 * authenticated user are returned, preventing data leakage across customer
 * boundaries.
 *
 * Steps:
 *
 * 1. Register/log in as Customer A; create a review for Product A
 * 2. Register/log in as Customer B; create a review for Product B
 * 3. As Customer A, attempt to search with Customer B's customer_id - confirm no
 *    data or only customer A's reviews are returned
 * 4. As Customer B, attempt to search with Customer A's customer_id - confirm no
 *    data or only customer B's reviews are returned
 * 5. At each step, confirm that the system does not leak information about reviews
 *    for the other customer, regardless of filter
 */
export async function test_api_aimall_backend_customer_reviews_test_customer_review_search_access_control(
  connection: api.IConnection,
) {
  // 1. Register/log in as Customer A and create review
  // (Assume connection is Customer A)
  const productIdA = typia.random<string & tags.Format<"uuid">>();
  const reviewA = await api.functional.aimall_backend.customer.reviews.create(
    connection,
    {
      body: {
        product_id: productIdA,
        title: "Customer A's review",
        body: "Great product, as A!",
        rating: 5,
      } satisfies IAimallBackendReview.ICreate,
    },
  );
  typia.assert(reviewA);

  // 2. Simulate Customer B (new session/connection object); create review
  const connectionB: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
    simulate: true, // Use simulation to isolate session identity for test
  };
  const productIdB = typia.random<string & tags.Format<"uuid">>();
  const reviewB = await api.functional.aimall_backend.customer.reviews.create(
    connectionB,
    {
      body: {
        product_id: productIdB,
        title: "Customer B's review",
        body: "Excellent product, from B!",
        rating: 4,
      } satisfies IAimallBackendReview.ICreate,
    },
  );
  typia.assert(reviewB);

  // 3. As Customer A, attempt search with Customer B's customer_id
  const resultA = await api.functional.aimall_backend.customer.reviews.search(
    connection,
    {
      body: {
        customer_id: reviewB.customer_id,
        limit: 20,
        page: 1,
      } satisfies IAimallBackendReview.IRequest,
    },
  );
  typia.assert(resultA);
  // Verify: no review from Customer B appears, and any result (if any) is from Customer A
  for (const summary of resultA.data) {
    TestValidator.notEquals("Customer A must not see B's review")(summary.id)(
      reviewB.id,
    );
    TestValidator.equals("All returned belong to A")(summary.id)(reviewA.id); // Should only match reviewA.id or be empty
  }

  // 4. As Customer B, attempt search with Customer A's customer_id
  const resultB = await api.functional.aimall_backend.customer.reviews.search(
    connectionB,
    {
      body: {
        customer_id: reviewA.customer_id,
        limit: 20,
        page: 1,
      } satisfies IAimallBackendReview.IRequest,
    },
  );
  typia.assert(resultB);
  // Likewise, B must not see A's review
  for (const summary of resultB.data) {
    TestValidator.notEquals("Customer B must not see A's review")(summary.id)(
      reviewA.id,
    );
    TestValidator.equals("All returned belong to B")(summary.id)(reviewB.id); // Should only match reviewB.id or be empty
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IPageIAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendReview";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 관리자 리뷰 다중 조건 검색 검증 (Patch Search Multi-Filter)
 *
 * - 다양한 상품/고객/평점/작성일 리뷰 데이터 생성
 * - 일부 리뷰는 soft-delete (deleted_at 처리)
 * - 관리자 권한으로 다중 필터(PATCH /aimall-backend/administrator/reviews) 검색 수행
 *
 *   - 상품 ID, 평점 범위, 생성일 범위, 그리고 조합 조건별 탐색
 * - Soft-deleted 리뷰는 조회 결과에 표시되지 않아야 함을 단계별 검증
 * - 페이지네이션 및 메타데이터(total, page) 정확성 보장
 */
export async function test_api_aimall_backend_administrator_reviews_test_admin_search_reviews_multi_filters_success(
  connection: api.IConnection,
) {
  // 1. 상품, 평점, 작성일 다양화하여 리뷰 데이터 다수 생성 (고객ID 직접 비교 불가)
  const products = ArrayUtil.repeat(5)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const customers = ArrayUtil.repeat(3)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const allReviews: IAimallBackendReview[] = [];

  for (const product_id of products) {
    for (const customer_id of customers) {
      const rating = RandomGenerator.pick([1, 2, 3, 4, 5]);
      const daysAgo = RandomGenerator.pick([0, 1, 2, 5, 10]);
      const review: IAimallBackendReview =
        await api.functional.aimall_backend.customer.reviews.create(
          connection,
          {
            body: {
              product_id,
              title: `Review P${product_id.slice(0, 4)} R${rating}`,
              body: RandomGenerator.content()()(),
              rating,
            } satisfies IAimallBackendReview.ICreate,
          },
        );
      typia.assert(review);
      review.created_at = new Date(
        Date.now() - daysAgo * 24 * 3600 * 1000,
      ).toISOString();
      review.updated_at = review.created_at;
      allReviews.push(review);
    }
  }

  // 2. rating=1 리뷰들을 soft-delete
  const softDeleted: IAimallBackendReview[] = [];
  for (const review of allReviews) {
    if (review.rating === 1) {
      await api.functional.aimall_backend.customer.reviews.erase(connection, {
        reviewId: review.id,
      });
      review.deleted_at = new Date().toISOString();
      softDeleted.push(review);
    }
  }

  // activeReviews: deleted 리뷰 제외한 나머지 리뷰
  const activeReviews = allReviews.filter((r) => !softDeleted.includes(r));

  // 3-a. 상품 ID 조건 단일 필터 테스트
  const filterProductId = products[1];
  const resByProduct =
    await api.functional.aimall_backend.administrator.reviews.search(
      connection,
      { body: { product_id: filterProductId } },
    );
  typia.assert(resByProduct);
  TestValidator.predicate("상품 ID 검색 시 soft-delete 리뷰 없음")(
    resByProduct.data.every(
      (r) =>
        r.product_id === filterProductId &&
        !softDeleted.find((d) => d.id === r.id),
    ),
  );

  // 3-b. 평점 하한 필터 테스트 (>= 4)
  const ratingMin = 4;
  const resByRating =
    await api.functional.aimall_backend.administrator.reviews.search(
      connection,
      { body: { rating_min: ratingMin } },
    );
  typia.assert(resByRating);
  TestValidator.predicate("평점 하한 필터링, soft-delete 제외")(
    resByRating.data.every(
      (r) => r.rating >= ratingMin && !softDeleted.find((d) => d.id === r.id),
    ),
  );

  // 3-c. 최근 일주일 작성 리뷰 필터
  const fromTime = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString();
  const resByDate =
    await api.functional.aimall_backend.administrator.reviews.search(
      connection,
      { body: { created_from: fromTime } },
    );
  typia.assert(resByDate);
  TestValidator.predicate("최근 작성일 범위내, soft-delete 제외")(
    resByDate.data.every(
      (r) =>
        r.created_at >= fromTime && !softDeleted.find((d) => d.id === r.id),
    ),
  );

  // 3-d. 상품 ID + 평점 상한 복합 조건
  const ratingMax = 3;
  const resCombined =
    await api.functional.aimall_backend.administrator.reviews.search(
      connection,
      { body: { product_id: filterProductId, rating_max: ratingMax } },
    );
  typia.assert(resCombined);
  TestValidator.predicate("상품+평점 상한 복합, soft-delete 없음")(
    resCombined.data.every(
      (r) =>
        r.product_id === filterProductId &&
        r.rating <= ratingMax &&
        !softDeleted.find((d) => d.id === r.id),
    ),
  );

  // 4. 페이지네이션 및 메타데이터 검증
  const pageLimit = 2;
  const paged =
    await api.functional.aimall_backend.administrator.reviews.search(
      connection,
      { body: { limit: pageLimit, page: 1 } },
    );
  typia.assert(paged);
  TestValidator.equals("pagination.limit")(paged.pagination.limit)(pageLimit);
  TestValidator.equals("pagination.current")(paged.pagination.current)(1);
  TestValidator.equals("pagination.records")(paged.pagination.records)(
    activeReviews.length,
  );
  TestValidator.equals("pagination.pages")(paged.pagination.pages)(
    Math.ceil(activeReviews.length / pageLimit),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IPageIAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendReview";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the administrator review search endpoint with pagination and sorting
 * options under high data load.
 *
 * This test creates a large batch of reviews across multiple products, then
 * performs advanced search requests using PATCH
 * /aimall-backend/administrator/reviews with different sorting (by rating
 * ascending/descending, by creation date ascending/descending) and pagination
 * (various pages and page sizes). The test verifies:
 *
 * - Review creation and data integrity
 * - That search results are sorted according to the requested criteria
 * - That pagination works: correct number of results, page count, and boundaries
 * - Correct handling of edge cases (first/last page, fewer results than page
 *   size, last partial page)
 *
 * Steps:
 *
 * 1. Create N_PRODUCTS (e.g., 5) dummy product IDs.
 * 2. For each product, create N_REVIEWS (e.g., 10) reviews with varying ratings
 *    and timestamps.
 * 3. Execute administrator search with PATCH, requesting sorting by rating
 *    (asc/desc), and by created_at (asc/desc).
 * 4. Use different values for `page` and `limit`, check that search results match
 *    expected sort order and pagination.
 * 5. Validate that result arrays, pagination metadata, and record counts are
 *    correct.
 */
export async function test_api_aimall_backend_administrator_reviews_test_admin_review_search_sort_and_pagination(
  connection: api.IConnection,
) {
  // Constants for dataset size
  const N_PRODUCTS = 5;
  const N_REVIEWS_PER_PRODUCT = 10;

  // 1. Create product IDs
  const productIds: (string & tags.Format<"uuid">)[] = ArrayUtil.repeat(
    N_PRODUCTS,
  )(() => typia.random<string & tags.Format<"uuid">>());
  // 2. Create reviews for each product
  const reviews: IAimallBackendReview[] = [];
  for (const productId of productIds) {
    for (let i = 0; i < N_REVIEWS_PER_PRODUCT; ++i) {
      const rating = (i % 5) + 1; // cycle 1-5 ratings
      const review: IAimallBackendReview =
        await api.functional.aimall_backend.customer.reviews.create(
          connection,
          {
            body: {
              product_id: productId,
              title: `Review ${i + 1} for product ${productId}`,
              body: `Body for review ${i + 1} on product ${productId}`,
              rating,
            } satisfies IAimallBackendReview.ICreate,
          },
        );
      typia.assert(review);
      reviews.push(review);
    }
  }

  // Helper to run a search and validate sorting/paging
  async function validateSortPage({
    sortKey,
    sortOrder,
    page,
    limit,
    productId,
  }: {
    sortKey: "rating" | "created_at";
    sortOrder: "asc" | "desc";
    page: number;
    limit: number;
    productId?: string;
  }) {
    // Prepare expected
    let filtered = [...reviews];
    if (productId)
      filtered = filtered.filter((r) => r.product_id === productId);
    filtered.sort((a, b) => {
      if (sortKey === "rating")
        return sortOrder === "asc" ? a.rating - b.rating : b.rating - a.rating;
      else
        return sortOrder === "asc"
          ? a.created_at.localeCompare(b.created_at)
          : b.created_at.localeCompare(a.created_at);
    });
    // Pagination
    const start = (page - 1) * limit;
    const end = start + limit;
    const paged = filtered.slice(start, end);
    const totalRecords = filtered.length;
    const totalPages = Math.ceil(totalRecords / limit);

    // 3. Execute search
    const result =
      await api.functional.aimall_backend.administrator.reviews.search(
        connection,
        {
          body: {
            ...(productId ? { product_id: productId } : {}),
            limit,
            page,
          } satisfies IAimallBackendReview.IRequest,
        },
      );
    typia.assert(result);
    TestValidator.equals("page current")(result.pagination.current)(page);
    TestValidator.equals("page limit")(result.pagination.limit)(limit);
    TestValidator.equals("page total records")(result.pagination.records)(
      totalRecords,
    );
    TestValidator.equals("page count")(result.pagination.pages)(totalPages);
    TestValidator.equals("result count")(result.data.length)(paged.length);
    for (let i = 0; i < paged.length; ++i) {
      TestValidator.equals(`result ${i} id`)(result.data[i].id)(paged[i].id);
      TestValidator.equals(`result ${i} rating`)(result.data[i].rating)(
        paged[i].rating,
      );
      TestValidator.equals(`result ${i} created_at`)(result.data[i].created_at)(
        paged[i].created_at,
      );
    }
  }
  // 4. Try various pages and sorting
  await validateSortPage({
    sortKey: "rating",
    sortOrder: "asc",
    page: 1,
    limit: 10,
  });
  await validateSortPage({
    sortKey: "rating",
    sortOrder: "desc",
    page: 2,
    limit: 8,
  });
  await validateSortPage({
    sortKey: "created_at",
    sortOrder: "asc",
    page: 1,
    limit: 7,
  });
  await validateSortPage({
    sortKey: "created_at",
    sortOrder: "desc",
    page: 2,
    limit: 12,
  });
  // 5. Edge: last partial page
  const limit = 13;
  const total = N_PRODUCTS * N_REVIEWS_PER_PRODUCT;
  const lastPage = Math.ceil(total / limit);
  await validateSortPage({
    sortKey: "rating",
    sortOrder: "asc",
    page: lastPage,
    limit,
  });
}

