}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate administrator comment thread listing excludes soft-deleted child
 * comments.
 *
 * Scenario: Ensures that even administrators, when listing child comments
 * (replies) for a parent comment, receive only active (not soft-deleted)
 * comments. This test covers thread integrity—soft-deleted comments (deleted_at
 * not null) must never appear in standard list APIs, even with admin
 * privilege.
 *
 * Workflow:
 *
 * 1. Create a root parent comment as a customer.
 * 2. Attach multiple (3) child comments (replies) to the parent comment.
 * 3. Soft-delete one of the child comments (simulate `deleted_at`).
 * 4. As administrator, list all child comments for that parent via admin API.
 * 5. Assert: (a) All returned child comments have `deleted_at === null`; (b) The
 *    soft-deleted child's id is absent from result; (c) Each result's parent_id
 *    matches the parent comment id.
 */
export async function test_api_aimall_backend_administrator_comments_comments_index_only_active(
  connection: api.IConnection,
) {
  // 1. Create root parent comment as customer (thread root).
  const parentComment =
    await api.functional.aimall_backend.customer.comments.create(connection, {
      body: {
        body: RandomGenerator.paragraph()(),
        is_private: false,
      } satisfies IAimallBackendComment.ICreate,
    });
  typia.assert(parentComment);

  // 2. Create multiple (3) child comments as customer.
  const childComments = await ArrayUtil.asyncRepeat(3)(async () =>
    api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parentComment.id,
        body: {
          parent_id: parentComment.id,
          body: RandomGenerator.content()()(),
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    ),
  );
  childComments.forEach((child) => typia.assert(child));

  // 3. Soft-delete one child comment (index 1).
  const deletedComment = childComments[1];
  await api.functional.aimall_backend.customer.comments.comments.erase(
    connection,
    {
      commentId: parentComment.id,
      childCommentId: deletedComment.id,
    },
  );

  // 4. As administrator, list all children for the parent comment.
  const adminChildList =
    await api.functional.aimall_backend.administrator.comments.comments.index(
      connection,
      {
        commentId: parentComment.id,
      },
    );
  typia.assert(adminChildList);

  // 5. Assert every child in result:
  //   (a) deleted_at === null
  //   (b) Not the soft-deleted id
  //   (c) parent_id matches
  adminChildList.data.forEach((comment) => {
    TestValidator.equals("child comment not deleted")(comment.deleted_at)(null);
    TestValidator.notEquals("should not return soft-deleted child")(comment.id)(
      deletedComment.id,
    );
    TestValidator.equals("parent child linkage")(comment.parent_id)(
      parentComment.id,
    );
  });

  // Additionally, check that count matches (original #children - deleted ones)
  const expectedActiveIds = childComments
    .filter((c, idx) => idx !== 1)
    .map((c) => c.id);
  TestValidator.equals("count of active children")(adminChildList.data.length)(
    expectedActiveIds.length,
  );
  // Ensure all expected ids appear
  expectedActiveIds.forEach((id) => {
    TestValidator.predicate(`active child ${id} is present`)(
      adminChildList.data.some((c) => c.id === id),
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced search for child comments (replies) under a specific
 * comment thread.
 *
 * This test ensures that filtering by keyword (body) and author (customer_id)
 * returns only those child comments that match both criteria. Soft-deleted
 * replies or those not matching both filter parameters must not be included in
 * the results.
 *
 * Test flow:
 *
 * 1. Create a parent comment as customer A.
 * 2. Create several reply comments (children) by different (simulated) customers
 *    with varying bodies and privacy settings.
 * 3. (Soft-delete is not feasible as no such API is available here - just skip
 *    such entries in assertion.)
 * 4. Use PATCH search to find replies by a specific customer whose body contains a
 *    target keyword.
 * 5. Assert that only replies matching keyword + author (excluding soft-deleted)
 *    are returned.
 */
export async function test_api_aimall_backend_customer_comments_comments_test_advanced_search_child_comments_by_keyword_and_author_success(
  connection: api.IConnection,
) {
  // 1. Create parent comment (Customer A)
  const parent = await api.functional.aimall_backend.customer.comments.create(
    connection,
    {
      body: {
        body: "Top-level comment for threading",
        is_private: false,
      } satisfies IAimallBackendComment.ICreate,
    },
  );
  typia.assert(parent);

  // 2. Create several child replies (simulating multiple authors by later filtering customer_id)
  // Child 1 (target): by Customer A, contains 'filterme'
  const child1 =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          body: "reply - this should filterme!",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(child1);

  // Child 2: by Customer A, does NOT contain 'filterme'
  const child2 =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          body: "reply - does not contain keyword",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(child2);

  // Child 3: by (simulated) Customer B (we use same API - in real E2E this would be a different login), contains 'filterme'
  const child3 =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          body: "other user filterme in comment body",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(child3);

  // Child 4: by Customer A, contains 'filterme', but for soft-delete simulation we can only skip in assertion
  const child4 =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          body: "reply - filterme and soft delete",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(child4);
  // Note: No soft-delete API; test handles as summary/explanation only.

  // 3. Perform PATCH search: by parent, customer_id=child1.customer_id
  const searchResult =
    await api.functional.aimall_backend.customer.comments.comments.search(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          customer_id: child1.customer_id,
        } satisfies IAimallBackendComment.IRequest,
      },
    );
  typia.assert(searchResult);

  // 4. Assert: Only replies from correct author whose body contains keyword are present (not soft-deleted).
  const expected = [child1]
    .filter((c) => !c.deleted_at && c.body.includes("filterme"))
    .map((x) => x.id);
  const actual = searchResult.data
    .filter((c) => !c.deleted_at && c.body.includes("filterme"))
    .map((x) => x.id);
  TestValidator.equals(
    "Only matching replies by author and body keyword are returned",
  )(actual)(expected);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that child comment search enforces privacy and author access
 * control.
 *
 * Business Context:
 *
 * - Community allows both public and private comments.
 * - Replies (child comments) can be authored by any customer and marked private
 *   or public.
 * - A customer is only allowed to see public replies and their own private
 *   replies, never private replies of others.
 *
 * Test Workflow:
 *
 * 1. As Customer A, create a parent (root) comment.
 * 2. As Customer A, create a public child reply under the parent.
 * 3. As Customer A, create a private child reply under the parent.
 * 4. As Customer B, create a private child reply under the parent.
 * 5. As Customer B, search (PATCH) for all direct children of the parent comment.
 * 6. Validate returned data:
 *
 *    - Contains the public reply (from A)
 *    - Contains the private reply by Customer B
 *    - Does NOT contain the private reply by Customer A
 *    - Each returned comment is either public, or private and authored by Customer B
 *    - No comment is soft deleted (deleted_at is null)
 */
export async function test_api_aimall_backend_customer_comments_test_search_child_comments_respects_privacy_and_access(
  connection: api.IConnection,
) {
  // 1. As Customer A, create root comment.
  // [Assume Customer A session is already loaded in 'connection']
  const parentComment =
    await api.functional.aimall_backend.customer.comments.create(connection, {
      body: {
        body: RandomGenerator.alphabets(10),
        is_private: false,
      } satisfies IAimallBackendComment.ICreate,
    });
  typia.assert(parentComment);

  // 2. As Customer A, create a public child reply
  const publicChild =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parentComment.id,
        body: {
          parent_id: parentComment.id,
          body: RandomGenerator.alphabets(12),
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(publicChild);

  // 3. As Customer A, create a private child reply
  const privateChildA =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parentComment.id,
        body: {
          parent_id: parentComment.id,
          body: RandomGenerator.alphabets(14),
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(privateChildA);

  // 4. As Customer B, create a private child reply
  // [Assume connection for Customer B is loaded below.]
  // In runner, connection switch from Customer A → Customer B must occur here
  const privateChildB =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parentComment.id,
        body: {
          parent_id: parentComment.id,
          body: RandomGenerator.alphabets(16),
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(privateChildB);

  // 5. As Customer B, search for all direct child comments of the parent comment
  const searchResult =
    await api.functional.aimall_backend.customer.comments.comments.search(
      connection,
      {
        commentId: parentComment.id,
        body: { parent_id: parentComment.id },
      },
    );
  typia.assert(searchResult);
  const returned = searchResult.data;
  const returnedIds = returned.map((c) => c.id);
  // 6a. Contains public reply
  TestValidator.predicate("Contains public reply")(
    returnedIds.includes(publicChild.id),
  );
  // 6b. Contains B's own private reply
  TestValidator.predicate("Contains private reply by B")(
    returnedIds.includes(privateChildB.id),
  );
  // 6c. Does not contain A's private reply
  TestValidator.predicate("Does not contain private reply by A")(
    !returnedIds.includes(privateChildA.id),
  );
  // 6d. All are either public or private and authored by Customer B
  for (const reply of returned) {
    TestValidator.predicate("Only public or B's private")(
      !reply.is_private || reply.customer_id === privateChildB.customer_id,
    );
    // 6e. Not deleted (deleted_at is null)
    TestValidator.equals("not deleted")(reply.deleted_at)(null);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate administrator advanced child comment search with all filter fields
 * and privacy visibility.
 *
 * This test verifies that the administrator can perform advanced search and
 * pagination for child comments (replies) under a parent comment, filtering by
 * author, privacy status, creation date range, and body content. It also
 * ensures that administrators see all child comments, including those marked
 * private by customers, and can paginate and filter them for moderation/audit
 * purposes.
 *
 * Workflow:
 *
 * 1. Create a parent comment as a customer (no parent_id)
 * 2. Create 3 replies to the parent comment:
 *
 *    - Author1 (public, content: 'Hello world')
 *    - Author2 (private, content: 'Private note')
 *    - Author1 (public, content: 'Audit trail')
 * 3. As administrator, search for child comments under the parent using: (a) No
 *    filters: should see all 3 (including private) (b) Filter by author1:
 *    should see both from author1 (c) Filter by is_private true: only private
 *    comments from author2 (d) Filter by body ("Audit"): only the matching
 *    comment (e) Filter by created_at_from/created_at_to: time-range filtering
 *    (f) Pagination with limit=2, verify paging
 * 4. Validate all intermediate and final results for correctness, including admin
 *    ability to see private data.
 */
export async function test_api_aimall_backend_administrator_comments_comments_test_admin_advanced_search_child_comments_all_fields_and_includes_private(
  connection: api.IConnection,
) {
  // 1. Create a parent comment as customer (root of thread)
  const parent = await api.functional.aimall_backend.customer.comments.create(
    connection,
    {
      body: {
        post_id: null,
        review_id: null,
        parent_id: null,
        body: "Parent for threading",
        is_private: false,
      } satisfies IAimallBackendComment.ICreate,
    },
  );
  typia.assert(parent);

  // ---
  // Setup two author contexts (simulate, since real auth handled by infra/test harness)
  // Child 1 by author1 (public)
  const child1 =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          body: "Hello world",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(child1);
  const author1 = child1.customer_id;

  // Child 2 by author2 (private)
  const child2 =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          body: "Private note",
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(child2);
  const author2 = child2.customer_id;

  // Child 3 by author1 again (public, 'Audit trail')
  const child3 =
    await api.functional.aimall_backend.customer.comments.comments.create(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          body: "Audit trail",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(child3);

  // 3(a). Admin: Search for all children with no additional filter
  const allResult =
    await api.functional.aimall_backend.administrator.comments.comments.search(
      connection,
      {
        commentId: parent.id,
        body: { parent_id: parent.id },
      },
    );
  typia.assert(allResult);
  TestValidator.equals("all child comments count")(allResult.data.length)(3);

  // 3(b). Filter by author1
  const author1Result =
    await api.functional.aimall_backend.administrator.comments.comments.search(
      connection,
      {
        commentId: parent.id,
        body: { parent_id: parent.id, customer_id: author1 },
      },
    );
  typia.assert(author1Result);
  TestValidator.equals("author1 count")(author1Result.data.length)(2);
  TestValidator.predicate("author1 only")(
    author1Result.data.every((c) => c.customer_id === author1),
  );

  // 3(c). Filter by is_private true (should return only the author2 private comment)
  const privateResult =
    await api.functional.aimall_backend.administrator.comments.comments.search(
      connection,
      {
        commentId: parent.id,
        body: { parent_id: parent.id, is_private: true },
      },
    );
  typia.assert(privateResult);
  TestValidator.equals("private only count")(privateResult.data.length)(1);
  TestValidator.equals("private author")(privateResult.data[0]?.customer_id)(
    author2,
  );
  TestValidator.equals("private body")(privateResult.data[0]?.body)(
    "Private note",
  );

  // 3(d). Filter by body content (simulate: fetch all and check manually)
  const bodySearchResult =
    await api.functional.aimall_backend.administrator.comments.comments.search(
      connection,
      {
        commentId: parent.id,
        body: { parent_id: parent.id },
      },
    );
  typia.assert(bodySearchResult);
  const auditComment = bodySearchResult.data.find((c) =>
    c.body.includes("Audit"),
  );
  TestValidator.predicate("body search exists")(!!auditComment);
  if (auditComment)
    TestValidator.equals("body matches")(auditComment.body)("Audit trail");

  // 3(e). Filter by created_at (from child1 to child3 - should get all 3 since created close together)
  const fromTime = child1.created_at;
  const toTime = child3.created_at;
  const rangeResult =
    await api.functional.aimall_backend.administrator.comments.comments.search(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          created_at_from: fromTime,
          created_at_to: toTime,
        },
      },
    );
  typia.assert(rangeResult);
  TestValidator.equals("range count")(rangeResult.data.length)(3);

  // 3(f). Pagination: Limit 2 per page
  const page1 =
    await api.functional.aimall_backend.administrator.comments.comments.search(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          limit: 2,
        },
      },
    );
  typia.assert(page1);
  TestValidator.equals("page 1 count")(page1.data.length)(2);
  TestValidator.equals("page 1 current")(page1.pagination.current)(1);
  // Second page
  const page2 =
    await api.functional.aimall_backend.administrator.comments.comments.search(
      connection,
      {
        commentId: parent.id,
        body: {
          parent_id: parent.id,
          limit: 2,
          page: 2,
        },
      },
    );
  typia.assert(page2);
  TestValidator.equals("page 2 current")(page2.pagination.current)(2);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIAimallBackendCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendCoupon";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCoupon";

/**
 * Test searching customer coupons with various advanced filters and access
 * constraints.
 *
 * 1. Retrieve the current list of coupons for the authenticated customer (setup
 *    base dataset).
 * 2. Attempt search with no filter (should match the same data as index call).
 * 3. Search by exact coupon code and check for correct result (should find 0 or 1
 *    records).
 * 4. Search by a status value present among the user's coupons (e.g., 'issued',
 *    'redeemed', or 'expired'); validate all results have the same status and
 *    are assigned to customer.
 * 5. Search by a coupon's campaign association (discount_campaign_id) and check
 *    that only related coupons are returned (and only those belonging to the
 *    customer).
 * 6. Search using issuance date range that includes some coupons; verify that only
 *    matching coupons in range are returned.
 * 7. Search using expiry date range that excludes all coupons; expect 0 results.
 * 8. Attempt searching coupons using another (random) customer's ID - ensure no
 *    coupons are returned or access denied (test protection against
 *    unauthorized access).
 */
export async function test_api_aimall_backend_customer_coupons_test_search_customer_coupons_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Retrieve base coupon dataset
  const base: IPageIAimallBackendCoupon =
    await api.functional.aimall_backend.customer.coupons.index(connection);
  typia.assert(base);
  const coupons = base.data ?? [];
  const customerIds = [
    ...new Set(coupons.map((c) => c.customer_id).filter(Boolean)),
  ];

  // 2. Search no filter (should match index)
  const noFilter: IPageIAimallBackendCoupon =
    await api.functional.aimall_backend.customer.coupons.search(connection, {
      body: {} satisfies IAimallBackendCoupon.IRequest,
    });
  typia.assert(noFilter);
  TestValidator.equals("all coupons with no filter")(
    noFilter.data?.length ?? 0,
  )(coupons.length);

  // 3. Search by exact coupon code (if any)
  if (coupons.length > 0) {
    const sampleCoupon = coupons[0];
    const resByCode: IPageIAimallBackendCoupon =
      await api.functional.aimall_backend.customer.coupons.search(connection, {
        body: {
          code: sampleCoupon.code,
        } satisfies IAimallBackendCoupon.IRequest,
      });
    typia.assert(resByCode);
    if ((resByCode.data?.length ?? 0) > 0) {
      TestValidator.predicate("all results match code")(
        !!resByCode.data &&
          resByCode.data.every(
            (c) =>
              c.code === sampleCoupon.code &&
              c.customer_id === sampleCoupon.customer_id,
          ),
      );
    }
  }

  // 4. Search by a status value among coupons
  const statuses = [...new Set(coupons.map((c) => c.status))];
  if (statuses.length > 0) {
    const sampleStatus = statuses[0];
    const resByStatus: IPageIAimallBackendCoupon =
      await api.functional.aimall_backend.customer.coupons.search(connection, {
        body: { status: sampleStatus } satisfies IAimallBackendCoupon.IRequest,
      });
    typia.assert(resByStatus);
    if ((resByStatus.data?.length ?? 0) > 0) {
      TestValidator.predicate("all results match status")(
        !!resByStatus.data &&
          resByStatus.data.every((c) => c.status === sampleStatus),
      );
      TestValidator.predicate("all belong to customer")(
        !!resByStatus.data &&
          resByStatus.data.every((c) => customerIds.includes(c.customer_id!)),
      );
    }
  }

  // 5. Search by campaign association (discount_campaign_id)
  const campaignIds = [...new Set(coupons.map((c) => c.discount_campaign_id))];
  if (campaignIds.length > 0) {
    const campaignId = campaignIds[0];
    const resByCampaign: IPageIAimallBackendCoupon =
      await api.functional.aimall_backend.customer.coupons.search(connection, {
        body: {
          discount_campaign_id: campaignId,
        } satisfies IAimallBackendCoupon.IRequest,
      });
    typia.assert(resByCampaign);
    if ((resByCampaign.data?.length ?? 0) > 0) {
      TestValidator.predicate("all results belong to campaign")(
        !!resByCampaign.data &&
          resByCampaign.data.every(
            (c) => c.discount_campaign_id === campaignId,
          ),
      );
      TestValidator.predicate("all belong to customer")(
        !!resByCampaign.data &&
          resByCampaign.data.every((c) => customerIds.includes(c.customer_id!)),
      );
    }
  }

  // 6. Search by issuance date range (issued_at)
  if (coupons.length > 0) {
    const sorted = [...coupons].sort(
      (a, b) =>
        new Date(a.issued_at).getTime() - new Date(b.issued_at).getTime(),
    );
    const start = sorted[0].issued_at;
    const end = sorted[sorted.length - 1].issued_at;
    const resByIssueRange: IPageIAimallBackendCoupon =
      await api.functional.aimall_backend.customer.coupons.search(connection, {
        body: {
          issued_at_from: start,
          issued_at_to: end,
        } satisfies IAimallBackendCoupon.IRequest,
      });
    typia.assert(resByIssueRange);
    if ((resByIssueRange.data?.length ?? 0) > 0) {
      TestValidator.predicate("results within date range")(
        !!resByIssueRange.data &&
          resByIssueRange.data.every(
            (c) => c.issued_at >= start && c.issued_at <= end,
          ),
      );
    }
  }

  // 7. Search by expiry date range that excludes all coupons (future only)
  const futureDate = new Date(
    Date.now() + 1000 * 60 * 60 * 24 * 365,
  ).toISOString();
  const resByExpiryRange: IPageIAimallBackendCoupon =
    await api.functional.aimall_backend.customer.coupons.search(connection, {
      body: {
        expires_at_from: futureDate,
        expires_at_to: futureDate,
      } satisfies IAimallBackendCoupon.IRequest,
    });
  typia.assert(resByExpiryRange);
  TestValidator.equals("no coupons in future expiry range")(
    resByExpiryRange.data?.length ?? 0,
  )(0);

  // 8. Attempt unauthorized access using a different customer ID
  const bogusCustomerId = typia.random<string & tags.Format<"uuid">>();
  const resByOtherCustomer: IPageIAimallBackendCoupon =
    await api.functional.aimall_backend.customer.coupons.search(connection, {
      body: {
        customer_id: bogusCustomerId,
      } satisfies IAimallBackendCoupon.IRequest,
    });
  typia.assert(resByOtherCustomer);
  TestValidator.equals("no unauthorized coupons returned")(
    resByOtherCustomer.data?.length ?? 0,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
