/**
 * Validate that an administrator can retrieve the full detail of any coupon in
 * the system with only its couponId, regardless of whether it is assigned to a
 * customer or its current status.
 *
 * This test ensures correct backend exposure of coupons for admin: covers
 * issued, redeemed, and expired statuses, and both assigned and unassigned
 * coupons, verifying all fields in the returned dataset.
 *
 * Step-by-step process:
 *
 * 1. Retrieve the full list of coupons as an administrator (using the dependency
 *    API).
 * 2. Select at least one coupon from each status type in the result (issued,
 *    redeemed, expired; if available) and note their couponIds for detail
 *    querying.
 * 3. For each selected couponId, fetch the detailed coupon record using the
 *    GET-by-couponId endpoint.
 * 4. Assert that all returned fields (id, discount_campaign_id, customer_id, code,
 *    status, issued_at, expires_at, redeemed_at) match those in the original
 *    list (if present) and satisfy schema requirements.
 * 5. Ensure no error is thrown for any couponId and that all types of coupons
 *    (regardless of assignment or status) are accessible.
 */
export async function test_api_aimall_backend_administrator_coupons_get_coupon_detail_admin_any_coupon(
  connection: api.IConnection,
) {
  // 1. Retrieve list of all coupons for admin
  const page =
    await api.functional.aimall_backend.administrator.coupons.index(connection);
  typia.assert(page);
  const data = page.data ?? [];
  TestValidator.predicate("at least one coupon in system")(data.length > 0);

  // 2. Select coupons by unique status (issued, redeemed, expired, if present)
  const statuses = ["issued", "redeemed", "expired"];
  const chosen: IAimallBackendCoupon[] = [];
  for (const status of statuses) {
    const found = data.find((c) => c.status === status);
    if (found) chosen.push(found);
  }
  // If not enough status coverage, still pick up to three arbitrary coupons
  while (chosen.length < 3 && chosen.length < data.length) {
    const maybe = data.find((c) => !chosen.includes(c));
    if (maybe) chosen.push(maybe);
    else break;
  }
  TestValidator.predicate("have at least one coupon to test")(
    chosen.length > 0,
  );

  // 3. For each coupon, fetch detail by couponId and validate
  for (const coupon of chosen) {
    const detail = await api.functional.aimall_backend.administrator.coupons.at(
      connection,
      { couponId: coupon.id },
    );
    typia.assert(detail);
    // 4. Validate all major properties match and are present
    for (const key of [
      "id",
      "discount_campaign_id",
      "customer_id",
      "code",
      "status",
      "issued_at",
      "expires_at",
      "redeemed_at",
    ]) {
      TestValidator.equals(`${key} must match detail/list`)(
        (detail as any)[key],
      )((coupon as any)[key]);
    }
    // 5. No error thrown: test will fail if exception occurs
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCoupon";
import type { IPageIAimallBackendDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendDiscountCampaign";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendDiscountCampaign";

/**
 * Test creation of a new coupon voucher by an administrator with a unique code
 * and valid campaign association.
 *
 * Validates that an administrator can successfully create a coupon using a
 * unique code and a real discount campaign. Ensures required fields are
 * honored—association, unique code, issuance/expiry, and initial status. Also
 * verifies that code uniqueness is enforced (duplicate creation fails).
 *
 * Test Flow:
 *
 * 1. Fetch discount campaigns visible to the administrator
 * 2. Choose an active/available campaign for test association
 * 3. Generate a unique coupon code and set issued/expiry datetimes
 * 4. Submit coupon creation request via API
 * 5. Assert response fields: campaign link, code, status, timestamps, and redeemed
 *    state
 * 6. Attempt duplicate creation—expect business error due to code uniqueness
 */
export async function test_api_coupons_test_create_coupon_success_unique_code(
  connection: api.IConnection,
) {
  // 1. Fetch discount campaigns
  const campaignsPage =
    await api.functional.aimall_backend.administrator.discountCampaigns.index(
      connection,
    );
  typia.assert(campaignsPage);

  // 2. Pick an active campaign or any available
  const campaign =
    campaignsPage.data.find((c) => c.status === "active") ??
    campaignsPage.data[0];
  if (!campaign)
    throw new Error("No discount campaigns available for coupon creation test");

  // 3. Generate unique coupon code and set times
  const uniqueCode = `UNIQUE-${RandomGenerator.alphaNumeric(8)}`;
  const now = new Date();
  const issued_at = now.toISOString();
  const expires_at = new Date(now.getTime() + 24 * 3600 * 1000).toISOString(); // +1 day
  const couponCreate = {
    discount_campaign_id: campaign.id,
    code: uniqueCode,
    status: "issued",
    issued_at,
    expires_at,
  } satisfies IAimallBackendCoupon.ICreate;

  // 4. Submit coupon create API
  const created =
    await api.functional.aimall_backend.administrator.coupons.create(
      connection,
      { body: couponCreate },
    );
  typia.assert(created);

  // 5. Validate returned coupon
  TestValidator.equals("campaign association")(created.discount_campaign_id)(
    couponCreate.discount_campaign_id,
  );
  TestValidator.equals("coupon code")(created.code)(couponCreate.code);
  TestValidator.equals("status")(created.status)("issued");
  TestValidator.equals("issued_at")(created.issued_at)(couponCreate.issued_at);
  TestValidator.equals("expires_at")(created.expires_at)(
    couponCreate.expires_at,
  );
  TestValidator.equals("unredeemed")(created.redeemed_at)(null);

  // 6. Attempt duplicate code (code uniqueness)
  await TestValidator.error("duplicate code not allowed")(async () => {
    await api.functional.aimall_backend.administrator.coupons.create(
      connection,
      { body: couponCreate },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
