import type { IAimallBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendChannel";
import type { IAimallBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSection";

/**
 * Validate section code uniqueness constraint under a channel.
 *
 * This test verifies that within a single channel, section codes must be
 * unique. It adds a new channel, then creates a section under it with a
 * specific code. Next, it attempts to create a second section under the same
 * channel using an identical section code, and expects a uniqueness violation
 * (error) to occur on the second attempt. This confirms that the backend
 * enforces code-uniqueness per channel for sections.
 *
 * 1. Create a new channel (code and name randomly generated, enabled)
 * 2. Create the first section under that channel
 *
 *    - Use a unique section code, name, display order, enabled=true
 * 3. Attempt to create a second section under the same channel using the exact
 *    same code (different name allowed)
 * 4. Validate that an error is thrown for uniqueness constraint violation on code
 */
export async function test_api_aimall_backend_administrator_channels_sections_test_create_section_duplicate_code_within_channel_fails(
  connection: api.IConnection,
) {
  // 1. Create a new channel
  const channel =
    await api.functional.aimall_backend.administrator.channels.create(
      connection,
      {
        body: {
          code: RandomGenerator.alphaNumeric(6),
          name: RandomGenerator.alphabets(8),
          enabled: true,
        } satisfies IAimallBackendChannel.ICreate,
      },
    );
  typia.assert(channel);

  // 2. Create the first section
  const sectionCode = RandomGenerator.alphaNumeric(5);
  const section1 =
    await api.functional.aimall_backend.administrator.channels.sections.create(
      connection,
      {
        channelId: channel.id,
        body: {
          channel_id: channel.id,
          code: sectionCode,
          name: RandomGenerator.alphabets(7),
          display_order: 1,
          enabled: true,
        } satisfies IAimallBackendSection.ICreate,
      },
    );
  typia.assert(section1);
  TestValidator.equals("section1 code")(section1.code)(sectionCode);

  // 3. Attempt to create a second section with the same code under the same channel
  await TestValidator.error(
    "duplicate section code within channel should fail",
  )(async () => {
    await api.functional.aimall_backend.administrator.channels.sections.create(
      connection,
      {
        channelId: channel.id,
        body: {
          channel_id: channel.id,
          code: sectionCode, // same code as above
          name: RandomGenerator.alphabets(7),
          display_order: 2,
          enabled: true,
        } satisfies IAimallBackendSection.ICreate,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";

/**
 * E2E test that verifies a seller can create a comment on their own post with
 * valid data.
 *
 * This test case checks that a seller (authenticated) is able to successfully
 * comment on a community post they own, given valid required data fields.
 *
 * Steps:
 *
 * 1. Create a community post as the seller (dependency)
 * 2. Create a comment on that post with valid data (body, is_private, and optional
 *    nullable fields)
 * 3. Assert returned comment fields are populated
 * 4. Assert comment.post_id equals created post id
 *
 * Note: The author identity (seller/customer id) is not present in the comment
 * DTO, so cannot be directly validated.
 */
export async function test_api_aimall_backend_seller_posts_comments_test_create_post_comment_as_seller_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a community post as seller (dependency)
  const post = await api.functional.aimall_backend.seller.posts.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(1),
        is_private: false,
      } satisfies IAimallBackendPost.ICreate,
    },
  );
  typia.assert(post);

  // 2. Create a comment on the post using valid data
  const commentInput = {
    post_id: post.id,
    review_id: null,
    parent_id: null,
    body: RandomGenerator.content()()(1),
    is_private: false,
  } satisfies IAimallBackendComment.ICreate;

  const comment =
    await api.functional.aimall_backend.seller.posts.comments.create(
      connection,
      {
        postId: post.id,
        body: commentInput,
      },
    );
  typia.assert(comment);

  // 3. Assert returned comment fields are populated
  TestValidator.equals("comment post_id matches post id")(comment.post_id)(
    post.id,
  );
  TestValidator.equals("is_private set")(comment.is_private)(
    commentInput.is_private,
  );
  TestValidator.equals("comment not deleted")(comment.deleted_at)(null);
  TestValidator.equals("body set")(comment.body)(commentInput.body);

  // 4. Fields integrity check
  TestValidator.predicate("id exists and is uuid")(
    typeof comment.id === "string" && comment.id.length > 0,
  );
  TestValidator.predicate("created_at iso string")(
    typeof comment.created_at === "string" && comment.created_at.includes("T"),
  );
  TestValidator.predicate("updated_at iso string")(
    typeof comment.updated_at === "string" && comment.updated_at.includes("T"),
  );
  // Note: Author/customer id cannot be validated directly as it is not present in response DTO.
}

