import type { IAimallBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCartItem";

/**
 * 존재하지 않는 cartItemId로 카트 아이템 업데이트 요청 시, 반드시 실패(오류)가 발생하고, cart 내 정보가 영향받지 않음을
 * 검증한다.
 *
 * [비즈니스 컨텍스트]
 *
 * - 고객 계정 신규 생성
 * - 해당 고객 카트 생성
 * - Cart에 없는(실제로 존재하지 않는 임의 uuid) cartItemId 사용하여 cart item update 시도
 *
 * [검증 Flow]
 *
 * 1. 고객 테스트 계정 생성
 * 2. 고객용 cart 생성
 * 3. Cart 내 actual cart_items_count(또는 카트 상태) 획득
 * 4. 존재하지 않는 cartItemId로 update 시도 - 반드시 예외 발생해야 함
 * 5. 이후 cart의 cart_items_count 정보가 불변임을 확인해 side effect 없음 체크
 *
 * (참고: 카트 상세/아이템 목록 재조회 API 없다면 카트 객체의 cart_items_count 기반 시나리오)
 */
export async function test_api_aimall_backend_customer_carts_cartItems_test_update_cart_item_with_invalid_cartitemid_rejected(
  connection: api.IConnection,
) {
  // 1. 고객 계정(테스트용) 생성
  const customer = await api.functional.aimall_backend.customers.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        phone: typia.random<string>(),
        password_hash: null,
        status: "active",
      },
    },
  );
  typia.assert(customer);

  // 2. 고객 cart 생성
  const cart = await api.functional.aimall_backend.customer.carts.create(
    connection,
    {
      body: {
        aimall_backend_customer_id: customer.id,
      },
    },
  );
  typia.assert(cart);

  // 3. 생성된 카트의 cart_items_count(원본) 저장
  const originalCartItemsCount = cart.cart_items_count ?? 0;

  // 4. 존재하지 않는 cartItemId(랜덤 uuid)로 update 요청하여 반드시 오류 발생해야 함
  await TestValidator.error(
    "존재하지 않는 카트아이템ID로 인한 update 실패 검증",
  )(async () => {
    await api.functional.aimall_backend.customer.carts.cartItems.update(
      connection,
      {
        cartId: cart.id,
        cartItemId: typia.random<string & tags.Format<"uuid">>(), // 실존하지 않는 cartItemId
        body: {
          quantity: 2,
          updated_at: new Date().toISOString(),
        },
      },
    );
  });

  // 5. cart_items_count(원본 값) 변동 없는지 체크(카트 상태 불변)
  TestValidator.equals("cart_items_count 불변")(originalCartItemsCount)(
    cart.cart_items_count ?? 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";
import type { IAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrderItem";
import type { IPageIAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendOrderItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Advanced search and filtering for customer order items by product ID and item
 * name substring.
 *
 * Purpose:
 *
 * - To validate advanced order item querying for a customer's order, ensuring
 *   that filtering and pagination work as intended.
 * - Since the order item schema lacks a 'status' field, we test search by
 *   'product_id' and 'item_name' substring.
 * - This simulates a customer auditing their order, including specific queries
 *   for products, names, and pagination edge cases.
 *
 * Steps:
 *
 * 1. Create a new order for a random customer, seller, and address UUID.
 * 2. Add four order items with different properties:
 *
 *    - At least two items share a product_id.
 *    - Item names include a known substring for targeted filtering.
 * 3. Search for order items by product_id and verify only matching items are
 *    returned, and others excluded.
 * 4. Search for an item using both product_id and partial item_name, expect only a
 *    single match.
 * 5. Verify search with a non-existent product_id returns an empty result set.
 * 6. Test pagination by limiting results to 2 per page and validate pagination
 *    metadata.
 */
export async function test_api_aimall_backend_customer_orders_orderItems_search_by_product_id_and_item_name(
  connection: api.IConnection,
) {
  // 1. Create a new order
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const seller_id = typia.random<string & tags.Format<"uuid">>();
  const address_id = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.aimall_backend.customer.orders.create(
    connection,
    {
      body: {
        customer_id,
        seller_id,
        address_id,
        order_status: "pending",
        total_amount: 100_000,
        currency: "KRW",
      } satisfies IAimallBackendOrder.ICreate,
    },
  );
  typia.assert(order);

  // 2. Add 4 order items: at least 2 share a product_id, all unique item_names
  const shared_product_id = typia.random<string & tags.Format<"uuid">>();
  const unique_product_id_1 = typia.random<string & tags.Format<"uuid">>();
  const unique_product_id_2 = typia.random<string & tags.Format<"uuid">>();
  // Name substring for targeted filtering
  const search_word = "SpecialItem";
  const orderItemsBuild = [
    {
      product_id: shared_product_id,
      item_name: search_word + " Alpha",
      quantity: 1,
      unit_price: 10000,
      total_price: 10000,
    },
    {
      product_id: shared_product_id,
      item_name: "Ordinary Beta",
      quantity: 2,
      unit_price: 5000,
      total_price: 10000,
    },
    {
      product_id: unique_product_id_1,
      item_name: "Gamma Thing",
      quantity: 1,
      unit_price: 8888,
      total_price: 8888,
    },
    {
      product_id: unique_product_id_2,
      item_name: "Delta Stuff",
      quantity: 3,
      unit_price: 100,
      total_price: 300,
    },
  ];
  const createdOrderItems: IAimallBackendOrderItem[] = [];
  for (const data of orderItemsBuild) {
    const orderItem =
      await api.functional.aimall_backend.customer.orders.orderItems.create(
        connection,
        {
          orderId: order.id,
          body: data satisfies IAimallBackendOrderItem.ICreate,
        },
      );
    typia.assert(orderItem);
    createdOrderItems.push(orderItem);
  }

  // 3. Search for order items by shared product_id; expect 2 results and correct filtering
  {
    const result =
      await api.functional.aimall_backend.customer.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: {
            order_id: order.id,
            product_id: shared_product_id,
          } satisfies IAimallBackendOrderItem.IRequest,
        },
      );
    typia.assert(result);
    TestValidator.equals("product_id filtered orderItems count")(
      result.data.length,
    )(2);
    for (const item of result.data) {
      TestValidator.equals("item uses correct product_id")(item.product_id)(
        shared_product_id,
      );
    }
  }

  // 4. Search by product_id and item_name matching the substring
  {
    const result =
      await api.functional.aimall_backend.customer.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: {
            order_id: order.id,
            product_id: shared_product_id,
            item_name: search_word, // substring match for item_name
          } satisfies IAimallBackendOrderItem.IRequest,
        },
      );
    typia.assert(result);
    TestValidator.equals("filtered on item_name substring")(result.data.length)(
      1,
    );
    if (result.data.length > 0) {
      const matched = result.data[0];
      TestValidator.equals("product_id")(matched.product_id)(shared_product_id);
      TestValidator.predicate("item_name contains filter")(
        matched.item_name.includes(search_word),
      );
    }
  }

  // 5. Search with non-existent product_id—expect empty result
  {
    const result =
      await api.functional.aimall_backend.customer.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: {
            order_id: order.id,
            product_id: typia.random<string & tags.Format<"uuid">>(),
          } satisfies IAimallBackendOrderItem.IRequest,
        },
      );
    typia.assert(result);
    TestValidator.equals("search for missing product_id yields empty")(
      result.data.length,
    )(0);
    TestValidator.equals("pagination reflects no data")(
      result.pagination.records,
    )(0);
  }

  // 6. Paginate by limit=2, expect 2 items and correct pagination metadata
  {
    const result =
      await api.functional.aimall_backend.customer.orders.orderItems.search(
        connection,
        {
          orderId: order.id,
          body: {
            order_id: order.id,
            limit: 2,
            page: 1,
          } satisfies IAimallBackendOrderItem.IRequest,
        },
      );
    typia.assert(result);
    TestValidator.equals("only 2 items returned")(result.data.length)(2);
    TestValidator.equals("pagination limit")(result.pagination.limit)(2);
    TestValidator.equals("pagination current")(result.pagination.current)(1);
    TestValidator.predicate("pagination total records >= 4")(
      result.pagination.records >= 4,
    );
    TestValidator.predicate("pagination total pages >= 2")(
      result.pagination.pages >= 2,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";
import type { IAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrderItem";

/**
 * 관리자 권한으로 특정 주문의 상세 주문 상품 정보를 정상적으로 조회할 수 있는지 검증합니다.
 *
 * 시나리오는 다음과 같이 전체 비즈니스 플로우를 따라갑니다:
 *
 * 1. (의존성 준비) 관리자가 새로운 주문을 생성합니다. (필수 필드: customer_id, seller_id, address_id,
 *    order_status, total_amount, currency)
 * 2. 해당 주문에 주문 상품을 1개 추가합니다. (필수 필드: product_id, product_option_id, item_name,
 *    quantity, unit_price, total_price)
 * 3. 방금 생성한 orderItem의 ID를 이용해 상세 조회 API
 *    (/aimall-backend/administrator/orders/{orderId}/orderItems/{orderItemId})를
 *    호출합니다.
 * 4. 조회 결과로 반환된 주문 상품 객체의 id, order_id, product_id, product_option_id, item_name,
 *    quantity, unit_price, total_price 각각이 최초 입력 데이터 또는 생성된 값과 일치함을 검증합니다.
 * 5. 각 단계의 결과에 대해 타입 런타임 검증(typia.assert)과 비즈니스 필드 일치 검증(TestValidator.equals)을
 *    수행하여 정확성과 모순 없는 데이터 흐름을 보장합니다.
 */
export async function test_api_aimall_backend_test_admin_retrieve_specific_order_item_detail_success(
  connection: api.IConnection,
) {
  // 1. 주문 생성 (관리자 권한)
  const orderCreateInput: IAimallBackendOrder.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    address_id: typia.random<string & tags.Format<"uuid">>(),
    order_number: undefined, // 시스템 자동 생성 위임
    order_status: "pending",
    total_amount: 100000,
    currency: "KRW",
  };
  const order = await api.functional.aimall_backend.administrator.orders.create(
    connection,
    { body: orderCreateInput },
  );
  typia.assert(order);

  // 2. 주문 상품 추가 (하나)
  const orderItemCreateInput: IAimallBackendOrderItem.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_option_id: null,
    item_name: "테스트 상품명",
    quantity: 2,
    unit_price: 50000,
    total_price: 100000,
  };
  const createdOrderItem =
    await api.functional.aimall_backend.administrator.orders.orderItems.create(
      connection,
      {
        orderId: order.id,
        body: orderItemCreateInput,
      },
    );
  typia.assert(createdOrderItem);

  // 3. 생성된 orderItemId로 상세정보 조회
  const retrievedOrderItem =
    await api.functional.aimall_backend.administrator.orders.orderItems.at(
      connection,
      {
        orderId: order.id,
        orderItemId: createdOrderItem.id,
      },
    );
  typia.assert(retrievedOrderItem);

  // 4. 응답 필드 값이 데이터 흐름과 완전히 일치하는지 검증
  TestValidator.equals("order item id 일치")(retrievedOrderItem.id)(
    createdOrderItem.id,
  );
  TestValidator.equals("order id 일치")(retrievedOrderItem.order_id)(order.id);
  TestValidator.equals("product id 일치")(retrievedOrderItem.product_id)(
    orderItemCreateInput.product_id,
  );
  TestValidator.equals("product option id 일치")(
    retrievedOrderItem.product_option_id,
  )(orderItemCreateInput.product_option_id);
  TestValidator.equals("item name 일치")(retrievedOrderItem.item_name)(
    orderItemCreateInput.item_name,
  );
  TestValidator.equals("quantity 일치")(retrievedOrderItem.quantity)(
    orderItemCreateInput.quantity,
  );
  TestValidator.equals("unit price 일치")(retrievedOrderItem.unit_price)(
    orderItemCreateInput.unit_price,
  );
  TestValidator.equals("total price 일치")(retrievedOrderItem.total_price)(
    orderItemCreateInput.total_price,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";
import type { IAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrderItem";

/**
 * Validate handling of not-found and relationship violation cases when
 * retrieving an order item as administrator.
 *
 * This test checks:
 *
 * - API returns a not found error when querying with a nonexistent orderItemId.
 * - API returns a not found or relationship violation error when querying with a
 *   valid-looking orderItemId not belonging to the orderId.
 * - No private or irrelevant information is leaked in error responses.
 *
 * Steps:
 *
 * 1. Create a baseline order (Order A) using the admin order creation endpoint.
 * 2. Attempt to retrieve an order item with a random (nonexistent) orderItemId for
 *    Order A's id; validate error response.
 * 3. Create a second baseline order (Order B).
 * 4. Attempt to retrieve an order item with a random orderItemId for Order A's id
 *    (simulating cross-order/foreign item id); validate error.
 *
 * Note: Since there is no API to list/create order items directly, random UUIDs
 * are used to simulate item ids that do not exist or do not belong to the
 * referenced order.
 */
export async function test_api_aimall_backend_administrator_orders_orderItems_test_admin_retrieve_order_item_not_found_or_wrong_order(
  connection: api.IConnection,
) {
  // 1. Create baseline order (Order A)
  const orderA =
    await api.functional.aimall_backend.administrator.orders.create(
      connection,
      {
        body: typia.random<IAimallBackendOrder.ICreate>(),
      },
    );
  typia.assert(orderA);

  // 2. Attempt to retrieve a nonexistent order item id on Order A
  await TestValidator.error("should error on nonexistent orderItemId")(
    async () => {
      await api.functional.aimall_backend.administrator.orders.orderItems.at(
        connection,
        {
          orderId: orderA.id,
          orderItemId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );

  // 3. Create second order (Order B)
  const orderB =
    await api.functional.aimall_backend.administrator.orders.create(
      connection,
      {
        body: typia.random<IAimallBackendOrder.ICreate>(),
      },
    );
  typia.assert(orderB);

  // 4. Attempt to retrieve an order item (random uuid) for Order A (simulate cross-order violation)
  await TestValidator.error(
    "should error if orderItemId belongs to different orderId",
  )(async () => {
    await api.functional.aimall_backend.administrator.orders.orderItems.at(
      connection,
      {
        orderId: orderA.id,
        orderItemId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
