        body: {
          name: parentName,
          parent_id: null,
          depth: 1,
        } satisfies IAimallBackendCategory.ICreate,
      },
    );
  typia.assert(parent);

  // 2. Create two sibling categories under parent
  const childA: IAimallBackendCategory =
    await api.functional.aimall_backend.administrator.categories.create(
