  await TestValidator.error("Duplicate sibling name update must be rejected")(
    async () => {
      await api.functional.aimall_backend.administrator.categories.update(
        connection,
        {
          categoryId: childB.id,
          body: {
            name: childA.name,
            parent_id: parent.id,
            depth: 2,
          } satisfies IAimallBackendCategory.IUpdate,
        },
      );
    },
  );
