import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendFaq } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendFaq";

/**
 * Validate retrieving the FAQ list when there are no FAQ entries in the
 * database.
 *
 * This test confirms the correct behavior of the FAQ list endpoint in a state
 * where the database is empty of FAQ entries:
 *
 * 1. Calls the FAQ list API endpoint with an empty database.
 * 2. Asserts the API response matches the IPageIAimallBackendFaq type.
 * 3. Confirms that the `data` field in the response is an empty array.
 * 4. Validates the presence and correctness of all pagination metadata fields
 *    (`current`, `limit`, `records`, `pages`) with values that logically
 *    represent an empty result set (e.g., `records` is 0, `pages` is 0 or 1).
 * 5. Ensures no schema or business logic violations occur in the empty result
 *    case.
 */
export async function test_api_aimall_backend_faqs_test_list_faq_entries_empty(
  connection: api.IConnection,
) {
  // 1. Call the FAQ list endpoint
  const output = await api.functional.aimall_backend.faqs.index(connection);
  typia.assert(output);

  // 2. Validate that data array is empty
  TestValidator.equals("no FAQ data present")(output.data.length)(0);

  // 3. Validate that pagination object exists and fields are valid
  TestValidator.predicate("pagination object present")(!!output.pagination);
  TestValidator.equals("no records should be present")(
    output.pagination.records,
  )(0);
  // Depending on system, pages may be 0 or 1 for empty state
  TestValidator.predicate("pages field is 0 or 1 for empty")(
    output.pagination.pages === 0 || output.pagination.pages === 1,
  );
  TestValidator.predicate("current page is a positive integer")(
    output.pagination.current >= 1,
  );
  TestValidator.predicate("limit is a positive integer")(
    output.pagination.limit > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendFaq } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendFaq";
import type { IPageIAimallBackendFaq } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendFaq";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate FAQ advanced search/filter by category and visibility
 * (visible=true).
 *
 * This test ensures that applying category and visibility filters to the search
 * endpoint returns only matching results, with correct pagination and ordering.
 * Also verifies that when sort_order is specified, sorting is effective.
 *
 * Steps:
 *
 * 1. Prepare test data: Create several FAQ entries spanning multiple categories
 *    and both true/false visibility using the admin creation endpoint. Some
 *    entries share category, some are unique. At least one category is used for
 *    filter testing, and at least one FAQ is hidden (visible=false) in that
 *    category.
 * 2. Search using the PATCH endpoint with category=X and visible=true.
 * 3. Validate that all returned FAQs are from the selected category and are
 *    visible.
 * 4. Ensure no hidden entries (visible=false) from the category are present in the
 *    results.
 * 5. If more than pagination limit, verify paging (page 1 vs page 2, etc.).
 * 6. If sort_order is provided for multiples in the category, ensure returned
 *    order matches.
 */
export async function test_api_aimall_backend_faqs_test_search_faqs_by_category_and_visibility(
  connection: api.IConnection,
) {
  // 1. Create FAQs spanning categories and visibility values for filter coverage
  const category1 = "category-A-" + RandomGenerator.alphaNumeric(6);
  const category2 = "category-B-" + RandomGenerator.alphaNumeric(6);

  // Create visible FAQ in category1
  const faqVisibleCat1 =
    await api.functional.aimall_backend.administrator.faqs.create(connection, {
      body: {
        question: RandomGenerator.paragraph()(),
        answer: RandomGenerator.content()()(),
        category: category1,
        sort_order: 1,
        visible: true,
      } satisfies IAimallBackendFaq.ICreate,
    });
  typia.assert(faqVisibleCat1);

  // Create invisible FAQ in category1
  const faqHiddenCat1 =
    await api.functional.aimall_backend.administrator.faqs.create(connection, {
      body: {
        question: RandomGenerator.paragraph()(),
        answer: RandomGenerator.content()()(),
        category: category1,
        sort_order: 2,
        visible: false,
      } satisfies IAimallBackendFaq.ICreate,
    });
  typia.assert(faqHiddenCat1);

  // Create visible FAQ in category2
  const faqVisibleCat2 =
    await api.functional.aimall_backend.administrator.faqs.create(connection, {
      body: {
        question: RandomGenerator.paragraph()(),
        answer: RandomGenerator.content()()(),
        category: category2,
        sort_order: 1,
        visible: true,
      } satisfies IAimallBackendFaq.ICreate,
    });
  typia.assert(faqVisibleCat2);

  // Create more visible FAQs in category1 for pagination/sorting safety
  const moreFaqsCat1 = await ArrayUtil.asyncRepeat(17)(async (i) => {
    const faq = await api.functional.aimall_backend.administrator.faqs.create(
      connection,
      {
        body: {
          question: RandomGenerator.paragraph()(),
          answer: RandomGenerator.content()()(),
          category: category1,
          sort_order: i + 3,
          visible: true,
        } satisfies IAimallBackendFaq.ICreate,
      },
    );
    typia.assert(faq);
    return faq;
  });

  // 2. Search FAQs by category1 and visible=true (expect only visible from category1)
  const searchResponse = await api.functional.aimall_backend.faqs.search(
    connection,
    {
      body: {
        category: category1,
        visible: true,
      } satisfies IAimallBackendFaq.IRequest,
    },
  );
  typia.assert(searchResponse);

  // 3. Validate results: all match category1 and visible=true
  for (const item of searchResponse.data) {
    TestValidator.equals("category matches")(item.category)(category1);
    TestValidator.equals("must be visible")(item.visible)(true);
  }
  // 4. Validate no hidden FAQ is present
  TestValidator.predicate("hidden FAQ not shown")(
    !searchResponse.data.some((x) => x.id === faqHiddenCat1.id),
  );

  // 5. Check pagination metadata (assume default or implementation limit <= 20, as we inserted 18 total visible in category1)
  TestValidator.predicate("pagination reflects count")(
    searchResponse.pagination.records >= 18 &&
      searchResponse.pagination.pages >= 1,
  );

  // 6. If more than fit on first page, page 2 returns remainder
  if (searchResponse.pagination.pages > 1) {
    // Try fetching page 2 (if logic requests page param, extend IAimallBackendFaq.IRequest accordingly)
    // Skipping paging test implementation here as current DTO IAimallBackendFaq.IRequest doesn't show paging fields.
  }

  // 7. Validate manual sorting effect if sort_order differs
  if (searchResponse.data.length > 2) {
    const sorted = [...searchResponse.data].sort(
      (a, b) => a.sort_order - b.sort_order,
    );
    const sortOrders = searchResponse.data.map((f) => f.sort_order);
    const expected = sorted.map((f) => f.sort_order);
    TestValidator.equals("sort order by sort_order ascending")(sortOrders)(
      expected,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendFaq } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendFaq";
import type { IPageIAimallBackendFaq } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendFaq";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate FAQ search returns empty results and correct pagination metadata for
 * non-matching filters.
 *
 * Ensures the advanced FAQ search endpoint correctly returns empty results and
 * appropriate pagination when no FAQs match the provided filter, covering both
 * the non-existent category scenario and the visible=true filter when all
 * inserted FAQs are invisible.
 *
 * Steps:
 *
 * 1. Create an FAQ entry with category "general" and visible set to false
 *    (admin-only/hidden).
 * 2. Search for FAQs using a category filter that does not exist
 *    ("nonexistent-category").
 *
 *    - Confirm that data is empty and pagination reports zero records/pages.
 * 3. Search for FAQs using visible=true (publicly visible only), when all entries
 *    are invisible.
 *
 *    - Confirm that data is empty and pagination reports zero records/pages.
 *
 * This test verifies both edge cases and robustness of the FAQ search endpoint
 * for empty result handling.
 */
export async function test_api_aimall_backend_faqs_test_search_faqs_with_no_results(
  connection: api.IConnection,
) {
  // 1. Create an FAQ with category="general" and visible=false
  const createdFaq =
    await api.functional.aimall_backend.administrator.faqs.create(connection, {
      body: {
        question: "How to use the feature?",
        answer: "This is how you use it...",
        category: "general",
        sort_order: 1,
        visible: false,
      } satisfies IAimallBackendFaq.ICreate,
    });
  typia.assert(createdFaq);

  // 2. Search FAQs for a non-existent category
  const categoryResult = await api.functional.aimall_backend.faqs.search(
    connection,
    {
      body: {
        category: "nonexistent-category",
      } satisfies IAimallBackendFaq.IRequest,
    },
  );
  typia.assert(categoryResult);
  TestValidator.equals("empty result for nonexistent category")(
    categoryResult.data.length,
  )(0);
  TestValidator.equals("zero records for nonexistent category")(
    categoryResult.pagination.records,
  )(0);
  TestValidator.equals("zero pages for nonexistent category")(
    categoryResult.pagination.pages,
  )(0);

  // 3. Search FAQs for visible=true when all are invisible
  const visibleResult = await api.functional.aimall_backend.faqs.search(
    connection,
    {
      body: {
        visible: true,
      } satisfies IAimallBackendFaq.IRequest,
    },
  );
  typia.assert(visibleResult);
  TestValidator.equals("empty result for visible=true when all invisible")(
    visibleResult.data.length,
  )(0);
  TestValidator.equals("zero records for visible=true when all invisible")(
    visibleResult.pagination.records,
  )(0);
  TestValidator.equals("zero pages for visible=true when all invisible")(
    visibleResult.pagination.pages,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendFaq } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendFaq";

/**
 * Validate successful retrieval of a single FAQ entity by its UUID.
 *
 * This test ensures that the FAQ retrieval endpoint correctly returns a FAQ
 * record that matches the one inserted via the admin creation API. It covers
 * data integrity, field completeness, and timestamp presence for use in detail
 * views, search, and audit.
 *
 * Step-by-step process:
 *
 * 1. Insert a FAQ entity using the admin API to ensure it exists.
 * 2. Retrieve the FAQ entity using its UUID via the user-facing endpoint.
 * 3. Assert that all fields in the retrieved record match the inserted data,
 *    including question, answer, category, sort_order, visible, and id.
 * 4. Assert that created_at and updated_at are present and ISO8601 strings.
 */
export async function test_api_aimall_backend_faqs_test_get_faq_detail_success(
  connection: api.IConnection,
) {
  // 1. Insert a FAQ entry via admin API
  const faqInput: IAimallBackendFaq.ICreate = {
    question: "What is the best way to reset my password?",
    answer:
      "You can reset your password by clicking the 'Forgot password' link at login.",
    category: "Account",
    sort_order: 10,
    visible: true,
  };

  const createdFaq: IAimallBackendFaq =
    await api.functional.aimall_backend.administrator.faqs.create(connection, {
      body: faqInput,
    });
  typia.assert(createdFaq);

  // 2. Retrieve the FAQ by its UUID via the get-by-id endpoint
  const fetchedFaq: IAimallBackendFaq =
    await api.functional.aimall_backend.faqs.at(connection, {
      faqId: createdFaq.id,
    });
  typia.assert(fetchedFaq);

  // 3. Assert all relevant business fields match what was inserted
  TestValidator.equals("question matches input")(fetchedFaq.question)(
    faqInput.question,
  );
  TestValidator.equals("answer matches input")(fetchedFaq.answer)(
    faqInput.answer,
  );
  TestValidator.equals("category matches input")(fetchedFaq.category)(
    faqInput.category,
  );
  TestValidator.equals("sort_order matches input")(fetchedFaq.sort_order)(
    faqInput.sort_order,
  );
  TestValidator.equals("visible matches input")(fetchedFaq.visible)(
    faqInput.visible,
  );
  TestValidator.equals("id matches inserted")(fetchedFaq.id)(createdFaq.id);

  // 4. Audit/logging: created_at and updated_at should be valid ISO8601 timestamps
  TestValidator.predicate("created_at is a valid ISO 8601 string")(
    !!fetchedFaq.created_at && !isNaN(Date.parse(fetchedFaq.created_at)),
  );
  TestValidator.predicate("updated_at is a valid ISO 8601 string")(
    !!fetchedFaq.updated_at && !isNaN(Date.parse(fetchedFaq.updated_at)),
  );
}

