  TestValidator.equals("SKU id 변경 없음")(updated.id)(sku.id);
  TestValidator.equals("product_id 변경 없음")(updated.product_id)(product.id);
  TestValidator.equals("sku_code 정상 변경")(updated.sku_code)(newSkuCode);
}

