) {
  // 1. seller_id(존재하는 값)를 지정하여 주문목록 조회 및 검증
  const knownSellerId = typia.random<string & tags.Format<"uuid">>(); // 실제 주문 seller_id로 대체 필요
  const result =
    await api.functional.aimall_backend.administrator.orders.search(
