import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";
import type { IAimallBackendAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAddress";
import type { IAimallBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSeller";
import type { IPageIAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendProduct";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";

/**
 * End-to-end test for creating a new customer order with valid data.
 *
 * This test ensures that an authenticated customer can create a new order when
 * all referenced entities (customer, seller, address, product) exist and all
 * required business fields are supplied, according to
 * IAimallBackendOrder.ICreate schema. The goal is to verify correct order
 * creation, auto-generation of order_number if not provided, proper linkage of
 * customer/seller/address references, and that returned order record matches
 * the input data for relevant fields.
 *
 * The workflow involves:
 *
 * 1. Register a new customer using aimall_backend.customers.create
 * 2. Create a new seller using aimall_backend.administrator.sellers.create
 * 3. Fetch a product from aimall_backend.products.index (simulate customer
 *    shopping)
 * 4. Add a delivery address for the new customer
 *    (aimall_backend.customer.customers.addresses.create)
 * 5. Submit a new order as the customer, using valid references above and
 *    realistic required fields (omit order_number to test system
 *    auto-numbering)
 * 6. Validate that the returned response includes the same data for customer_id,
 *    seller_id, address_id, order_status, total_amount, currency and a valid
 *    order_number
 * 7. Assert field types and business logic, ensuring properly linked references.
 *
 * This test confirms system compliance for happy-path order creation and
 * correct default value handling.
 */
export async function test_api_aimall_backend_test_create_order_with_valid_data_for_customer(
  connection: api.IConnection,
) {
  // 1. Register a new customer (order owner)
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPhone: string = RandomGenerator.mobile();
  const customer = await api.functional.aimall_backend.customers.create(
    connection,
    {
      body: {
        email: customerEmail,
        phone: customerPhone,
        password_hash: null,
        status: "active",
      },
    },
  );
  typia.assert(customer);

  // 2. Register a seller
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const seller =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: {
          business_name: RandomGenerator.name(),
          email: sellerEmail,
          contact_phone: RandomGenerator.mobile(),
          status: "approved",
        },
      },
    );
  typia.assert(seller);

  // 3. Fetch a product (dependency - for business context, not order payload)
  const productsPage =
    await api.functional.aimall_backend.products.index(connection);
  typia.assert(productsPage);
  TestValidator.predicate("Products available")(productsPage.data.length > 0);
  const product = RandomGenerator.pick(productsPage.data);

  // 4. Add a delivery address for the customer
  const address =
    await api.functional.aimall_backend.customer.customers.addresses.create(
      connection,
      {
        customerId: customer.id,
        body: {
          alias: "Home",
          recipient_name: RandomGenerator.name(),
          phone: RandomGenerator.mobile(),
          address_line1: RandomGenerator.paragraph()(),
          city: "Seoul",
          postal_code: (10000 + Math.floor(Math.random() * 90000)).toString(),
          country: "Korea",
          is_default: true,
        },
      },
    );
  typia.assert(address);

  // 5. Submit a new order as the customer, omitting order_number (system generates)
  const createOrderBody = {
    customer_id: customer.id,
    seller_id: seller.id,
    address_id: address.id,
    order_status: "pending",
    total_amount: 10000, // Simulated order amount
    currency: "KRW",
    // order_number omitted
  } satisfies IAimallBackendOrder.ICreate;
  const createdOrder =
    await api.functional.aimall_backend.customer.orders.create(connection, {
      body: createOrderBody,
    });
  typia.assert(createdOrder);

  // 6. Validate response matches input and business logic
  TestValidator.equals("customer_id")(createdOrder.customer_id)(customer.id);
  TestValidator.equals("seller_id")(createdOrder.seller_id)(seller.id);
  TestValidator.equals("address_id")(createdOrder.address_id)(address.id);
  TestValidator.equals("order_status")(createdOrder.order_status)("pending");
  TestValidator.equals("total_amount")(createdOrder.total_amount)(10000);
  TestValidator.equals("currency")(createdOrder.currency)("KRW");
  TestValidator.predicate("order_number generated")(
    typeof createdOrder.order_number === "string" &&
      createdOrder.order_number.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";

/**
 * Validate order creation failure cases for missing required fields as a
 * customer.
 *
 * Business context:
 *
 * - In AIMall, a customer cannot create an order without all required fields
 *   present (customer_id, seller_id, address_id, order_status, total_amount,
 *   currency).
 * - This test ensures that if required fields are omitted—such as address_id or
 *   seller_id—the API will respond with a validation error and will not create
 *   the order.
 * - Also checks that relation integrity is enforced (e.g., missing correct
 *   foreign keys), and no order is created with empty or incomplete
 *   parameters.
 *
 * Step-by-step process:
 *
 * 1. Register a new customer (precondition for order testing).
 * 2. Create a valid order with all required fields present to confirm API accepts
 *    proper input (baseline expectation).
 * 3. Try creating a new order with missing required fields (multiple negative
 *    cases): a. Omit address_id b. Omit seller_id c. Omit customer_id d. Omit
 *    currency and total_amount e. Pass empty string for order_status
 * 4. For each case, ensure API rejects invalid creation requests and no improper
 *    order is created.
 */
export async function test_api_aimall_backend_customer_orders_test_create_order_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Register a new customer (dependency)
  const customer = await api.functional.aimall_backend.customers.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        phone: "010" + typia.random<string>().slice(0, 8),
        status: "active",
      } satisfies IAimallBackendCustomer.ICreate,
    },
  );
  typia.assert(customer);

  // 2. Baseline: create valid order (should succeed)
  const validOrder = await api.functional.aimall_backend.customer.orders.create(
    connection,
    {
      body: {
        customer_id: customer.id,
        seller_id: typia.random<string & tags.Format<"uuid">>(),
        address_id: typia.random<string & tags.Format<"uuid">>(),
        order_status: "pending",
        total_amount: 10000,
        currency: "KRW",
      } satisfies IAimallBackendOrder.ICreate,
    },
  );
  typia.assert(validOrder);

  // 3a. Omit required field: address_id
  await TestValidator.error("missing address_id validation")(() =>
    api.functional.aimall_backend.customer.orders.create(connection, {
      body: {
        customer_id: customer.id,
        seller_id: typia.random<string & tags.Format<"uuid">>(),
        // address_id: omitted
        order_status: "pending",
        total_amount: 10000,
        currency: "KRW",
      } as any,
    }),
  );

  // 3b. Omit required field: seller_id
  await TestValidator.error("missing seller_id validation")(() =>
    api.functional.aimall_backend.customer.orders.create(connection, {
      body: {
        customer_id: customer.id,
        // seller_id: omitted
        address_id: typia.random<string & tags.Format<"uuid">>(),
        order_status: "pending",
        total_amount: 10000,
        currency: "KRW",
      } as any,
    }),
  );

  // 3c. Omit required field: customer_id
  await TestValidator.error("missing customer_id validation")(() =>
    api.functional.aimall_backend.customer.orders.create(connection, {
      body: {
        // customer_id: omitted
        seller_id: typia.random<string & tags.Format<"uuid">>(),
        address_id: typia.random<string & tags.Format<"uuid">>(),
        order_status: "pending",
        total_amount: 10000,
        currency: "KRW",
      } as any,
    }),
  );

  // 3d. Omit both currency and total_amount
  await TestValidator.error("missing currency and total_amount validation")(
    () =>
      api.functional.aimall_backend.customer.orders.create(connection, {
        body: {
          customer_id: customer.id,
          seller_id: typia.random<string & tags.Format<"uuid">>(),
          address_id: typia.random<string & tags.Format<"uuid">>(),
          order_status: "pending",
          // total_amount: omitted
          // currency: omitted
        } as any,
      }),
  );

  // 3e. Pass empty string for order_status
  await TestValidator.error("order_status empty validation")(() =>
    api.functional.aimall_backend.customer.orders.create(connection, {
      body: {
        customer_id: customer.id,
        seller_id: typia.random<string & tags.Format<"uuid">>(),
        address_id: typia.random<string & tags.Format<"uuid">>(),
        order_status: "", // invalid: should not be empty
        total_amount: 10000,
        currency: "KRW",
      } as any,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";

/**
 * Validate foreign key constraint enforcement when creating an order with
 * invalid references.
 *
 * This test ensures that the aimall-backend order creation API enforces strict
 * foreign key integrity. It attempts to create new orders using deliberately
 * invalid (non-existent) UUIDs for `customer_id`, `seller_id`, and
 * `address_id`. According to business rules, the system must reject such
 * orders, returning a descriptive foreign key constraint error (typically a 4xx
 * HTTP error), and must not write any data to the database catalog. No partial
 * order must be created or persisted. This test covers cases where all or each
 * reference is invalid.
 *
 * Steps:
 *
 * 1. Attempt creation with all references invalid (random UUIDs for all FK
 *    fields).
 * 2. Attempt creation with only `customer_id` invalid (other FKs still random as
 *    no fixture API).
 * 3. Attempt creation with only `seller_id` invalid (other FKs still random as no
 *    fixture API).
 * 4. Attempt creation with only `address_id` invalid (other FKs still random as no
 *    fixture API).
 * 5. Confirm that API rejects each invalid input with an explicit error
 *    (TestValidator.error).
 * 6. Note: Cannot confirm absence of partial inserts/catalog mutations as no
 *    GET/LIST API exists.
 */
export async function test_api_aimall_backend_customer_orders_test_create_order_with_invalid_foreign_keys(
  connection: api.IConnection,
) {
  // Helper: Generate a random UUID (presumed not to match any real record)
  const randomUUID = () => typia.random<string & tags.Format<"uuid">>();
  // Static valid values for required simple fields
  const order_status = "pending";
  const total_amount = 10000;
  const currency = "KRW";

  // 1. All references invalid
  await TestValidator.error("All foreign keys invalid should throw error")(() =>
    api.functional.aimall_backend.customer.orders.create(connection, {
      body: {
        customer_id: randomUUID(),
        seller_id: randomUUID(),
        address_id: randomUUID(),
        order_status,
        total_amount,
        currency,
      } satisfies IAimallBackendOrder.ICreate,
    }),
  );

  // 2. Invalid customer_id only (other FKs still random as no valid fixture API)
  await TestValidator.error(
    "Invalid customer_id foreign key should throw error",
  )(() =>
    api.functional.aimall_backend.customer.orders.create(connection, {
      body: {
        customer_id: randomUUID(),
        seller_id: randomUUID(),
        address_id: randomUUID(),
        order_status,
        total_amount,
        currency,
      } satisfies IAimallBackendOrder.ICreate,
    }),
  );

  // 3. Invalid seller_id only (other FKs still random as no valid fixture API)
  await TestValidator.error("Invalid seller_id foreign key should throw error")(
    () =>
      api.functional.aimall_backend.customer.orders.create(connection, {
        body: {
          customer_id: randomUUID(),
          seller_id: randomUUID(),
          address_id: randomUUID(),
          order_status,
          total_amount,
          currency,
        } satisfies IAimallBackendOrder.ICreate,
      }),
  );

  // 4. Invalid address_id only (other FKs still random as no valid fixture API)
  await TestValidator.error(
    "Invalid address_id foreign key should throw error",
  )(() =>
    api.functional.aimall_backend.customer.orders.create(connection, {
      body: {
        customer_id: randomUUID(),
        seller_id: randomUUID(),
        address_id: randomUUID(),
        order_status,
        total_amount,
        currency,
      } satisfies IAimallBackendOrder.ICreate,
    }),
  );
  // Note: Unable to assert database/catalog state post-failure without retrieval API
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";

/**
 * Validate that unauthenticated order creation is denied.
 *
 * Attempts to submit a new order (POST /aimall-backend/customer/orders) without
 * any authentication context. This test ensures that the system strictly
 * enforces authentication for order creation, and does not allow guests,
 * anonymous, or unauthenticated users to create orders. According to the
 * business requirement and security context, only valid customers, sellers, or
 * administrators should be able to place orders. Any attempt by an
 * unauthenticated client must be rejected by the API with an appropriate
 * authorization error (such as 401 Unauthorized).
 *
 * Steps:
 *
 * 1. Prepare a connection object with no authentication headers (simulate
 *    logged-out state).
 * 2. Build a random but valid IAimallBackendOrder.ICreate DTO.
 * 3. Attempt to create an order using the unauthenticated connection.
 * 4. Expect the API to reject the request with an authorization error. Test passes
 *    if the error is thrown, fails otherwise.
 */
export async function test_api_aimall_backend_customer_orders_test_create_order_unauthenticated_access_denied(
  connection: api.IConnection,
) {
  // 1. Prepare a random, valid order payload (fields are all required except order_number, which is optional)
  const dto: IAimallBackendOrder.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    address_id: typia.random<string & tags.Format<"uuid">>(),
    order_status: "pending",
    total_amount: typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<1000000>
    >(),
    currency: "KRW",
    // order_number is left out to trigger system auto-generation as per API description
  };

  // 2. Create an unauthenticated connection (clone connection, remove headers)
  const unauthConnection = { ...connection, headers: {} };

  // 3. Attempt the request and assert that an error (authentication error) is thrown
  await TestValidator.error("unauthenticated order creation must be denied")(
    async () => {
      await api.functional.aimall_backend.customer.orders.create(
        unauthConnection,
        {
          body: dto,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";
import type { IAimallBackendAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAddress";
import type { IAimallBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSeller";
import type { IPageIAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendProduct";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";

/**
 * Validates enforcement of unique order_number constraint on order creation in
 * the AIMall Backend Order API.
 *
 * Business context: When placing a new order, the system should enforce a
 * unique (per-table) order_number. If an explicit order_number is specified,
 * creating a second order with the same order_number (even if other details
 * differ or are for another user) must fail.
 *
 * Test process:
 *
 * 1. Create a customer for ordering.
 * 2. Create a seller (fulfiller) for the order; required for order link.
 * 3. Create an address for the customer.
 * 4. Retrieve available products; select one for the order.
 * 5. Create the first order explicitly providing a fixed order_number.
 * 6. Try to create a second order (again explicit order_number, with otherwise
 *    valid data, can be same customer or different customer), expecting it to
 *    fail with a uniqueness violation.
 * 7. Assert the first succeeds and the second fails as per the business
 *    constraint.
 *
 * The API must reject the second call with a unique/duplicate order_number
 * error, confirming business logic is correctly enforced.
 */
export async function test_api_customer_orders_test_create_order_duplicate_order_number(
  connection: api.IConnection,
) {
  // 1. Create test customer
  const customer = await api.functional.aimall_backend.customers.create(
    connection,
    {
      body: {
        email: RandomGenerator.alphabets(10) + "@test.com",
        phone: RandomGenerator.mobile(),
        password_hash: null,
