    order_id: order.id,
    shipment_address_id: address.id,
    carrier: "CJ Logistics",
    tracking_number: typia.random<string>(),
    shipment_status: "shipped",
    shipped_at: new Date().toISOString(),
    delivered_at: null,
  };
  const shipment =
