/**
 * Validate that a seller cannot delete a shipment belonging to an order they do
 * not own.
 *
 * This test verifies access control enforcement by ensuring that if a seller
 * attempts to delete a shipment for another seller's order, the operation is
 * forbidden. This simulates a scenario where business logic must deny
 * non-owning actors from manipulating fulfillment records outside their scope.
 *
 * Business Workflow Steps:
 *
 * 1. Create seller 1 (legitimate owner of the order/shipment).
 * 2. Create seller 2 (non-owner who will attempt forbidden action).
 * 3. Create a customer.
 * 4. Create a product owned by seller 1.
 * 5. Register a customer delivery address.
 * 6. Place an order for seller 1, the customer, and address.
 * 7. Under seller 1, create a shipment for the order.
 * 8. Attempt to delete the shipment as seller 2 (not the owner).
 * 9. Confirm that the system rejects the request (returns a 403 or business
 *    error).
 */
export async function test_api_aimall_backend_test_delete_shipment_by_seller_without_ownership(
  connection: api.IConnection,
) {
  // 1. Create seller 1 (owner)
  const seller1 =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: {
          business_name: RandomGenerator.name(),
          email: typia.random<string & tags.Format<"email">>(),
          contact_phone: RandomGenerator.mobile(),
          status: "approved",
        } satisfies IAimallBackendSeller.ICreate,
      },
    );
  typia.assert(seller1);

  // 2. Create seller 2 (non-owner)
  const seller2 =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: {
          business_name: RandomGenerator.name(),
          email: typia.random<string & tags.Format<"email">>(),
          contact_phone: RandomGenerator.mobile(),
          status: "approved",
        } satisfies IAimallBackendSeller.ICreate,
      },
    );
  typia.assert(seller2);

  // 3. Create a customer
  const customer = await api.functional.aimall_backend.customers.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        phone: RandomGenerator.mobile(),
        password_hash: null,
        status: "active",
      } satisfies IAimallBackendCustomer.ICreate,
    },
  );
  typia.assert(customer);

  // 4. Create a product under seller1
  const product =
    await api.functional.aimall_backend.administrator.products.create(
      connection,
      {
        body: {
          category_id: typia.random<string & tags.Format<"uuid">>(),
          seller_id: seller1.id,
          title: RandomGenerator.paragraph()(10),
          description: RandomGenerator.paragraph()(20),
          status: "active",
        } satisfies IAimallBackendProduct.ICreate,
      },
    );
  typia.assert(product);

  // 5. Register a customer delivery address
  const address =
    await api.functional.aimall_backend.customer.customers.addresses.create(
      connection,
      {
        customerId: customer.id,
        body: {
          alias: "Home",
          recipient_name: RandomGenerator.name(),
          phone: RandomGenerator.mobile(),
          address_line1: RandomGenerator.paragraph()(3),
          city: "Seoul",
          postal_code: "06236",
          country: "KOR",
          is_default: true,
        } satisfies IAimallBackendAddress.ICreate,
      },
    );
  typia.assert(address);

  // 6. Place an order for seller 1
  const order = await api.functional.aimall_backend.seller.orders.create(
    connection,
    {
      body: {
        customer_id: customer.id,
        seller_id: seller1.id,
        address_id: address.id,
        order_status: "pending",
        total_amount: 10_000,
        currency: "KRW",
      } satisfies IAimallBackendOrder.ICreate,
    },
  );
  typia.assert(order);

  // 7. Seller 1 creates a shipment for the order
  const shipment =
    await api.functional.aimall_backend.seller.orders.shipments.create(
      connection,
      {
        orderId: order.id,
        body: {
          order_id: order.id,
          shipment_address_id: address.id,
          carrier: "CJ Logistics",
          tracking_number: "1234567890",
          shipment_status: "pending",
          shipped_at: null,
          delivered_at: null,
        } satisfies IAimallBackendShipment.ICreate,
      },
    );
  typia.assert(shipment);

  // 8. Attempt to delete the shipment as seller 2 (non-owner)
  await TestValidator.error(
    "non-owner seller cannot delete another seller's shipment",
  )(async () => {
    await api.functional.aimall_backend.seller.orders.shipments.erase(
      connection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates seller's ability to search & filter review comments (privacy,
 * authorship, parent/threading, pagination) and confirms proper privacy/access
 * controls.
 *
 * This test covers the end-to-end scenario where:
 *
 * - A seller creates a new product
 * - A customer posts a review on it
 * - Multiple customers create comments (mixing public/private, different authors,
 *   and reply chains) on the review
 * - The seller authenticates and attempts advanced searches via PATCH (with all
 *   filter fields)
 * - The seller should see all comments for their product's reviews (including
 *   private), with all filters working as expected
 * - The seller is forbidden from searching comments on reviews unrelated to their
 *   product
 *
 * Steps:
 *
 * 1. Seller creates a product.
 * 2. Customer 1 posts a review for this product.
 * 3. Customer 1 and Customer 2 create multiple comments on the review:
 *
 *    - Both public and private comments.
 *    - At least one reply (with parent_id).
 * 4. Authenticate as the seller.
 * 5. Use PATCH /aimall-backend/seller/reviews/:reviewId/comments to search: a. All
 *    comments (no filters) b. Filter by customer_id (author) c. Filter by
 *    is_private d. Filter by parent_id (replies) e. Filter by body keyword f.
 *    Filter by date range (created_at_from/to) g. Check pagination (page,
 *    limit) Assert result set correctness for each filter, and that seller sees
 *    all comments (including private) for their product's review.
 * 6. As the seller, try to search comments from a review on another (unrelated)
 *    product and confirm access is denied (error/unauthorized).
 */
export async function test_api_aimall_backend_test_search_review_comments_seller_privacy_and_authorization(
  connection: api.IConnection,
) {
  // --------- PREP: Seller and Product
  // Create seller identifier (simulate seller auth implied by api connection object)
  const seller_id: string = typia.random<string & tags.Format<"uuid">>();
  const category_id: string = typia.random<string & tags.Format<"uuid">>();

  // 1. Seller creates product
  const product = await api.functional.aimall_backend.seller.products.create(
    connection,
    {
      body: {
        category_id,
        seller_id,
        title: "Test Product for Comment Search",
        status: "active",
      } satisfies IAimallBackendProduct.ICreate,
    },
  );
  typia.assert(product);

  // --------- Customers & Review
  // Simulate 2 customers
  const customer1_id: string = typia.random<string & tags.Format<"uuid">>();
  const customer2_id: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Customer 1 posts a review
  const review = await api.functional.aimall_backend.customer.reviews.create(
    connection,
    {
      body: {
        product_id: product.id,
        title: "Satisfactory Experience",
        body: "Shipping was very fast and product matched description.",
        rating: 5,
      } satisfies IAimallBackendReview.ICreate,
    },
  );
  typia.assert(review);

  // --------- Comments (via customers, both public/private, with reply threading)
  // 3. Multiple comments
  // Public root comment from customer1
  const comment1 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          body: "Really useful info!",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(comment1);

  // Private root comment from customer2
  const comment2 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          body: "Private seller feedback only.",
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(comment2);

  // Reply (public) from customer1 to comment2
  const comment3 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          parent_id: comment2.id,
          body: "Followup for seller: please check!",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(comment3);

  // Another private reply from customer2 to comment1
  const comment4 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          parent_id: comment1.id,
          body: "Private reply for seller only.",
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(comment4);

  // ------- As Seller: search comments with filters (using PATCH)
  // a) No filters: get all comments for this review (should see all, including private)
  let searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: {},
      },
    );
  typia.assert(searchRes);
  TestValidator.predicate("all 4 comments present")(
    searchRes.data.length === 4,
  );

  // b) Filter by customer_id (customer1_id):
  searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: { customer_id: customer1_id },
      },
    );
  typia.assert(searchRes);
  TestValidator.predicate("at least one comment by customer 1")(
    searchRes.data.some(
      (c) =>
        c.body.includes("Really useful info") ||
        c.body.includes("Followup for seller"),
    ),
  );

  // c) Filter by is_private true
  searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: { is_private: true },
      },
    );
  typia.assert(searchRes);
  TestValidator.predicate("both private comments present")(
    searchRes.data.length === 2 && searchRes.data.every((c) => c.is_private),
  );

  // d) Filter by parent_id (threaded replies, e.g., comment2.id)
  searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: { parent_id: comment2.id },
      },
    );
  typia.assert(searchRes);
  TestValidator.predicate("comment3 is returned as reply to comment2")(
    searchRes.data.length === 1 && searchRes.data[0].parent_id === comment2.id,
  );

  // e) Filter by body keyword ("Private seller feedback only.")
  searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: { body: "Private seller feedback only." } as any, // for demonstration, but real API would require keyword/contains search feature
      },
    );
  typia.assert(searchRes);
  TestValidator.predicate("contains specific body text")(
    searchRes.data.every((c) =>
      c.body.includes("Private seller feedback only."),
    ),
  );

  // f) Filter by created_at_from/to (using earliest and latest comment date)
  const earliest = Math.min(
    ...searchRes.data.map((c) => new Date(c.created_at).getTime()),
  );
  const latest = Math.max(
    ...searchRes.data.map((c) => new Date(c.created_at).getTime()),
  );
  // from
  searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: { created_at_from: new Date(earliest).toISOString() },
      },
    );
  typia.assert(searchRes);
  TestValidator.predicate("all comments after from-date")(
    searchRes.data.every((c) => new Date(c.created_at).getTime() >= earliest),
  );
  // to
  searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: { created_at_to: new Date(latest).toISOString() },
      },
    );
  typia.assert(searchRes);
  TestValidator.predicate("all comments before to-date")(
    searchRes.data.every((c) => new Date(c.created_at).getTime() <= latest),
  );

  // g) Pagination test: limit=2, page=1 then page=2
  searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: { limit: 2, page: 1 },
      },
    );
  typia.assert(searchRes);
  TestValidator.equals("page size == limit")(searchRes.data.length)(2);
  searchRes =
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: { limit: 2, page: 2 },
      },
    );
  typia.assert(searchRes);
  TestValidator.equals("page size == limit or less")(
    searchRes.data.length <= 2,
  )(true);

  // ------------ Negative: as seller, search unrelated review's comments
  const other_product =
    await api.functional.aimall_backend.seller.products.create(connection, {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        seller_id: typia.random<string & tags.Format<"uuid">>(),
        title: "Unrelated Product",
        status: "active",
      } satisfies IAimallBackendProduct.ICreate,
    });
  typia.assert(other_product);
  const unrelated_review =
    await api.functional.aimall_backend.customer.reviews.create(connection, {
      body: {
        product_id: other_product.id,
        title: "Great Other Product!",
        body: "I like this unrelated item.",
        rating: 4,
      } satisfies IAimallBackendReview.ICreate,
    });
  typia.assert(unrelated_review);
  await TestValidator.error(
    "seller forbidden to search comments of review for different seller's product",
  )(async () => {
    await api.functional.aimall_backend.seller.reviews.comments.search(
      connection,
      {
        reviewId: unrelated_review.id,
        body: {},
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import type { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 관리자 권한에서 리뷰 댓글 검색·필터 기능 및 소프트 삭제 적용 검증 E2E 테스트
 *
 * 이 테스트는 다음을 포괄적으로 검증합니다:
 *
 * - 여러 명의 고객이 남긴 공개/비공개·단일/답글 등 다양한 조합의 리뷰 댓글 생성
 * - Soft-delete(논리삭제)된 댓글의 기본 필터링 동작
 * - 관리자 계정으로 customer_id, is_private, parent_id, created_at 날짜필터, 페이지네이션 등 복합
 *   검색·정렬 동작
 * - 비즈니스 룰에 따라 관리자는 대부분 모두 열람 가능하고, 삭제된 댓글은 기본적으로 제외됨을 확인
 * - 잘못된 필터/페이지 파라미터 요청 등 에러 처리도 함께 검증
 *
 * **세부 절차**
 *
 * 1. 고객 ID 3개 임의 생성 (실 서비스라면 인증·회원가입이 필요하나 여기선 uuid만 가정)
 * 2. 한 고객ID로 상품 리뷰 등록
 * 3. 리뷰에 대하여 다양한 조합(공개/비공개, 루트/답글)의 댓글 3개 등록
 * 4. Soft-delete는 별도 API 존재하지 않아, deleted_at이 null/non-null 케이스는 생성 시/필터 결과로만 간접
 *    검증
 * 5. 관리자로 인증(별도 인증 API 없음) 후, 관리용 검색/필터 API를 customer_id, is_private, parent_id,
 *    created_at 등으로 수차례 호출 후 결과 검증
 * 6. 페이지네이션 및 입력값 오류(불가능한 page/limit 등) 케이스도 마지막에 체크
 */
export async function test_api_aimall_backend_administrator_reviews_comments_test_search_review_comments_admin_all_access_respects_filters_and_soft_delete(
  connection: api.IConnection,
) {
  // 1. 고객 uuid 3개 임의 준비
  const customerIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // 2. 고객A로 상품 리뷰 등록
  const review = await api.functional.aimall_backend.customer.reviews.create(
    connection,
    {
      body: {
        product_id: typia.random<string & tags.Format<"uuid">>(),
        title: "관리자 댓글 필터링 시나리오용 리뷰",
        body: "이 리뷰에는 다양한 조건의 댓글들이 달립니다.",
        rating: 5 as 5 & tags.Type<"int32">,
      },
    },
  );
  typia.assert(review);

  // 3. 다양한 조합(공개,비공개,답글) 댓글 등록
  // root: 공개, customer[0]
  const commentRoot1 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          body: "공개 댓글 sampleA",
          is_private: false,
        },
      },
    );
  typia.assert(commentRoot1);

  // root: 비공개, customer[1]
  const commentRoot2 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          body: "비공개 댓글 sampleB",
          is_private: true,
        },
      },
    );
  typia.assert(commentRoot2);

  // reply(자식) 공개, customer[2], parent_id = root1
  const commentChild1 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          parent_id: commentRoot1.id,
          body: "root1에 대한 답글",
          is_private: false,
        },
      },
    );
  typia.assert(commentChild1);

  // 4. 별도 soft-delete API는 없어 deleted_at 테스트는 생략(결과 row로만 확인)

  // 5-1. customer_id 필터
  const resultCustomer =
    await api.functional.aimall_backend.administrator.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: {
          customer_id: commentRoot2.customer_id,
        },
      },
    );
  typia.assert(resultCustomer);
  resultCustomer.data.forEach((c) =>
    TestValidator.equals("customer_id")(c.customer_id)(
      commentRoot2.customer_id,
    ),
  );

  // 5-2. is_private true 필터
  const resultPrivate =
    await api.functional.aimall_backend.administrator.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: {
          is_private: true,
        },
      },
    );
  typia.assert(resultPrivate);
  resultPrivate.data.forEach((c) =>
    TestValidator.equals("is_private true")(c.is_private)(true),
  );

  // 5-3. parent_id(스레드 필터) 조건으로 답글만 조회
  const resultParent =
    await api.functional.aimall_backend.administrator.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: {
          parent_id: commentRoot1.id,
        },
      },
    );
  typia.assert(resultParent);
  resultParent.data.forEach((c) =>
    TestValidator.equals("parent_id")(c.parent_id)(commentRoot1.id),
  );

  // 5-4. created_at_from/to 필터
  const resultCreatedAt =
    await api.functional.aimall_backend.administrator.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: {
          created_at_from: commentRoot1.created_at,
          created_at_to: commentChild1.created_at,
        },
      },
    );
  typia.assert(resultCreatedAt);

  // 5-5. 페이지네이션(limit, page)
  const limit: number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }> = 1 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const page: number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }> = 1 as number &
    tags.Type<"int32"> &
    tags.JsonSchemaPlugin<{ format: "uint32" }>;
  const resultPaging =
    await api.functional.aimall_backend.administrator.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: {
          limit,
          page,
        },
      },
    );
  typia.assert(resultPaging);
  TestValidator.equals("limit=1")(resultPaging.data.length)(1);

  // 6. 에러: 페이지 번호 초과, limit오류(허용되지 않는 값 전달)
  await TestValidator.error("잘못된 페이지 번호")(async () => {
    await api.functional.aimall_backend.administrator.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: {
          page: 10000 as number &
            tags.Type<"int32"> &
            tags.JsonSchemaPlugin<{ format: "uint32" }>,
          limit,
        },
      },
    );
  });
  await TestValidator.error("잘못된 limit")(async () => {
    await api.functional.aimall_backend.administrator.reviews.comments.search(
      connection,
      {
        reviewId: review.id,
        body: {
          limit: 0 as number &
            tags.Type<"int32"> &
            tags.JsonSchemaPlugin<{ format: "uint32" }>, // 유효범위 벗어남
        },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";

/**
 * Validate customer permissions and privacy for retrieving product review
 * comments.
 *
 * This test ensures customers can read public comments and their own comments
 * on a review, but not access private comments written by other users or
 * soft-deleted content. The workflow covers positive and negative paths for
 * review comment detail retrieval.
 *
 * Steps:
 *
 * 1. Create a new product review as a customer (customer A).
 * 2. Add several comments to that review with different privacy and authorship
 *    (customer A & B, public & private, replies).
 * 3. As customer A, attempt to fetch:
 *
 *    - Their own public comment (should succeed)
 *    - Their own private comment (should succeed)
 *    - Public comment from customer B (should succeed)
 *    - Private comment from customer B (should fail)
 *    - A reply comment (should succeed if public or visible to A)
 *    - A soft-deleted comment (should fail)
 *    - A non-existent comment (should fail)
 */
export async function test_api_aimall_backend_customer_reviews_comments_test_get_review_comment_as_customer_visibility_and_privacy(
  connection: api.IConnection,
) {
  // --- Setup: two distinct customers for authorship and privacy tests ---
  // Generate two unique customer emails.
  const customerAEmail = `customerA_${typia.random<string & tags.Format<"uuid">>()}@test.com`;
  const customerBEmail = `customerB_${typia.random<string & tags.Format<"uuid">>()}@test.com`;
  // Password can be a constant for both.
  const password = "1234!Test";

  // NOTE: Authentication API endpoints are not provided in the materials.
  // So, assume the connection parameter is already authenticated as customer A ONLY.
  // All authorship is controlled by which connection executes the request.

  // 1. Create a new product review as customer A (the current connection)
  const review = await api.functional.aimall_backend.customer.reviews.create(
    connection,
    {
      body: {
        product_id: typia.random<string & tags.Format<"uuid">>(),
        title: "E2E Test Review - Visibility",
        body: "This is a test review for comment visibility e2e.",
        rating: 5,
      } satisfies IAimallBackendReview.ICreate,
    },
  );
  typia.assert(review);

  // 2. Seed comments on the review
  // As customer A (owner)
  const ownPublicComment =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          body: "Customer A's PUBLIC comment",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(ownPublicComment);
  // Private comment from review owner
  const ownPrivateComment =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          body: "Customer A's PRIVATE comment",
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(ownPrivateComment);

  // As customer B: cannot simulate login here due to no auth API in SDK/materials.
  // So, we can only show as if acting through customer A for creation, but set up the data for the negative perm/visibility test only logically.
  // Simulate a "foreign" customer comment
  // --- We'll proceed with the test as if customer B authored it ---

  // Public foreign comment
  const foreignPublicComment =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          body: "Customer B's PUBLIC comment",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(foreignPublicComment);
  // Private foreign comment
  const foreignPrivateComment =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          body: "Customer B's PRIVATE comment",
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(foreignPrivateComment);

  // Reply to an existing comment (as customer A, to foreignPublicComment)
  const replyComment =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          parent_id: foreignPublicComment.id,
          body: "Reply from A to B's public comment",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(replyComment);

  // Soft-deleted comment simulation: cannot actually soft-delete using this SDK (no endpoint)
  // So simulate by picking an unused random id
  const softDeletedCommentId = typia.random<string & tags.Format<"uuid">>();

  // Non-existent comment id
  const nonExistentCommentId = typia.random<string & tags.Format<"uuid">>();

  // --- POSITIVE CASES ---
  // Can fetch own public comment
  const fetchedOwnPublic =
    await api.functional.aimall_backend.customer.reviews.comments.at(
      connection,
      {
        reviewId: review.id,
        commentId: ownPublicComment.id,
      },
    );
  typia.assert(fetchedOwnPublic);
  TestValidator.equals("fetched own public comment")(fetchedOwnPublic.body)(
    ownPublicComment.body,
  );
  TestValidator.equals("fetched own public is_private")(
    fetchedOwnPublic.is_private,
  )(false);
  // Can fetch own private comment
  const fetchedOwnPrivate =
    await api.functional.aimall_backend.customer.reviews.comments.at(
      connection,
      {
        reviewId: review.id,
        commentId: ownPrivateComment.id,
      },
    );
  typia.assert(fetchedOwnPrivate);
  TestValidator.equals("fetched own private comment")(fetchedOwnPrivate.body)(
    ownPrivateComment.body,
  );
  TestValidator.equals("fetched own private is_private")(
    fetchedOwnPrivate.is_private,
  )(true);
  // Can fetch foreign public comment
  const fetchedForeignPublic =
    await api.functional.aimall_backend.customer.reviews.comments.at(
      connection,
      {
        reviewId: review.id,
        commentId: foreignPublicComment.id,
      },
    );
  typia.assert(fetchedForeignPublic);
  TestValidator.equals("fetched foreign public comment")(
    fetchedForeignPublic.body,
  )(foreignPublicComment.body);
  // Can fetch reply comment
  const fetchedReply =
    await api.functional.aimall_backend.customer.reviews.comments.at(
      connection,
      {
        reviewId: review.id,
        commentId: replyComment.id,
      },
    );
  typia.assert(fetchedReply);
  TestValidator.equals("fetched reply's body")(fetchedReply.body)(
    replyComment.body,
  );

  // --- NEGATIVE CASES ---
  // Should NOT fetch foreign private comment (as customer A) -- expect forbidden/not found.
  await TestValidator.error("cannot fetch another user's private comment")(
    async () => {
      await api.functional.aimall_backend.customer.reviews.comments.at(
        connection,
        {
          reviewId: review.id,
          commentId: foreignPrivateComment.id,
        },
      );
    },
  );
  // Should NOT fetch soft-deleted comment (simulate only; cannot actually soft-delete)
  await TestValidator.error("cannot fetch soft-deleted comment")(async () => {
    await api.functional.aimall_backend.customer.reviews.comments.at(
      connection,
      {
        reviewId: review.id,
        commentId: softDeletedCommentId,
      },
    );
  });
  // Should NOT fetch non-existent comment
  await TestValidator.error("cannot fetch non-existent commentId")(async () => {
    await api.functional.aimall_backend.customer.reviews.comments.at(
      connection,
      {
        reviewId: review.id,
        commentId: nonExistentCommentId,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";

/**
 * Ensure seller access to all comments (public & private, any author) for
 * reviews on their own product, and denial for others.
 *
 * This test simulates a full review/comment thread for a product belonging to a
 * seller. It tests:
 *
 * 1. Seller can fetch comments (public, private, multiple authors, and replies) on
 *    their own product review.
 * 2. Access denied or error when fetching comment from other seller's product
 *    review.
 * 3. Error when fetching a non-existent commentId for a valid review.
 *
 * Steps:
 *
 * 1. Seller creates a product (records seller_id for later lookup).
 * 2. Two customers are simulated for comment authorship variety.
 * 3. Customer1 submits a review for the product.
 * 4. Multiple comments are authored: both public & private, by both customers,
 *    including a reply chain.
 * 5. Seller attempts to fetch each created comment individually via the
 *    seller/comments.at endpoint, confirming data integrity and visibility.
 * 6. Negative: seller tried to fetch a comment on another seller’s product (should
 *    fail: access denied/not found).
 * 7. Negative: seller attempts to fetch random nonexistent commentId (error
 *    expected).
 */
export async function test_api_aimall_backend_test_get_review_comment_as_seller_access_all_on_owned_product(
  connection: api.IConnection,
) {
  // Step 1: Seller creates a product
  const sellerId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const categoryId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const sellerProduct =
    await api.functional.aimall_backend.seller.products.create(connection, {
      body: {
        category_id: categoryId,
        seller_id: sellerId,
        title: "E2E Test Product - Seller Owned",
        description:
          "Product created for seller comment access E2E integration test.",
        status: "active",
      } satisfies IAimallBackendProduct.ICreate,
    });
  typia.assert(sellerProduct);

  // Step 2: Two customers (simulate by randomizing customer_id usage in comments)
  const customerId1: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const customerId2: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // Step 3: Customer1 creates a review for the seller's product
  const review = await api.functional.aimall_backend.customer.reviews.create(
    connection,
    {
      body: {
        product_id: sellerProduct.id,
        title: "Review E2E Test",
        body: "Full integration path to comments for seller visibility test.",
        rating: 5,
      } satisfies IAimallBackendReview.ICreate,
    },
  );
  typia.assert(review);

  // Step 4: Create multiple comments (public, private, various authors) on the review
  // Root comment by customer1 (public)
  const comment_public_cust1 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          body: "Public root comment from customer1.",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(comment_public_cust1);

  // Root comment by customer2 (private)
  const comment_private_cust2 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          body: "Private root comment from customer2.",
          is_private: true,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(comment_private_cust2);

  // Reply by customer1 to customer2's private root comment (public thread reply)
  const comment_reply_public_cust1 =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          review_id: review.id,
          parent_id: comment_private_cust2.id,
          body: "Reply from customer1 to private root (public reply).",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(comment_reply_public_cust1);

  // Step 5: As seller, fetch each created comment by commentId/reviewId
  // (Seller has right to see all on their own product's review)
  const fetched_public_cust1 =
    await api.functional.aimall_backend.seller.reviews.comments.at(connection, {
      reviewId: review.id,
      commentId: comment_public_cust1.id,
    });
  typia.assert(fetched_public_cust1);
  TestValidator.equals("public root comment matches")(fetched_public_cust1.id)(
    comment_public_cust1.id,
  );
  TestValidator.equals("review linkage")(fetched_public_cust1.review_id)(
    review.id,
  );

  const fetched_private_cust2 =
    await api.functional.aimall_backend.seller.reviews.comments.at(connection, {
      reviewId: review.id,
      commentId: comment_private_cust2.id,
    });
  typia.assert(fetched_private_cust2);
  TestValidator.equals("private root comment matches")(
    fetched_private_cust2.id,
  )(comment_private_cust2.id);
  TestValidator.equals("review linkage")(fetched_private_cust2.review_id)(
    review.id,
  );
  TestValidator.equals("privacy flag")(fetched_private_cust2.is_private)(true);

  const fetched_reply_public_cust1 =
    await api.functional.aimall_backend.seller.reviews.comments.at(connection, {
      reviewId: review.id,
      commentId: comment_reply_public_cust1.id,
    });
  typia.assert(fetched_reply_public_cust1);
  TestValidator.equals("public reply matches")(fetched_reply_public_cust1.id)(
    comment_reply_public_cust1.id,
  );
  TestValidator.equals("parent linkage")(fetched_reply_public_cust1.parent_id)(
    comment_private_cust2.id,
  );

  // Step 6: Negative - seller fetches comment for review on another seller's product
  // Create another seller and product
  const otherSellerId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const otherCategoryId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const otherProduct =
    await api.functional.aimall_backend.seller.products.create(connection, {
      body: {
        category_id: otherCategoryId,
        seller_id: otherSellerId,
        title: "Product not owned by test seller",
        status: "active",
      } satisfies IAimallBackendProduct.ICreate,
    });
  typia.assert(otherProduct);

  // Review for other seller's product
  const otherReview =
    await api.functional.aimall_backend.customer.reviews.create(connection, {
      body: {
        product_id: otherProduct.id,
        title: "Review from someone on other seller prod",
        body: "Review not for test seller product.",
        rating: 3,
      } satisfies IAimallBackendReview.ICreate,
    });
  typia.assert(otherReview);

  // Comment on the other review
  const otherComment =
    await api.functional.aimall_backend.customer.reviews.comments.create(
      connection,
      {
        reviewId: otherReview.id,
        body: {
          review_id: otherReview.id,
          body: "Other seller product comment for access denial test.",
          is_private: false,
        } satisfies IAimallBackendComment.ICreate,
      },
    );
  typia.assert(otherComment);

  // As original seller, attempt to fetch comment on another seller's product (should error)
  await TestValidator.error(
    "seller can't access unowned product's comment for review",
  )(async () => {
    await api.functional.aimall_backend.seller.reviews.comments.at(connection, {
      reviewId: otherReview.id,
      commentId: otherComment.id,
    });
  });

  // Step 7: Negative - fetch non-existent commentId for valid review
  const fakeCommentId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  await TestValidator.error("non-existent comment fetch fails")(async () => {
    await api.functional.aimall_backend.seller.reviews.comments.at(connection, {
      reviewId: review.id,
      commentId: fakeCommentId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import type { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import type { IAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAttachment";

/**
 * 테스트: 댓글 소유 고객이 첨부파일을 성공적으로 업로드하고 연결할 수 있는지 검증
 *
 * 이 테스트는 다음 시나리오를 검증합니다:
 *
 * 1. 고객이 새로운 게시글을 작성한다.
 * 2. 동일 고객이 해당 게시글에 댓글을 작성한다.
 * 3. 댓글에 이미지 첨부파일을 업로드한다.
 * 4. 생성된 첨부파일 레코드가 올바르게 댓글에 연결되고, 주요 메타데이터가 모두 저장되어 있는지 검증한다.
 *
 * ※ 인증/회원가입 관련 endpoint는 본 SDK 내에 없으므로 '고객 세션'은 connection 파라미터로 가정합니다. ※ 첨부파일
 * 조회(상세/목록) endpoint 미제공으로 반환 레코드 기반으로만 검증합니다.
 *
 * 단계별 절차:
 *
 * 1. 게시글 생성 (고객 권한)
 * 2. 게시글에 댓글 작성 (고객 권한)
 * 3. 댓글에 이미지 파일 첨부
 * 4. 첨부파일과 댓글 간 linkage, 파일 메타데이터(유형/크기/파일경로) 검증
 */
export async function test_api_aimall_backend_customer_comments_attachments_test_create_attachment_comment_as_owner_success(
  connection: api.IConnection,
