                  ? -Math.abs(typia.random<number>())
                  : Math.abs(typia.random<number>()),
              type,
              description: `${type} test transaction for ${customer}`,
              expired_at:
                type === "expiration"
                  ? new Date(Date.now() + 1e9).toISOString()
                  : null,
            } satisfies IAimallBackendLoyaltyTransaction.ICreate,
          },
        );
      typia.assert(tx);
      createdTxs.push(tx);
