import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSupportTicket";
import type { IPageIAimallBackendSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendSupportTicket";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the advanced search and paginated retrieval of support tickets by a
 * customer.
 *
 * This test ensures that after creating multiple support tickets with varying
 * statuses, priorities, and categories for a single customer, the customer can
 * search their own tickets using filter criteria (status, priority, category)
 * and pagination parameters, and gets correct results.
 *
 * Steps:
 *
 * 1. Create a unique customer UUID (requester_id) for ownership tracking.
 * 2. Create multiple support tickets (6-8) for this customer, covering
 *    combinations of status ('open', 'pending', 'closed'), priority ('high',
 *    'normal', 'urgent'), and category ('payment', 'delivery', 'account').
 * 3. Create additional tickets for a different customer requester_id, to ensure
 *    isolation.
 * 4. As the first customer, search support tickets via PATCH
 *    /aimall-backend/customer/supportTickets using filters (e.g.,
 *    status='open', priority='high', limit=2, page=1).
 * 5. Validate that all returned tickets belong to the requester_id, match the
 *    filter criteria, and pagination metadata is correct.
 * 6. Confirm that tickets from other customers are never present in the result, no
 *    matter the filter.
 * 7. Check pagination by retrieving page 2 and validating no overlaps, proper
 *    `current`, `limit`, `pages`, and `records` values.
 */
export async function test_api_aimall_backend_customer_supportTickets_test_search_support_tickets_by_customer_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Generate unique customer requester_ids for test isolation
  const requesterId = typia.random<string & tags.Format<"uuid">>();
  const otherRequesterId = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Create support tickets for test customer across status/priority/category
  const supportTicketMatrix = [
    { status: "open", priority: "high", category: "payment" },
    { status: "open", priority: "high", category: "delivery" },
    { status: "open", priority: "urgent", category: "account" },
    { status: "pending", priority: "normal", category: "delivery" },
    { status: "pending", priority: "urgent", category: "payment" },
    { status: "closed", priority: "high", category: "account" },
    { status: "closed", priority: "normal", category: "support" },
  ];
  const createdTickets = [];
  for (const props of supportTicketMatrix) {
    const ticket =
      await api.functional.aimall_backend.customer.supportTickets.create(
        connection,
        {
          body: {
            requester_id: requesterId,
            subject: `Test: ${props.status}/${props.priority}/${props.category}`,
            body: `Body content for ${props.status} + ${props.priority} + ${props.category}`,
            priority: props.priority,
            category: props.category,
          } satisfies IAimallBackendSupportTicket.ICreate,
        },
      );
    typia.assert(ticket);
    createdTickets.push(ticket);
  }

  // Step 3: Create tickets for unrelated customer to ensure filter correctness
  await api.functional.aimall_backend.customer.supportTickets.create(
    connection,
    {
      body: {
        requester_id: otherRequesterId,
        subject: `Other customer open`,
        body: `Irrelevant ticket`,
        priority: "high",
        category: "payment",
      } satisfies IAimallBackendSupportTicket.ICreate,
    },
  );

  await api.functional.aimall_backend.customer.supportTickets.create(
    connection,
    {
      body: {
        requester_id: otherRequesterId,
        subject: `Other customer pending`,
        body: `Irrelevant ticket`,
        priority: "urgent",
        category: "delivery",
      } satisfies IAimallBackendSupportTicket.ICreate,
    },
  );

  // Step 4: Customer searches their support tickets with filters/pagination
  const filterRequest: IAimallBackendSupportTicket.IRequest = {
    requester_id: requesterId,
    status: "open",
    priority: "high",
    page: 1,
    limit: 2,
  };
  const searchResult =
    await api.functional.aimall_backend.customer.supportTickets.search(
      connection,
      {
        body: filterRequest,
      },
    );
  typia.assert(searchResult);

  // Step 5: Validate results match filter and ownership
  TestValidator.predicate(
    "only tickets matching status and priority and requester_id",
  )(
    searchResult.data.every(
      (t) =>
        t.status === "open" &&
        t.priority === "high" &&
        t.requester_id === requesterId,
    ),
  );
  // Confirm no ticket from other requester_id appears
  TestValidator.predicate("no ticket of other customer")(
    searchResult.data.every((t) => t.requester_id === requesterId),
  );
  // Pagination metadata
  TestValidator.equals("pagination limit")(searchResult.pagination.limit)(2);
  TestValidator.equals("pagination current")(searchResult.pagination.current)(
    1,
  );

  // Step 6: Validate page 2 of results (if total > 2)
  if (searchResult.pagination.pages > 1) {
    const searchResultPage2 =
      await api.functional.aimall_backend.customer.supportTickets.search(
        connection,
        {
          body: { ...filterRequest, page: 2 },
        },
      );
    typia.assert(searchResultPage2);
    TestValidator.equals("pagination page 2")(
      searchResultPage2.pagination.current,
    )(2);
    // No overlapping tickets between page 1 and 2
    const idsPage1 = new Set(searchResult.data.map((t) => t.id));
    const idsPage2 = new Set(searchResultPage2.data.map((t) => t.id));
    TestValidator.predicate("no overlap between page results")(
      Array.from(idsPage1).every((id) => !idsPage2.has(id)),
    );
    // All tickets still match filters and ownership
    TestValidator.predicate("page 2 filtered/owned")(
      searchResultPage2.data.every(
        (t) =>
          t.status === "open" &&
          t.priority === "high" &&
          t.requester_id === requesterId,
      ),
    );
    TestValidator.equals("pagination limit")(
      searchResultPage2.pagination.limit,
    )(2);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSupportTicket";
import type { IPageIAimallBackendSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendSupportTicket";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates that the support ticket search endpoint returns only tickets owned
 * by the authenticated customer, regardless of filters.
 *
 * This test covers the security and isolation requirement that a customer
 * should never be able to view another customer's support tickets—even if using
 * broad or crafted filter values.
 *
 * **Test process:**
 *
 * 1. Simulate two customers by generating unique UUIDs.
 * 2. Customer A creates multiple support tickets with diverse details.
 * 3. Customer B creates a distinct ticket.
 * 4. Perform various searches as Customer A, including unfiltered and filtered
 *    cases, and confirm that only tickets owned by A are returned.
 * 5. Perform a control search as Customer B.
 *
 * At each step, assert that all tickets in the result belong only to the
 * requesting customer, regardless of filter specificity.
 */
export async function test_api_aimall_backend_customer_supportTickets_test_search_support_tickets_returns_only_customer_owned_tickets(
  connection: api.IConnection,
) {
  // 1. Simulate two customers by generating distinct UUIDs.
  const customerA_id: string = typia.random<string & tags.Format<"uuid">>();
  const customerB_id: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Customer A creates two support tickets with different subjects/category/priority.
  const ticketA1 =
    await api.functional.aimall_backend.customer.supportTickets.create(
      connection,
      {
        body: {
          requester_id: customerA_id,
          subject: "Payment issue",
          body: "CustomerA: Payment failed on order #1234.",
          priority: "urgent",
          category: "payment",
        },
      },
    );
  typia.assert(ticketA1);

  const ticketA2 =
    await api.functional.aimall_backend.customer.supportTickets.create(
      connection,
      {
        body: {
          requester_id: customerA_id,
          subject: "Shipping delay",
          body: "CustomerA: My package has not arrived.",
          priority: "high",
          category: "delivery",
        },
      },
    );
  typia.assert(ticketA2);

  // 3. Customer B creates a distinct support ticket.
  const ticketB1 =
    await api.functional.aimall_backend.customer.supportTickets.create(
      connection,
      {
        body: {
          requester_id: customerB_id,
          subject: "Product defect",
          body: "CustomerB: Received defective item.",
          priority: "normal",
          category: "product",
        },
      },
    );
  typia.assert(ticketB1);

  // 4. Customer A performs a general search: expects only their own tickets regardless of broad filter.
  {
    const result =
      await api.functional.aimall_backend.customer.supportTickets.search(
        connection,
        {
          body: {
            requester_id: customerA_id,
          },
        },
      );
    typia.assert(result);
    for (const t of result.data)
      TestValidator.equals("all tickets belong to CustomerA")(t.requester_id)(
        customerA_id,
      );
  }

  // 5. Customer A searches with a subject filter matching one ticket.
  {
    const result =
      await api.functional.aimall_backend.customer.supportTickets.search(
        connection,
        {
          body: {
            requester_id: customerA_id,
            subject: "Shipping delay",
          },
        },
      );
    typia.assert(result);
    for (const t of result.data)
      TestValidator.equals("subject search also isolates CustomerA")(
        t.requester_id,
      )(customerA_id);
  }

  // 6. Customer A searches by category, querying for a different ticket.
  {
    const result =
      await api.functional.aimall_backend.customer.supportTickets.search(
        connection,
        {
          body: {
            requester_id: customerA_id,
            category: "payment",
          },
        },
      );
    typia.assert(result);
    for (const t of result.data)
      TestValidator.equals("category filter enforces CustomerA isolation")(
        t.requester_id,
      )(customerA_id);
  }

  // 7. Control: Customer B searches and expects only their own ticket.
  {
    const result =
      await api.functional.aimall_backend.customer.supportTickets.search(
        connection,
        {
          body: {
            requester_id: customerB_id,
          },
        },
      );
    typia.assert(result);
    for (const t of result.data)
      TestValidator.equals("CustomerB sees only their ticket")(t.requester_id)(
        customerB_id,
      );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSupportTicket";
import type { IPageIAimallBackendSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendSupportTicket";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search and filtering for seller-created support tickets.
 *
 * This E2E test ensures that a seller can retrieve only their own support
 * tickets using complex filter criteria via the advanced PATCH search endpoint.
 * The test exercises filtering by status, priority, category, creation date
 * (range), and pagination. Only the seller’s own tickets should match; attempts
 * to filter on another seller’s tickets must produce empty results.
 *
 * Steps:
 *
 * 1. As a seller, generate a set of support tickets with diverse combinations of
 *    status, priority, and category.
 * 2. Choose meaningful filter criteria (e.g., status 'open', priority 'high',
 *    category 'payment', date within last 5 days).
 * 3. Query using PATCH /aimall-backend/seller/supportTickets with these filters
 *    (with pagination limit).
 * 4. Assert that results show ONLY matching tickets belonging to the seller,
 *    respecting filtering and pagination.
 * 5. Assert that searching for tickets using a different requester_id yields no
 *    results.
 */
export async function test_api_aimall_backend_seller_supportTickets_test_search_support_tickets_by_seller_with_advanced_criteria(
  connection: api.IConnection,
) {
  // 1. Generate seller identifier for ticket creation
  const seller_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Bulk create support tickets with a matrix of statuses, priorities, categories, and timestamps
  const STATUS_OPTIONS = ["open", "pending", "resolved", "closed"];
  const PRIORITY_OPTIONS = ["normal", "high", "urgent"];
  const CATEGORY_OPTIONS = ["payment", "delivery", "product", "account"];

  const createdTickets: IAimallBackendSupportTicket[] = [];
  const baseDate = new Date();

  for (const status of STATUS_OPTIONS) {
    for (const priority of PRIORITY_OPTIONS) {
      for (const category of CATEGORY_OPTIONS) {
        const created_at = new Date(
          baseDate.getTime() -
            Math.floor(Math.random() * 1000 * 60 * 60 * 24 * 10),
        ).toISOString(); // Up to 10 days ago
        const ticket =
          await api.functional.aimall_backend.seller.supportTickets.create(
            connection,
            {
              body: {
                requester_id: seller_id,
                subject: `Advanced Ticket ${status}-${priority}-${category}`,
                body: `E2E test body for ${status}/${priority}/${category}`,
                priority,
                category,
                assignee_admin_id: null,
              } satisfies IAimallBackendSupportTicket.ICreate,
            },
          );
        typia.assert(ticket);
        // Track locally for filter assertions (status/created_at used only for in-memory checks)
        createdTickets.push({ ...ticket, status, created_at });
      }
    }
  }

  // 3. Choose filter: status 'open', priority 'high', category 'payment', created in last 5 days
  const FILTER_STATUS = "open";
  const FILTER_PRIORITY = "high";
  const FILTER_CATEGORY = "payment";
  const now = new Date();
  const fiveDaysAgo = new Date(
    now.getTime() - 1000 * 60 * 60 * 24 * 5,
  ).toISOString();
  const until = now.toISOString();

  const expectedFiltered = createdTickets.filter(
    (t) =>
      t.status === FILTER_STATUS &&
      t.priority === FILTER_PRIORITY &&
      t.category === FILTER_CATEGORY &&
      t.created_at >= fiveDaysAgo &&
      t.created_at <= until,
  );

  // 4. Perform advanced search with pagination (limit 2 per page)
  const searchReq: IAimallBackendSupportTicket.IRequest = {
    requester_id: seller_id,
    status: FILTER_STATUS,
    priority: FILTER_PRIORITY,
    category: FILTER_CATEGORY,
    create_from: fiveDaysAgo,
    create_to: until,
    page: 1,
    limit: 2,
  };
  const page1 =
    await api.functional.aimall_backend.seller.supportTickets.search(
      connection,
      { body: searchReq },
    );
  typia.assert(page1);
  TestValidator.predicate(
    "all page1 results belong to seller and match filter",
  )(
    page1.data.every(
      (t) =>
        t.requester_id === seller_id &&
        t.status === FILTER_STATUS &&
        t.priority === FILTER_PRIORITY &&
        t.category === FILTER_CATEGORY &&
        t.created_at >= fiveDaysAgo &&
        t.created_at <= until,
    ),
  );
  TestValidator.equals("page1 current")(page1.pagination.current)(1);
  TestValidator.equals("page1 limit")(page1.pagination.limit)(2);

  // 5. Optionally page through more results if available
  if (page1.pagination.pages > 1) {
    const page2 =
      await api.functional.aimall_backend.seller.supportTickets.search(
        connection,
        { body: { ...searchReq, page: 2 } },
      );
    typia.assert(page2);
    TestValidator.equals("page2 current")(page2.pagination.current)(2);
    TestValidator.equals("page2 limit")(page2.pagination.limit)(2);
  }

  // 6. Search for another requester's tickets and confirm none returned
  const other_seller_id = typia.random<string & tags.Format<"uuid">>();
  const otherSearch =
    await api.functional.aimall_backend.seller.supportTickets.search(
      connection,
      {
        body: { ...searchReq, requester_id: other_seller_id },
      },
    );
  typia.assert(otherSearch);
  TestValidator.equals("no results for other seller")(otherSearch.data.length)(
    0,
  );
}

