  if (
    ticket.assignee_admin_id !== null &&
    ticket.assignee_admin_id !== undefined
  )
    TestValidator.predicate("assignee_admin_id is uuid string")(
      typeof ticket.assignee_admin_id === "string" &&
        ticket.assignee_admin_id.length > 0,
    );
}

