  await TestValidator.error("non-existent order item deletion should fail")(
    async () => {
      await api.functional.aimall_backend.administrator.orders.orderItems.erase(
        connection,
        {
          orderId: order.id,
          orderItemId: fakeOrderItemId,
        },
      );
    },
  );
}

