    snapshot.product_id,
  );
  TestValidator.equals("media_uri")(detail.media_uri)(snapshot.media_uri);
  TestValidator.equals("caption")(detail.caption)(snapshot.caption);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
