/**
 * Validate failure cases for seller adding attachments to review with invalid
 * payloads.
 *
 * Ensures that the backend correctly rejects attempts to add attachments to a
 * product review when provided invalid data. This test covers business
 * validation for content schema, MIME types, and size checks, helping to
 * enforce upload/media compliance at the API boundary.
 *
 * **Test Workflow:**
 *
 * 1. Admin creates a seller account (to simulate seller's role).
 * 2. Seller creates a product for context (though not directly used for
 *    attachment, ensures full business context).
 * 3. Create a customer (prerequisite for having a review record, though review
 *    creation is not testable here, so we randomize reviewId).
 * 4. Attempt to create a review attachment with:
 *
 *    - Unsupported MIME file_type (should fail validation)
 *    - File_size exceeding allowed maximum (should fail validation)
 *
 * For each invalid case, verifies that the API call results in a validation
 * error.
 *
 * Any scenarios requiring omission of required properties (i.e., missing
 * fields) are omitted from implementation, as such cases would cause TypeScript
 * compile-time errors and cannot be tested at runtime.
 */
export async function test_api_aimall_backend_seller_reviews_attachments_test_add_review_attachment_by_seller_invalid_payload(
  connection: api.IConnection,
) {
  // 1. Admin creates a seller account
  const seller =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: {
          business_name: RandomGenerator.alphabets(10),
          email: typia.random<string & tags.Format<"email">>(),
          contact_phone: RandomGenerator.mobile(),
          status: "approved",
        },
      },
    );
  typia.assert(seller);

  // 2. Seller creates a product (business context)
  const product = await api.functional.aimall_backend.seller.products.create(
    connection,
    {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        seller_id: seller.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        main_thumbnail_uri: undefined,
        status: "active",
      },
    },
  );
  typia.assert(product);

  // 3. Customer registration (to enable review context—review not creatable, so random reviewId is used)
  const customer = await api.functional.aimall_backend.customers.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        phone: RandomGenerator.mobile(),
        password_hash: RandomGenerator.alphabets(40),
        status: "active",
      },
    },
  );
  typia.assert(customer);

  // Mock/re-use a reviewId as review creation endpoint is not provided
  const reviewId = typia.random<string & tags.Format<"uuid">>();

  // 4a. Unsupported file_type (e.g., not in allowed MIME type list)
  await TestValidator.error("unsupported file_type must fail")(async () => {
    await api.functional.aimall_backend.seller.reviews.attachments.create(
      connection,
      {
        reviewId,
        body: {
          file_uri: "s3://bucket/fakefile.txt",
          file_type: "text/unknown-type",
          file_size: 1024,
          review_id: reviewId,
        },
      },
    );
  });

  // 4b. file_size too large (practical max size violation)
  await TestValidator.error("file_size too large must fail")(async () => {
    await api.functional.aimall_backend.seller.reviews.attachments.create(
      connection,
      {
        reviewId,
        body: {
          file_uri: "s3://bucket/bigfile.jpg",
          file_type: "image/jpeg",
          file_size: 10_000_000_000, // 10 GB, exceeds practical/allowed
          review_id: reviewId,
        },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";
import type { IAimallBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSeller";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAttachment";

/**
 * 검증: 판매자는 자신 제품이 아닌 리뷰에 첨부 파일을 추가할 수 없다.
 *
 * 비즈니스 시나리오:
 *
 * 1. 서로 다른 정보로 Seller 2명을 생성 (관리자 엔드포인트 이용)
 * 2. 각 Seller로 Product를 하나씩 생성
 * 3. Customer 1명이 첫 Seller의 Product에 대해 리뷰를 작성했다고 가정 (실제 엔드포인트 부재로 uuid만 생성)
 * 4. 두 번째 Seller가 첫 Seller의 리뷰(reviewId)로 첨부파일 추가를 시도
 * 5. 403 Forbidden(권한 없음)이 발생하는지 확인 (TestValidator.error 사용)
 *
 * ※ 실제 리뷰 생성 엔드포인트 및 인증 API가 제공되지 않아, 리뷰 UUID 생성 및 비정상 정상 시나리오 검증 위주로 테스트 구현
 */
export async function test_api_aimall_backend_seller_reviews_attachments_test_add_review_attachment_by_seller_to_unrelated_review_denied(
  connection: api.IConnection,
) {
  // 1. Seller 2명 등록 (관리자 엔드포인트)
  const seller1 =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: {
          business_name: RandomGenerator.name(),
          email: typia.random<string & tags.Format<"email">>(),
          contact_phone: RandomGenerator.mobile(),
          status: "active",
        } satisfies IAimallBackendSeller.ICreate,
      },
    );
  typia.assert(seller1);

  const seller2 =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: {
          business_name: RandomGenerator.name(),
          email: typia.random<string & tags.Format<"email">>(),
          contact_phone: RandomGenerator.mobile(),
          status: "active",
        } satisfies IAimallBackendSeller.ICreate,
      },
    );
  typia.assert(seller2);

  // 2. 각 Seller로 Product 생성 (각기 다른 seller_id)
  const product1 = await api.functional.aimall_backend.seller.products.create(
    connection,
    {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        seller_id: seller1.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        status: "active",
      } satisfies IAimallBackendProduct.ICreate,
    },
  );
  typia.assert(product1);

  const product2 = await api.functional.aimall_backend.seller.products.create(
    connection,
    {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        seller_id: seller2.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        status: "active",
      } satisfies IAimallBackendProduct.ICreate,
    },
  );
  typia.assert(product2);

  // 3. (실제 리뷰 엔드포인트 없음) 리뷰의 UUID 생성 (customer가 product1에 리뷰 작성했다고 가정)
  const reviewId = typia.random<string & tags.Format<"uuid">>();

  // 4. seller2가 seller1의 상품 리뷰(reviewId)에 파일 첨부 시도
  await TestValidator.error(
    "권한 없는 판매자가 타 리뷰에 첨부파일 추가 시 403",
  )(async () => {
    await api.functional.aimall_backend.seller.reviews.attachments.create(
      connection,
      {
        reviewId: reviewId,
        body: {
          post_id: null,
          comment_id: null,
          review_id: reviewId,
          file_uri: `s3://dummy/${typia.random<string & tags.Format<"uuid">>()}.jpg`,
          file_type: "image/jpeg",
          file_size: 123456,
        } satisfies IAimallBackendAttachment.ICreate,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";
import type { IAimallBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSeller";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAttachment";

/**
 * 관리자 권한으로 상품 리뷰에 첨부파일 추가 기능을 검증합니다.
 *
 * - 판매자 계정 생성 (최소 required 필드)
 * - 해당 판매자가 상품 등록 (category_id는 UUID 랜덤)
 * - 고객 회원 가입
 * - 고객이 상품에 대한 리뷰 작성
 * - 관리자가 해당 리뷰에 파일 첨부(첨부파일 엔티티 연관성 및 메타데이터 검증)
 *
 * 검증 포인트:
 *
 * - 반환된 첨부파일의 review_id가 대상 리뷰와 일치하는지
 * - Post_id, comment_id는 null임을 확인(잘못된 엔티티 연결 방지)
 * - File_uri, file_type, file_size, created_at 등 메타데이터
 *
 * Steps:
 *
 * 1. 판매자 생성 (IAimallBackendSeller.ICreate)
 * 2. 상품 등록 (IAimallBackendProduct.ICreate)
 * 3. 고객 생성 (IAimallBackendCustomer.ICreate)
 * 4. 리뷰 생성 (IAimallBackendReview.ICreate)
 * 5. 관리자가 첨부파일 등록
 * 6. 첨부파일의 반환값 및 메타 정보/연관성 종합 검증
 */
export async function test_api_aimall_backend_administrator_reviews_attachments_test_add_review_attachment_by_admin_success(
  connection: api.IConnection,
) {
  // 1. 판매자 생성
  const seller =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: {
          business_name: RandomGenerator.name(),
          email: typia.random<string & tags.Format<"email">>(),
          contact_phone: RandomGenerator.mobile(),
          status: "approved",
        },
      },
    );
  typia.assert(seller);

  // 2. 상품 등록 (해당 판매자)
  const product = await api.functional.aimall_backend.seller.products.create(
    connection,
    {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        seller_id: seller.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        status: "active",
      },
    },
  );
  typia.assert(product);

  // 3. 고객 회원가입
  const customer = await api.functional.aimall_backend.customers.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        phone: RandomGenerator.mobile(),
        password_hash: "hashed_password_example",
        status: "active",
      },
    },
  );
  typia.assert(customer);

  // 4. 리뷰 작성 (고객 → 해당 상품)
  const review = await api.functional.aimall_backend.customer.reviews.create(
    connection,
    {
      body: {
        product_id: product.id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        rating: 5,
      },
    },
  );
  typia.assert(review);

  // 5. 관리자가 리뷰에 첨부파일 등록
  const fileUri = `s3://test-bucket/${typia.random<string & tags.Format<"uuid">>()}.jpg`;
  const fileType = "image/jpeg";
  const fileSize = 60102;
  const attachment =
    await api.functional.aimall_backend.administrator.reviews.attachments.create(
      connection,
      {
        reviewId: review.id,
        body: {
          post_id: null,
          comment_id: null,
          review_id: review.id,
          file_uri: fileUri,
          file_type: fileType,
          file_size: fileSize,
        },
      },
    );
  typia.assert(attachment);

  // 6. 첨부파일 반환값 필드 및 연관성 검증
  TestValidator.equals("review_id 일치")(attachment.review_id)(review.id);
  TestValidator.equals("post_id는 null")(attachment.post_id)(null);
  TestValidator.equals("comment_id는 null")(attachment.comment_id)(null);
  TestValidator.equals("file_uri 일치")(attachment.file_uri)(fileUri);
  TestValidator.equals("file_type 일치")(attachment.file_type)(fileType);
  TestValidator.equals("file_size 일치")(attachment.file_size)(fileSize);
  TestValidator.predicate("created_at 필수 문자열")(
    typeof attachment.created_at === "string" &&
      attachment.created_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";
import type { IAimallBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSeller";
