import type { IAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAttachment";

/**
 * 관리자 리뷰 첨부파일 POST 엔드포인트의 비정상/비준수 payload 거부 검증
 *
 * - 이 테스트는 판매자, 상품 선행 생성 후 (시스템 review entity 생성 API 미노출 시, mock reviewId 사용)
 * - 첨부파일 생성 API에 잘못된 payload(필수 필드 누락/허용되지 않는 파일 타입/불가 파일 사이즈/존재하지 않는 리뷰 ID)를 입력
 * - 엔드포인트가 DTO 및 비즈니스 제약조건 위반 payload를 error와 함께 정확히 거부하는지 확인함.
 * - 각각의 시나리오 (필수 필드 누락, 불허 file_type, file_size 오류, FK 오류)에 대해
 *   TestValidator.error로 런타임 오류 반환을 검증
 *
 * 테스트 목적:
 *
 * 1. 스키마/제약조건 위반 입력 값을 가진 요청이 거절되는지 검증
 * 2. 시스템의 입력 검증 엄격성 및 방어적 코딩 신뢰성 확인
 */
export async function test_api_aimall_backend_administrator_reviews_attachments_test_add_review_attachment_admin_invalid_payload(
  connection: api.IConnection,
) {
  // 1. 판매자 선행 생성 (상품 컨텍스트 연동 목적)
  const seller =
    await api.functional.aimall_backend.administrator.sellers.create(
      connection,
      {
        body: {
          business_name: RandomGenerator.name(),
          email: typia.random<string & tags.Format<"email">>(),
          contact_phone: RandomGenerator.mobile(),
          status: "approved",
        } satisfies IAimallBackendSeller.ICreate,
      },
    );
  typia.assert(seller);

  // 2. 상품 선행 생성 (review 컨텍스트 가정)
  const product = await api.functional.aimall_backend.seller.products.create(
    connection,
    {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        seller_id: seller.id,
        title: RandomGenerator.paragraph()(),
        status: "active",
        description: RandomGenerator.content()()(),
        main_thumbnail_uri: undefined,
      } satisfies IAimallBackendProduct.ICreate,
    },
  );
  typia.assert(product);

  // 3. 테스트용 mock reviewId — 실제 연결 review 생성 API 미노출 시 가상 사용 (존재할 가능성 높음)
  const reviewId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // CASE 1. 필수 필드 file_uri 누락된 payload → 오류 발생 검증
  await TestValidator.error("필수 file_uri 누락시 거부")(() =>
    api.functional.aimall_backend.administrator.reviews.attachments.create(
      connection,
      {
        reviewId,
        body: {
          // file_uri: undefined intentionally omitted
          file_type: "image/png",
          file_size: 1024,
          review_id: reviewId,
          post_id: null,
          comment_id: null,
        } as any,
      },
    ),
  );

  // CASE 2. 허용되지 않는 file_type("application/x-malware") 지정 시 거부
  await TestValidator.error("불허 file_type 거부")(() =>
    api.functional.aimall_backend.administrator.reviews.attachments.create(
      connection,
      {
        reviewId,
        body: {
          file_uri: "s3://bucket/uuid-malware.png",
          file_type: "application/x-malware",
          file_size: 2048,
          review_id: reviewId,
          post_id: null,
          comment_id: null,
        } satisfies IAimallBackendAttachment.ICreate,
      },
    ),
  );

  // CASE 3. file_size 0(불가) → 오류 발생 검증
  await TestValidator.error("file_size 0 거부")(() =>
    api.functional.aimall_backend.administrator.reviews.attachments.create(
      connection,
      {
        reviewId,
        body: {
          file_uri: "s3://bucket/uuid-zero.bin",
          file_type: "application/pdf",
          file_size: 0,
          review_id: reviewId,
          post_id: null,
          comment_id: null,
        } satisfies IAimallBackendAttachment.ICreate,
      },
    ),
  );

  // CASE 4. 존재하지 않는 reviewId 전달 시 오류 발생
  await TestValidator.error("존재하지 않는 reviewId시 거부")(() =>
    api.functional.aimall_backend.administrator.reviews.attachments.create(
      connection,
      {
        reviewId: typia.random<string & tags.Format<"uuid">>(), // 실제 연결 review 미존재 예상
        body: {
          file_uri: "s3://bucket/uuid-notfound.png",
          file_type: "image/png",
          file_size: 12345,
          review_id: reviewId,
          post_id: null,
          comment_id: null,
        } satisfies IAimallBackendAttachment.ICreate,
      },
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAttachment";

/**
 * Test uploading an attachment as admin to a non-existent review.
 *
 * This test ensures that when an administrator attempts to upload a file
 * attachment to a product review that does not exist (using a random UUID as
 * reviewId), the endpoint responds with a 404 Not Found error and no attachment
 * record is created.
 *
 * Steps:
 *
 * 1. Generate a random UUID to serve as a non-existent reviewId.
 * 2. Build a valid attachment payload, pointing review_id to that UUID.
 * 3. Attempt to upload the attachment as admin, expecting an error.
 * 4. Assert that the error is thrown (and is not a success response).
 */
export async function test_api_aimall_backend_administrator_reviews_attachments_test_add_review_attachment_admin_to_nonexistent_review(
  connection: api.IConnection,
) {
  // 1. Generate non-existent review ID.
  const nonexistentReviewId: string = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. Prepare a valid attachment payload (with review_id set to non-existent ID).
  const attachmentPayload: IAimallBackendAttachment.ICreate = {
    review_id: nonexistentReviewId,
    post_id: null,
    comment_id: null,
    file_uri: `s3://test/${typia.random<string & tags.Format<"uuid">>()}.jpg`,
    file_type: "image/jpeg",
    file_size: 12345,
  } satisfies IAimallBackendAttachment.ICreate;

  // 3 & 4. Attempt upload, expecting a 404 error (HttpError)
  await TestValidator.error("Uploading to non-existent review triggers 404")(
    async () => {
      await api.functional.aimall_backend.administrator.reviews.attachments.create(
        connection,
        {
          reviewId: nonexistentReviewId,
          body: attachmentPayload,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";
import type { IAimallBackendReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendReview";
import type { IPageIAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSnapshot";

/**
 * 관리자 권한으로 특정 리뷰(reviewId)에 연결된 모든 스냅샷(medias)을 정상적으로 조회하는 플로우를 검증합니다.
 *
 * 1. 신규 고객을 등록합니다 (고객 계정 생성).
 * 2. 고객으로 상품 리뷰를 작성합니다.
 * 3. 관리자 권한으로, 해당 리뷰에 스냅샷(사진/미디어)들을 여러 개 등록합니다.
 * 4. 관리자 권한으로 리뷰에 연결된 스냅샷 목록을 조회합니다.
 * 5. 응답에 등록한 스냅샷들이 모두 포함되어 있고, 각 스냅샷이 스키마상 필수 필드를 정상적으로 포함하는지 검증합니다.
 */
export async function test_api_aimall_backend_administrator_reviews_snapshots_index_test_retrieve_all_snapshots_for_review_successfully_as_admin(
  connection: api.IConnection,
) {
  // 1. 신규 고객을 등록합니다.
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customer: IAimallBackendCustomer =
    await api.functional.aimall_backend.customers.create(connection, {
      body: {
        email: customerEmail,
        phone: RandomGenerator.mobile(),
        status: "active",
      },
    });
  typia.assert(customer);

  // 2. 고객으로서 상품 리뷰를 등록합니다. (임의 product_id 사용)
  const review: IAimallBackendReview =
    await api.functional.aimall_backend.customer.reviews.create(connection, {
      body: {
        product_id: typia.random<string & tags.Format<"uuid">>(),
        title: "관리자 스냅샷 테스트",
        body: "스냅샷 API E2E 테스트 시나리오.",
        rating: 5,
      },
    });
  typia.assert(review);

  // 3. 관리자 권한으로 해당 리뷰에 여러 스냅샷 등록
  const snapshots: IAimallBackendSnapshot[] = [];
  for (let i = 0; i < 3; ++i) {
    const snapshot =
      await api.functional.aimall_backend.administrator.reviews.snapshots.create(
        connection,
        {
          reviewId: review.id,
          body: {
            media_uri: `https://cdn.example.com/image/test-${i + 1}.jpg`,
            caption: `테스트 이미지 #${i + 1}`,
            created_at: new Date().toISOString(),
          },
        },
      );
    typia.assert(snapshot);
    snapshots.push(snapshot);
  }

  // 4. 스냅샷 전체 목록 조회 (관리자 권한)
  const page =
    await api.functional.aimall_backend.administrator.reviews.snapshots.index(
      connection,
      {
        reviewId: review.id,
      },
    );
  typia.assert(page);

  // 5. 응답 검증: 등록한 스냅샷이 모두 포함됐는지, 필드가 정상적으로 존재하는지 체크
  // (id, media_uri, created_at 등 필수스키마 검사)
  TestValidator.equals("스냅샷 개수 일치")(page.data?.length)(snapshots.length);
  snapshots.forEach((item) => {
    const found = page.data?.find((s) => s.id === item.id);
    TestValidator.predicate(`스냅샷(id=${item.id}) 존재 여부`)(!!found);
    TestValidator.equals("이미지 위치 일치")(found?.media_uri)(item.media_uri);
    TestValidator.equals("등록일시 일치")(found?.created_at)(item.created_at);
  });
}

