  // 3. Admin searches for attachments by file_type=image/png
  const searchResult =
    await api.functional.aimall_backend.administrator.attachments.search(
      connection,
      {
        body: {
          file_type: imageType,
          limit: 10,
          page: 1,
        },
      },
    );
