import type { IAimallBackendCouponRedemption } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCouponRedemption";

/**
 * Validate that attempts to update immutable fields of a coupon redemption
 * record are rejected.
 *
 * Coupon redemption records should have immutable analytic/audit keys such as
 * coupon_id and customer_id. This test creates a coupon and a coupon
 * redemption, then attempts to update the redemption with non-permitted fields
 * (coupon_id/customer_id). It expects the API to reject these updates and
 * return a validation error. This ensures business logic enforcement and
 * audit/relational integrity.
 *
 * Test Steps:
 *
 * 1. Create a coupon associated with a new campaign and customer (if needed)
 * 2. Create a coupon redemption event for that coupon and customer
 * 3. Attempt to update the redemption record's coupon_id
 *
 *    - Expect a validation error or rejection response
 * 4. Attempt to update the redemption record's customer_id
 *
 *    - Expect a validation error or rejection response
 * 5. Attempt a valid, allowed update (such as redemption_status or order_id)
 *
 *    - Expect success
 *
 * Steps 3 and 4 validate that changes to analytic/audit columns are not
 * allowed. Step 5 confirms that allowed fields can still be updated as
 * expected.
 */
export async function test_api_aimall_backend_administrator_couponRedemptions_test_update_coupon_redemption_non_mutable_fields_rejected(
  connection: api.IConnection,
) {
  // 1. Create a coupon (with a new random campaign)
  const campaignId = typia.random<string & tags.Format<"uuid">>();
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const coupon =
    await api.functional.aimall_backend.administrator.coupons.create(
      connection,
      {
        body: {
          discount_campaign_id: campaignId,
          customer_id: customerId,
          code: RandomGenerator.alphaNumeric(10),
          status: "issued",
          issued_at: new Date().toISOString(),
          expires_at: new Date(
            Date.now() + 7 * 24 * 60 * 60 * 1000,
          ).toISOString(),
        },
      },
    );
  typia.assert(coupon);

  // 2. Create a coupon redemption for that coupon and customer
  const redemption =
    await api.functional.aimall_backend.administrator.couponRedemptions.create(
      connection,
      {
        body: {
          coupon_id: coupon.id,
          customer_id: customerId,
          discount_campaign_id: campaignId,
          redeemed_at: new Date().toISOString(),
          redemption_status: "success",
          order_id: null,
          product_id: null,
        },
      },
    );
  typia.assert(redemption);

  // 3. Attempt to update immutable coupon_id (expect error)
  await TestValidator.error("cannot update coupon_id")(() =>
    api.functional.aimall_backend.administrator.couponRedemptions.update(
      connection,
      {
        couponRedemptionId: redemption.id,
        // Type casting only for runtime test: coupon_id is NOT in the update DTO
        body: {
          coupon_id: typia.random<string & tags.Format<"uuid">>(),
        } as any,
      },
    ),
  );

  // 4. Attempt to update immutable customer_id (expect error)
  await TestValidator.error("cannot update customer_id")(() =>
    api.functional.aimall_backend.administrator.couponRedemptions.update(
      connection,
      {
        couponRedemptionId: redemption.id,
        // Type casting only for runtime test: customer_id is NOT in the update DTO
        body: {
          customer_id: typia.random<string & tags.Format<"uuid">>(),
        } as any,
      },
    ),
  );

  // 5. Valid allowed update
  const updated =
    await api.functional.aimall_backend.administrator.couponRedemptions.update(
      connection,
      {
        couponRedemptionId: redemption.id,
        body: { redemption_status: "failed" },
      },
    );
  typia.assert(updated);
  TestValidator.equals("status updated")(updated.redemption_status)("failed");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAimallBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCustomer";
import type { IAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProduct";
import type { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";

/**
 * Test updating an order as an administrator.
 *
 * This E2E test ensures that an administrator can successfully update an order
 * using the admin API. It covers the following business flow:
 *
 * 1. Create a customer (prerequisite for the order)
 * 2. Create a product (to assign proper foreign keys; uses test UUIDs for category
 *    and seller fields)
 * 3. Create an order using the new customer and product
 * 4. Update mutable fields on the order (e.g., order_status, total_amount)
 * 5. Validate changes are reflected in the updated order
 * 6. Confirm that unchanged fields did not change
 * 7. Ensure the updated_at audit field is properly updated
 */
export async function test_api_aimall_backend_administrator_orders_test_update_order_successfully_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a customer for the order
  const customer = await api.functional.aimall_backend.customers.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        phone: RandomGenerator.mobile(),
        password_hash: "hashedpassword123", // Dummy hash for testing only (do not use in prod)
        status: "active",
      } satisfies IAimallBackendCustomer.ICreate,
    },
  );
  typia.assert(customer);

  // 2. Create a product (needs a valid seller and category ID)
  const product =
    await api.functional.aimall_backend.administrator.products.create(
      connection,
      {
        body: {
          category_id: typia.random<string & tags.Format<"uuid">>(),
          seller_id: typia.random<string & tags.Format<"uuid">>(),
          title: RandomGenerator.paragraph()(1),
          status: "active",
        } satisfies IAimallBackendProduct.ICreate,
      },
    );
  typia.assert(product);

  // 3. Create an order for the customer and product
  const order = await api.functional.aimall_backend.administrator.orders.create(
    connection,
    {
      body: {
        customer_id: customer.id,
        seller_id: product.seller_id,
        address_id: typia.random<string & tags.Format<"uuid">>(),
        order_status: "pending",
        total_amount: 30000,
        currency: "KRW",
      } satisfies IAimallBackendOrder.ICreate,
    },
  );
  typia.assert(order);

  // 4. Update order's mutable fields: order_status and total_amount
  const new_status = "paid";
  const new_total_amount = order.total_amount + 5000;
  const updated_at = new Date().toISOString();
  const updated =
    await api.functional.aimall_backend.administrator.orders.update(
      connection,
      {
        orderId: order.id,
        body: {
          order_status: new_status,
          total_amount: new_total_amount,
          updated_at,
        } satisfies IAimallBackendOrder.IUpdate,
      },
    );
  typia.assert(updated);

  // 5. Validate updated fields are changed
  TestValidator.equals("order_status should be updated")(updated.order_status)(
    new_status,
  );
  TestValidator.equals("total_amount should be updated")(updated.total_amount)(
    new_total_amount,
  );

  // 6. Unchanged fields remain the same
  TestValidator.equals("order id matches")(updated.id)(order.id);
  TestValidator.equals("customer id unchanged")(updated.customer_id)(
    order.customer_id,
  );
  TestValidator.equals("seller id unchanged")(updated.seller_id)(
    order.seller_id,
  );
  TestValidator.equals("currency unchanged")(updated.currency)(order.currency);

  // 7. Confirm updated_at reflects correct update timestamp
  TestValidator.predicate("updated_at advanced or equal")(
    new Date(updated.updated_at).getTime() >=
      new Date(order.updated_at).getTime(),
  );
}

