    currency: "KRW",
    paid_at: new Date().toISOString(),
    transaction_id: `TXN-${Date.now()}`,
  };
  const payment =
    await api.functional.aimall_backend.seller.orders.payments.create(
      connection,
      {
        orderId: order.id,
        body: paymentCreateInput,
      },
